  aiMessages:   {kind:'list',   prefix:'am', step:'1.1', label:'What leaders have said AI is for', nameField:'said', redraw:['said','title'], fields:{title:'text (the message title shown on its card)', date:'YYYY-MM (month and year)', channel:'text', audience:'text', audienceOther:'text (the Please specify text when audience is other)', said:'text'}},
  aiUses:       {kind:'list',   prefix:'us', nameField:'name', redraw:['name'], step:'1.1, 3.4 or the Register', label:'AI uses', fields:{name:'text', status:'status key (CUL_USE_STATUS)', sanctioned:'sanctioned key (CUL_USE_SANC)', teams:'array of team ids', roles:'array of role ids (the shared roles list)', changeKind:'change key (CUL_USE_CHANGE)', changeKindOther:'text (what it changes, when Other is chosen) (Paul, final pass)', told:'text (what people were told)', overrideWho:'text (who may override its results; required before its deployment review is logged) (Paul, 26 Oct 2026)', overrideRecorded:'text (how overrides of its results are recorded; required before its deployment review is logged)', statusHistory:'array of dated entries'}},
  useReviews:   {kind:'list',   prefix:'ur', step:'3.4 or the Register', label:'Deployment reviews of AI uses', fields:{proceedReason:'text (why it goes ahead despite a poor fit or people not ready; 20 Oct 2026)', useId:'id of aiUses', date:'YYYY-MM-DD', parts:'object: culture {q1,q2,q3: {answer, verdict}}, room {map, better, needs, transparency, transparencyNote}, identity {says, ready, readyNote}, assumptions {text, fit, fitNote}', decision:'proceed, proceedChanges, pause or stop', changesRequired:'text, for proceedChanges', decidedBy:'text, a role', humanInRoom:'text, a role (no longer asked, 1 Nov 2026)', stopReason:'text, why a Stop decision stops the deployment (1 Nov 2026)', overrideCheck:'adequate or revised: whether the AI use\'s override rules were confirmed or revised at this review (1 Nov 2026)'}},
  roleImpact:   {kind:'list',   prefix:'ri', step:'2.5', label:'Role impact', fields:{roleId:'id of roles', teams:'array of team ids', changing:'text', support:'text', decisionStatus:'text', commitment:'text', tellWho:'text (who will tell people in this role what is changing)', tellHow:'text (how they will be told)', tellDate:'YYYY-MM-DD (the delivery date)', tellCheck:'object keyed by CUL_CP_CHECK key (true): the message checked before it goes out', tellDone:'boolean (delivered; 20 Oct 2026)',status:'proposed, agreed, inPlace or stopped (lifecycle, ruling 90; absent means read from the record\'s own state)'}},
  reviewSettings: {kind:'record', prefix:'rvs', step:'dashboard', label:'Culture Review settings', fields:{quarterlyFirst:'YYYY-MM-DD (the first quarterly review, until one is logged)', annualFirst:'YYYY-MM-DD (the first annual review, until one is logged)', quarterlyAttendees:'array of text, a name or a role each', annualAttendees:'array of text, a name or a role each'}}, /* Paul (20 Oct 2026): the family's review Settings */
  gate:         {kind:'record', prefix:'gt', step:'3.4', label:'Which AI uses need a review', redraw:['kindsReviewed'], fields:{kindsReviewed:'array of CUL_USE_CHANGE keys (the rule: a use that is in use or in pilot and changes people\'s work in one of these ways has a culture review before it goes ahead) (Paul, 27 Oct 2026: the rule card boiled down)'}},
