  conversations:{kind:'list',   prefix:'cv', step:'1.3', label:'Senior-leader conversations', nameField:'learned', draftAny:true, redraw:['learned'], fields:{date:'YYYY-MM-DD', leader:'text', team:'id of teams', learned:'text', rows:'array of row ids'}},
