var CUL_PREFIX=(function(){var m={};Object.keys(CUL_SCHEMA).forEach(function(k){var p=CUL_SCHEMA[k].prefix;if(!p)return;if(m[p])throw new Error('CUL_SCHEMA: prefix '+p+' declared twice');m[p]=k});return m})();
function newId(prefix){return String(prefix)+uid()} /* 25 Sep 2026 (Spec §23.2): the family generator with a per-collection prefix — never the clock alone, never a position */
function culNew(coll){var c=CUL_SCHEMA[coll];if(!c||c.kind!=='list'||!c.prefix)throw new Error('culNew: '+coll+' is not a declared list collection');return newId(c.prefix)}
function culEmptyData(){var d={};Object.keys(CUL_SCHEMA).forEach(function(k){var c=CUL_SCHEMA[k];d[k]=('empty' in c)?JSON.parse(JSON.stringify(c.empty)):((c.kind==='list'||c.kind==='series')?[]:(c.kind==='value'?null:{}))});d.startDate=todayIso();return d;}
