/* Map a field id to the record it edits (Spec §10 lock map, §23.3). 25 Sep 2026: read from
   CUL_SCHEMA, so every field that follows the data standard's id form locks its own record
   with no per-surface wiring: list fields prefix_field_<recordId> lock collection::recordId,
   map fields prefix_<canonicalKey>_<field> lock collection::canonicalKey, record and value
   fields lock the collection. The Org & Team modal's roster (ru_) and enterprise (ent_) fields
   lock at collection grain, the ER form. Unmapped ids (panel inputs, drafts, the sign-in-side
   admin console's au_ fields, whose writes span organizations) stay permissive. */
function idToRecordKey(id){
  if(!id) return null;
  var s=String(id), i=s.indexOf('_'); if(i<0) return null;
  var pre=s.slice(0,i), rest=s.slice(i+1);
  var fam={ru:'roster',ent:'enterprise'}; if(fam[pre]) return fam[pre];
  var coll=CUL_PREFIX[pre]; if(!coll) return null;
  var c=CUL_SCHEMA[coll];
  if(c.kind==='list'){ var j=rest.indexOf('_'); if(j<0) return null; var rid=rest.slice(j+1); return rid?(coll+'::'+rid):null; }
  if(c.kind==='map'){ var k=rest.indexOf('_'); var key=k<0?rest:rest.slice(0,k); return key?(coll+'::'+key):coll; }
  return coll;
}

