if(typeof document!=='undefined'){
  document.addEventListener('focusin', function(e){
    var t=e.target; if(!t||!/^(INPUT|SELECT|TEXTAREA)$/.test(t.tagName||'')) return;
    if(t.readOnly||t.disabled) return;
    var rk=(t.getAttribute&&t.getAttribute('data-lock'))||idToRecordKey(t.id)||handlerLockKey(t); if(!rk) return; /* C-2 (testing chat, 30 Oct 2026): a control's own data-lock first, then its id, then its handler, the order applyLockUI reads them (Architecture Sweep 4R items 13 and 27) */ /* Batch 2: a cell without a routable id carries its record in data-lock */
    if(Collab.lockedByOther(rk)){ if(t.blur)t.blur(); return; }
    if(_heldLock&&_heldLock!==rk){ Collab.release(_heldLock); _heldLock=null; }
    if(Collab.acquire(rk)) _heldLock=rk;
  });
  document.addEventListener('focusout', function(e){
    setTimeout(function(){
      var a=document.activeElement;
      var stillField=a&&/^(INPUT|SELECT|TEXTAREA)$/.test(a.tagName||'')&&(idToRecordKey(a.id)||(a.getAttribute&&a.getAttribute('data-lock')));
      if(_heldLock&&!stillField){ Collab.release(_heldLock); _heldLock=null; }
    },60);
  });
  window.addEventListener('beforeunload', function(){ try{Collab.leave();}catch(e){} });
  setInterval(function(){ try{ Collab.refreshMine(); applyLockUI(false); }catch(e){} }, 4000);
}

