function culEntryPick(id){try{var e=document.getElementById(id);if(e){e.focus();if(e.select)e.select()}}catch(x){}} /* a refused setup puts the cursor in the field at fault with its text selected, so a stale entry is seen and replaced (Sweep 4 item 14, 1 Nov 2026) */ function gotoSetup(){ UI.entry={step:'setup', presetUser:'', presetPin:'', err:''}; render(); }

function gotoLogin(){ UI.entry={step:'login', err:''}; render(); }

function gotoAdminLogin(){ UI.entry={step:'admin-login', err:''}; render(); }

var SETUP_CODE='ABCXYZ'; /* Spec §25.5 point 8 (ruled by Paul, 2 Oct 2026): a placeholder; in deployment the server checks it */
function culSetupKeep(){if(!UI.entry)return;var g=function(i){var e=$(i);return e?String(e.value||''):''};UI.entry.presetCode=g('setupCode');UI.entry.presetOrg=g('setupOrg');UI.entry.presetName=g('setupName');UI.entry.presetUser=g('setupUser').trim();UI.entry.presetPin=g('setupPin')} function culEntryPickSoon(id){try{culEntryPick(id)}catch(e){}setTimeout(function(){try{culEntryPick(id)}catch(e){}},40)} /* a refused setup keeps what was typed and puts the cursor in the field at fault, its text selected, once the screen has redrawn (Sweep 6 item 16) */ function doSetup(){ var _sc=$('setupCode'); if(((_sc&&_sc.value)||'').trim()!==SETUP_CODE){ UI.entry.err='That setup code is not recognized.'; culSetupKeep(); render(); culEntryPickSoon('setupCode'); return } /* 2 Oct 2026 (Paul): a new organization needs the setup code */ var org=$('setupOrg'),nm=$('setupName'),un=$('setupUser'),pn=$('setupPin');
  var orgName=org?org.value.trim():'',name=nm?nm.value.trim():'',username=un?un.value.trim():'',pin=pn?pn.value.trim():'';
  if(!orgName||!name||!username||!pin){UI.entry.err='Please complete all fields to continue.';culSetupKeep();render();culEntryPickSoon(!orgName?'setupOrg':!name?'setupName':!username?'setupUser':'setupPin');return} var _spp=passwordProblem(pin); if(_spp){UI.entry.err=_spp;culSetupKeep();render();culEntryPickSoon('setupPin');return} if(usernameTaken(username,null)){UI.entry.err='That username is already taken. Choose another.';culSetupKeep();render();culEntryPickSoon('setupUser');return} /* 2 Oct 2026 (Spec §25.5) */
  resetOrgScopedUI(); /* 23 Sep 2026: before the new organization is created and loaded */
  var res=createOrg(orgName,{name:name,username:username,passcode:pin,role:'Administrator'});
  Auth.setSession(res.userId);
  var rc=$('setupRemember');var remember=rc?rc.checked:false;
  try{Store.setRemember(remember?{orgId:res.orgId,userId:res.userId}:null)}catch(e){}
  // Land in the app and open the Team panel so they can add the rest of the team
  UI.entry=null;render();openOrgSetup();
}

function adminKey(e){ if(e&&e.key==='Enter') doAdminLogin(); }

function doAdminLogin(){ var un=$('adminUser'),pn=$('adminPin'); var user=un?un.value.trim():'', pin=pn?pn.value:''; Auth.signInAdmin(user,pin,function(res){ if(res&&res.ok){ if(res.mustChange){UI.entry={step:'adminNewpw',err:'',why:res.firstUse?'once':'weak'};render();return} enterAppAsAdmin();return} if(res&&res.reason==='network'){UI.entry.err='Could not reach the sign-in service. Try again.';render();return} UI.entry.err='That username and password do not match.';render();var a=$('adminPin');if(a){a.focus();a.select&&a.select()} }); }

function enterAppAsAdmin(){
  Auth.setAdminSession(true);
  var orgs=getOrgs();
  if(!orgs.length){ UI.entry={step:'admin'}; render(); return; } // no orgs yet → console to create one
  UI.entry={step:'admin'}; render(); /* C-5 (testing chat, 31 Oct 2026): the app administrator always lands on the console, as Architecture */
}

function adminConsoleOpen(orgId){ if(!isAppAdmin)return; /* C-1 (testing chat, 30 Oct 2026): rights checked inside the function, as Architecture (Sweep 4R item 29) */
  // Admin override: enter the org's workspace signed in as its first member
  switchToOrg(orgId);
  Auth.setSession((USERS[0]&&USERS[0].id)||null);
  if(!currentUserId){ UI.entry={step:'admin'}; alert('This organization has no members yet.'); render(); return; }
  try{Store.setRemember(null);}catch(e){}
  UI.entry=null; render();
}

function adminConsoleDelete(orgId){ if(!isAppAdmin)return; /* C-1 (testing chat, 30 Oct 2026): rights checked inside the function, as Architecture (Sweep 4R item 29) */
  var o=getOrg(orgId); if(!o)return;
  if(!confirm('Delete "'+o.name+'" and all of its data? This cannot be undone.'))return;
  deleteOrgById(orgId); UI.entry={step:'admin'}; render();
}

function adminConsoleNewOrg(){ if(!isAppAdmin)return; /* C-1 (testing chat, 30 Oct 2026): rights checked inside the function, as Architecture (Sweep 4R item 29) */
  var nm=prompt('Name the new organization:'); if(nm===null)return; nm=(nm||'').trim();
  if(!nm){ alert('Please enter a name.'); return; }
  var keepOrg=currentOrgId; createOrg(nm); setCurrentOrg(keepOrg); if(keepOrg){loadData();applyTeamRoster();} else {data=culEmptyData();USERS.length=0;}
  UI.entry={step:'admin'}; render();
}

function exitAdmin(){ Auth.setAdminSession(false); resetOrgScopedUI(); UI.entry={step:'login', err:''}; render(); }

function adminChangePasscode(){
  if(!isAppAdmin)return;
  var _cur=adminCreds()||{username:'admin',passcode:'NextChapter2026!',mustChange:true}; var cp0=prompt('Current password');if(cp0===null)return; if(cp0!==_cur.passcode){alert('Your current password is not correct.');return} /* 5 Oct 2026 (Sweep 4R item 22): the console asks for the current password, as the More menu's Change password does */ var np=prompt('New password (At least 8 characters, including a number and a special character such as ! or #.)');if(np===null)return; if(np===_cur.passcode){alert('Choose a password different from your current one.');return} /* Sweep 4R item 22: an unchanged password is refused */ var _pp=passwordProblem(np); if(_pp){alert(_pp);return} var cf=prompt('Confirm new password');if(cf===null)return; if(cf!==np){alert('The two passwords do not match.');return} setAdminCreds(Object.assign({},adminCreds()||{username:'admin'},{passcode:np,mustChange:false}));alert('Your password has been changed.'); }

function updateAdminBar(){
  var bar=document.getElementById('adminViewBar');
  var show = isAppAdmin && currentUserId && getCurrentUser() && !UI.entry;
  if(show){
    if(!bar){ bar=document.createElement('div'); bar.id='adminViewBar'; bar.className='admin-view-bar'; document.body.appendChild(bar); }
    var org=getOrg(currentOrgId); var u=getCurrentUser();
    bar.innerHTML='<span class="admin-view-txt"><span class="admin-view-dot">●</span> Admin view · '+esc(org?org.name:'')+' · acting as '+esc(u.name||'')+'</span><button class="admin-view-btn" onclick="openAdmin()">Admin panel</button>';
  } else if(bar && bar.parentNode){ bar.parentNode.removeChild(bar); }
}

function orgRosterPreview(orgId){var d=Store.readOrg(orgId);return (d&&Array.isArray(d.roster))?d.roster:[];}

function renderEntry(){
  if(!UI.entry)UI.entry={step:'login'};
  var s=UI.entry.step;
  if(s==='setup')return renderSetupScreen();
  if(s==='admin-login')return renderAdminLogin();
  if(s==='admin')return isAppAdmin?renderAdminConsole():renderAdminLogin(); if(s==='newpw'||s==='adminNewpw')return renderNewPasswordScreen(); if(s==='sampleSignIn')return renderSampleNeedsSignIn(); return renderLoginScreen();
}

