function renderPipeline(){ /* 25 Sep 2026 (Rollout items 24, 59): the ER overview — back button, module-overview video, 90-day timeline, hero, stat strip, phase cards */
  var h='<div class="content-area"><div class="content-inner">';
  h+=backBtn();
  h+='<div class="overview-video-card mb-6"><div class="overview-video-label">Module Overview</div>'
   +'<video class="overview-video" controls preload="auto" playsinline><source src="cult-module-overview.mp4" type="video/mp4">Your browser does not support embedded video.</video></div>';
  h+=vizTimeline(0);
  h+=asgnOverviewCard(); /* Governance addendum 217: My Assignments on the module overview, only when the signed-in member has an open assignment */
  h+='<div class="u-4d06b89">'+badge('90-Day Module','#1B6B5A')+'<h1 class="u-da9c7f5">90 Days to an <em class="t-blue">AI-Ready Culture</em></h1><p class="u-c9b7d79">Culture is where AI strategy goes to die \u2014 or where it takes root.</p></div>';
  h+=vizStatStrip();
  PH.forEach(function(ph){
    h+=card('<div class="u-1390122" onclick="go(\'phase\',\''+ph.id+'\')"><div><div class="flx-center gap-2 mb-1"><span class="ph-circle-28" style="--c:'+ph.color+'">'+ph.id+'</span><h3 class="u-a5b9245">'+ph.name+'</h3>'+badge(ph.days,ph.color)+'</div><div class="u-d9edac8">'+ph.steps.map(function(s){return s.name}).join(' \u2192 ')+'</div></div><span class="u-ef4626c">\u2192</span></div>','margin-bottom:12px');
  });
  h+='</div></div>';return h;
}


