function culEnsure(k,v){if(!data[k])data[k]=v;return data[k]}

/* ── teams ── */
/* In-place add forms (Rollout item 31). 25 Sep 2026: the five browser-dialog adds open a form on the page,
   directly below the button (item 33), scrolled into view (item 51). The typed draft lives in UI state until
   Add commits it, so a redraw cannot lose it (item 57). */
var CUL_ADD={
  team: {coll:'teams',   label:'Team name', ph:'For example, Client Services', make:function(v){return {id:culNew('teams'),name:v}}},
  role: {coll:'roles',   label:'Role name', ph:'For example, Claims handler', make:function(v){return {id:culNew('roles'),name:v}}}
};
function culAddOpen(kind){if(!CUL_ADD[kind])return;UI.culAddMsg='';UI.culAdd=kind;UI.culAddDraft='';UI.scrollTo='culAddCard_'+kind;render()}
function culAddClose(){UI.culAddMsg='';UI.culAdd=null;UI.culAddDraft='';UI.culAddUse=null;render()}
function culAddSave(){var k=UI.culAdd,c=CUL_ADD[k];if(!c)return;var v=String(UI.culAddDraft||'').trim();if(!v)return;if(UI.culAddUse&&lockBlocked('aiUses::'+UI.culAddUse))return; /* §26.1: linking into an AI use writes that use */
  if(k==='role'&&culRoleNameTaken(v)){var _rm='A role named '+v+' is already in the list.';if(currentStep==='2.5b')UI.riMsg=_rm;else UI.culAddMsg=_rm;render();return} /* the refusal shows on the Add card where it was refused; UI.riMsg is only for step 2.5b */
  var rec=c.make(v);culEnsure(c.coll,[]).push(rec);
  if(UI.culAddUse){var u=(data.aiUses||[]).filter(function(x){return x&&x.id===UI.culAddUse})[0],f=k==='team'?'teams':k==='role'?'roles':null;if(u&&f){if(!Array.isArray(u[f]))u[f]=[];u[f].push(rec.id);Store.commit('aiUses',u.id)}} /* Batch 2 step 4: added in place from an AI use, the new team or role is linked to that use by its id */
  UI.culAdd=null;UI.culAddDraft='';UI.culAddUse=null;UI.culAddMsg='';saveData();render()}
function culAddForm(kind){if(UI.culAdd!==kind)return'';var c=CUL_ADD[kind];
  return '<div class="card" id="culAddCard_'+kind+'" style="padding:16px 18px;margin:10px 0 14px"><label class="form-label" for="culAddDraft">'+esc(c.label)+'</label>'
   +'<input class="field-input" id="culAddDraft" style="width:100%" value="'+esc(UI.culAddDraft||'')+'" placeholder="'+esc(c.ph)+'" oninput="UI.culAddDraft=this.value;UI.culAddMsg=\'\'" onkeydown="if(event.key===\'Enter\'){event.preventDefault();culAddSave()}">'
   +(UI.culAddMsg?'<p data-add-msg role="status" style="font-size:14px;color:var(--gold-text);margin:8px 0 0">'+esc(UI.culAddMsg)+'</p>':'')+'<div style="display:flex;gap:8px;margin-top:10px">'+btn('Add','culAddSave()','bp')+btn('Cancel','culAddClose()','bg2')+'</div></div>'}
/* Blank and nameless records (Spec §26.3, Rollout item 90): a register row made by + Add is a draft until it is named.
   Architecture's form (inlineCtx, sweepBlankInline, blankInlineRemove), on Culture's registers: a blank draft is removed
   with its own record only. (7 Oct 2026, Batch 3, step 1: a named team, role or AI use is now linked from other records, and its delete removes those links through culLinksTo; a blank draft has none yet.) 6 Oct 2026, Batch 8f. */
function inlineCtx(){return JSON.stringify([currentPage,currentStep,Object.keys(UI).filter(function(k){return /(Part|Tab|tab)$/.test(k)}).sort().map(function(k){return [k,UI[k]]})])}
function culInlineAdded(coll){var L=data[coll];var r=Array.isArray(L)?L[L.length-1]:null;if(!r)return;r._inlineDraft=true;r._draftTab=CUL_TAB_ID;r._draftAt=Date.now();UI.inlineAdd={id:r.id,coll:coll,_ctx:inlineCtx()}}
function blankInlineRemove(id,coll,atLoad){var L=data[coll];if(!Array.isArray(L))return false;if(coll==='roles')(data.aiUses||[]).forEach(function(u){if(u&&Array.isArray(u.roles)&&u.roles.indexOf(id)>=0){u.roles=u.roles.filter(function(x){return x!==id});if(!atLoad)Store.commit('aiUses',u.id)}}); /* 25 Oct 2026 (bug hunt B14): a blank role that is removed leaves no AI use pointing at it */for(var i=L.length-1;i>=0;i--){if(L[i]&&L[i].id===id){L.splice(i,1);if(!atLoad)Store.commit(coll,id)}}return true}
function culDraftBlank(coll,r){var c=CUL_SCHEMA[coll]||{},nf=c.nameField;if(!r||!nf||String(r[nf]||'').trim())return false;if(Array.isArray(c.draftFields))return !c.draftFields.some(function(f){var v=r[f];return Array.isArray(v)?v.length>0:String(v==null?'':v).trim()!==''}); /* audit C2-03, 31 Oct 2026 */ if(!c.draftAny)return true;return !Object.keys(c.fields||{}).some(function(f){var v=r[f];return Array.isArray(v)?v.length>0:String(v==null?'':v).trim()!==''})} /* a record is a blank draft when its naming field is empty and, where the schema marks draftAny, every field is (UAT, 31 Oct 2026): a conversation with a leader and a date but nothing learned yet is kept */ function sweepBlankInline(force){try{culRvDecSweep(force)}catch(e){}var ctx=inlineCtx();var ia=UI.inlineAdd;if(!ia)return;if(!force&&ia._ctx===ctx)return;var L=data[ia.coll],nf=(CUL_SCHEMA[ia.coll]||{}).nameField;var r=Array.isArray(L)?L.filter(function(x){return x&&x.id===ia.id})[0]:null;if(r&&nf&&String(r[nf]||'').trim()&&r._inlineDraft){delete r._inlineDraft;try{Store.commit(ia.coll,r.id)}catch(e){}} /* clearing a draft flag saves the record (item 2, Sweep 2, 31 Oct 2026) */if(r&&nf&&culDraftBlank(ia.coll,r)){blankInlineRemove(ia.id,ia.coll,false)}UI.inlineAdd=null}
function culRsDedupe(){culDedupeColl('rowSettings',function(r){return r.row==null?null:String(r.row)},function(k){return 'rsrow'+k})} /* 8 Oct 2026 (R8): one rowSettings record per row; the 'rsrow'+row record wins, blanks are filled, history is joined, and the removals are committed */
/* 8 Oct 2026 (R12): the ids prbase*, prfirst, prday90*, jbcuts, pkbase*, pkq*, chrow*, rsrow*, rvday90 are canonical keys under Family Standard Spec 23.2, because the module defines each slot (one per group, per measure, per Tracker row, per organization). Reviews that people create (quarterly, annual) take family-generated ids; the review merge below keeps the first open review of a type. */
/* 8 Oct 2026 (R8): the load-time pass for rows created on first save. Per natural key it keeps the record with the deterministic id (else the first), fills the kept record's blank fields from the others, drops the rest, and repoints links that named a dropped record. The removals are committed after the load (culDedupeFlush), so a later merge cannot bring a dropped record back. */
