/* 7 Oct 2026 (Batch 1): the step shell. The old tools, action checklists, worksheets and related-step chips are retired. Each step batch builds its step's content
   in this function and adds its Complete when gate; until then a step shows its description, a plain not-built line and the family done button. */
function renderStepContent(id){
var stepObj=null,fl=null;PHASES.forEach(function(p){p.steps.forEach(function(s){if(s.id===id)stepObj=s});(STEP_FLOW[p.id]||[]).forEach(function(f){if(f.id===id)fl=f})});
var h='';
var _S=CUL_BATTERIES[id]; /* 7 Oct 2026 (Batch 2, decision 8): a step that has registered its sections is drawn by the tabbed battery; the rest keep the not-built shell */
if(!CUL_STEP_INTRO[id])h+='<p class="t-lead'+(CUL_MAP_STEPS_ON.indexOf(String(id))>=0?' cul-narrow':'')+'" style="margin-top:0;margin-bottom:20px">'+esc(((_S&&_S.intro)||(fl&&fl.sh))||'')+'</p>'; /* A1: a step with an entry in CUL_STEP_INTRO is introduced once, in its header */
if(_S&&!(stepObj&&stepObj.standing))return h+culBattery(id);
if(stepObj&&stepObj.standing){ /* the standing pages (5.1 to 5.3): no done button, no assign bar */
 if(id==='5.2')h+='<div data-standing="1">'+culS52()+'</div>';
 else if(id==='5.3')h+='<div data-standing="1">'+culS54()+'</div>';
 else if(id==='5.4')h+='<div data-standing="1">'+culS53()+'</div>'; /* 20 Oct 2026: the hub is 5.3, Analytics 5.4 */
 else h+='<div class="card" data-standing="1" style="padding:20px 24px;margin-bottom:20px"><div class="t-stone-13">This page has not been built yet. Nothing here is saved or needs your input.</div></div>';
 return h;
}
h+='<div class="card" style="padding:20px 24px;margin-bottom:20px"><div class="t-stone-13">This step has not been built yet. Nothing here is saved or needs your input.</div></div>';
// completion
h+='<div>'+doneBtn('markStepComplete(\''+id+'\')',false,null,id)+'</div>'; /* in its own div, so refreshGateInPlace swaps this and nothing else (Batch 2) */ /* Spec \u00a711: the family done button \u2014 level-aware labels, confirm, first stamp; Culture's steps are untabbed and ungated */
return h;
}


