  h+='<div class="cmap-scorebox"><div>'+culMapTrackFull(d)+'</div><div class="cmap-tiles"><div class="cmap-tile"><div class="n">'+(now!=null?esc(now.toFixed(1)):'&ndash;')+'</div><div class="l">employee score now</div></div><div class="cmap-tile"><div class="n">'+(d.target!=null?esc(d.target.toFixed(1)):'&ndash;')+'</div><div class="l">target</div></div><div class="cmap-tile go"><div class="n">'+(now!=null&&d.target!=null?esc(Math.max(0,d.target-now).toFixed(1)):'&ndash;')+'</div><div class="l">still to go</div></div><div class="cmap-tile"><div class="n">'+its.length+'</div><div class="l">'+(its.length===1?'initiative aimed at it':'initiatives aimed at it')+'</div></div></div></div>';
