  h+='<section class="cmap-col'+(col==='ev'?' show':'')+'" style="--pc:var(--p1)"><div class="cmap-colh"><h3>Evidence <span>'+b.evidence.length+'</span></h3><button type="button" class="cmap-add" onclick="culBoardAdd(&#39;ev&#39;)">+ Add</button></div>'+culBdRecFor('ev')+culMapCards(b.evidence,['Conversations','Signals','Practice','Fears and trust'],'Nothing recorded for this dimension yet.')+'</section>';
