  var tone={specific:'ok',vague:'warn',silent:'bad'},items=L.map(function(r){var k=culLcSaid(r);return {coll:'leaderComms',id:r.id,when:culMonthWords(r.date)||'Date not set',title:String(r.channel||'').trim()||'Unnamed communication',label:k?culTag('On AI and jobs: '+culWord(CUL_LC_SAID,k),tone[k]):'',sub:culLcAudLabel(r)?'To '+culLowerUnlessOther(r.audience==='other',culLcAudLabel(r)):'',dims:culItemDims('leaderComms',r)}});
