function culSurf25d(){var L=(data.commsPlan||[]).filter(function(r){return r&&!r._inlineDraft}).slice().sort(function(a,b){return String(a.date||'9999').localeCompare(String(b.date||'9999'))});
  var items=[{day1:true,title:'The program starts'}].concat(L.map(function(r){var open=culCpOpen(r),pl=(Array.isArray(r.plans)?r.plans:[]).map(function(id){var t=(data.themes||[]).filter(function(x){return x&&x.id===id})[0];return t&&String(t.plan||'').trim()?culMapShort(t.plan,70):''}).filter(Boolean);
    return {coll:'commsPlan',id:r.id,when:culDayWhen(r.date),title:String(r.channel||'').trim()||culMapShort(r.message,60)||'Unnamed communication',label:open?culTag(open+(open===1?' checklist item open':' checklist items open'),'warn'):culTag('Checklist complete','ok'),sub:String(r.deliveredBy||'').trim()?'Delivered by '+String(r.deliveredBy).trim():'',
      body:pl.length?'<div class="cmap-tl-ann"><span>Announces</span>'+pl.map(function(x){return '<div>'+esc(x)+'</div>'}).join('')+'</div>':'',dims:culItemDims('commsPlan',r)}}));
  return culSurface('<b>The communication plan.</b> Each planned communication at its date, from day 1, with the plans it announces.',(L.length?'':'<p class="cmap-empty">No communications planned yet.</p>')+culTimeline(items,'var(--s25)'),'var(--s25)')}
function culSide25d(){return culSideForm({colls:['commsPlan'],back:'All communications',lead:'Choose a communication on the timeline to change it or tick its checklist, or add one.',adds:[['commsPlan','+ Add a planned communication']]})}
/* ── Step 2.4 (prototype 5): each audit answer's grade, the change each answer points to, meeting tiles above the map, and red marks where a meeting's habits work against a dimension ── */
var CUL_AUDIT_GRADE={speaksFirst:{senior:'a',data:'h',rotates:'h',varies:'x'},rewards:{confident:'a',mix:'x',learned:'h'},dissent:{shutDown:'a',tolerated:'x',invited:'h'},learning:{never:'a',sometimes:'x',always:'h'},aiOpen:{never:'a',sometimes:'x',always:'h'}};
var CUL_AUDIT_DIMS={speaksFirst:['1','5'],rewards:['6','4'],dissent:['4','1'],learning:['2','4'],aiOpen:['3','8']};
var CUL_AUDIT_FIX={speaksFirst:'speakFirst',rewards:'learning',dissent:'dissentSlot',learning:'learning',aiOpen:'showAi'};
var CUL_GRADE_L={h:'Helps',x:'Mixed',a:'Works against'};
function culMtGrade(r,k){var a=r&&r.audit&&typeof r.audit==='object'?r.audit[k]:'';return a&&CUL_AUDIT_GRADE[k]?(CUL_AUDIT_GRADE[k][a]||''):''}
function culMtGradeHtml(r,k){var g=culMtGrade(r,k);return '<span data-gate="mtgr_'+escAttr(k)+'_'+escAttr(r.id)+'"><span class="cmap-grade '+g+'">'+esc(CUL_GRADE_L[g]||'')+'</span></span>'} /* the gate wraps the grade, so its color is swapped with its words */
/* the changes the audit points to: each answer that is mixed or works against suggests its fix; an AI meeting suggests bringing Legal and Compliance and front-line staff in early */
function culMtSuggested(r){var s=[];CUL_AUDIT_Q.forEach(function(q){var g=culMtGrade(r,q.k);if((g==='a'||g==='x')&&s.indexOf(CUL_AUDIT_FIX[q.k])<0)s.push(CUL_AUDIT_FIX[q.k])});if(r&&r.aiDecided===true&&s.indexOf('earlyInvolve')<0)s.push('earlyInvolve');return s}
function culMtAgainst(r){var d=[];CUL_AUDIT_Q.forEach(function(q){if(culMtGrade(r,q.k)==='a')CUL_AUDIT_DIMS[q.k].forEach(function(x){if(d.indexOf(x)<0)d.push(x)})});return d}
function culMtAudited(r){return CUL_AUDIT_Q.every(function(q){return !!(r.audit&&r.audit[q.k])})}
function culMtTileStatus(r){if(r.noChange===true)return ['No change needed','nc'];if(!culMtAudited(r))return ['Not yet audited','na'];var it=culMapItems().filter(function(x){return x.coll==='meetings'&&x.id===r.id})[0];if(!it)return ['Audited, no changes chosen','na'];
  return ['Redesign '+culLifeLabel(it.status).toLowerCase(),it.status==='inPlace'?'in':it.status==='agreed'?'ag':'na']}
function culMtPick(id){UI.mtSel=UI.mtSel===id?null:id;if(UI.mtSel){if(!UI.expanded)UI.expanded={};UI.expanded['mt24_'+id]=true;UI.scrollTo='mt24f_'+id}render()} /* a tile marks its meeting on the map, opens its form and goes to it */
function culMtAddPick(){var b=(data.meetings||[]).map(function(r){return r&&r.id});culMtAdd();var n=(data.meetings||[]).filter(function(r){return r&&b.indexOf(r.id)<0});if(n.length){UI.mtSel=n[0].id;render()}}
function culMtDashTitle(r,q){var a=r&&r.audit&&typeof r.audit==='object'?r.audit[q.k]:'',l=a?culWord(q.opts,a):'';return q.q+' '+(l||'Not answered yet.')+(l&&CUL_GRADE_L[culMtGrade(r,q.k)]?' ('+CUL_GRADE_L[culMtGrade(r,q.k)]+')':'')}
function culMtTilesRec(){var L=(data.meetings||[]).filter(function(r){return !!r});
  return '<div class="cmap-tiles24" role="group" aria-label="Meetings">'+L.map(function(r){var s=culMtTileStatus(r),nm=String(r.name||'').trim()||'Unnamed meeting',on=culRecIs('meetings',r.id);
    return '<button type="button" class="cmap-mtile'+(on?' sel':'')+'" aria-pressed="'+on+'" onclick="'+escAttr("culRecOpen('meetings','"+culFoldJs(r.id)+"')")+'"><span class="hd"><b title="'+escAttr(nm)+'">'+esc(nm)+'</b><span class="m">'+esc([culMtOften(r)||'How often not set',String(r.chair||'').trim()||'Chair not named'].join(' \u00B7 '))+'</span></span><span class="strip" role="img" aria-label="'+escAttr(CUL_AUDIT_Q.map(function(q){return culMtDashTitle(r,q)}).join(' '))+'">'+CUL_AUDIT_Q.map(function(q){return '<i class="'+culMtGrade(r,q.k)+'" title="'+escAttr(culMtDashTitle(r,q))+'"></i>'}).join('')+'</span><span class="tst '+s[1]+'">'+esc(s[0])+'</span><span class="m ai">'+(r.aiDecided===true?'AI meeting':'')+'</span></button>'}).join('') /* Paul (19 Oct 2026): the bar sits at the same height on every card, each dash names its question and answer, and the status sits directly under the bar */
    +culMtSuggestions().map(function(s){var d=culDayOf(s.date);return '<button type="button" class="cmap-mtile sug" onclick="'+escAttr("culMtFromObs('"+culFoldJs(s.obsId)+"')")+'"><b>'+esc(s.name)+'</b><span class="m">'+esc(d!=null&&d>0?'Came up in your observation on day '+d+'.':'Came up in one of your observations.')+'</span><span class="tst na">Audit it?</span></button>'}).join('')+'</div>'} /* Paul (19 Oct 2026): the meeting tiles are the audit tab's display; a tile opens its meeting below them, read-only, with Edit */
function culMtTiles(){var L=(data.meetings||[]).filter(function(r){return r&&!r._inlineDraft}),sel=UI.mtSel;
  return '<div class="cmap-tiles24" role="group" aria-label="Meetings">'+L.map(function(r){var s=culMtTileStatus(r),nm=String(r.name||'').trim()||'Unnamed meeting';
    return '<button type="button" class="cmap-mtile'+(sel===r.id?' sel':'')+'" aria-pressed="'+(sel===r.id)+'" onclick="'+escAttr("culMtPick('"+culFoldJs(r.id)+"')")+'"><b>'+esc(nm)+'</b><span class="m">'+esc([culMtOften(r)||'How often not set',String(r.chair||'').trim()||'Chair not named'].join(' · '))+'</span><span class="strip" title="The five audit answers">'+CUL_AUDIT_Q.map(function(q){return '<i class="'+culMtGrade(r,q.k)+'"></i>'}).join('')+'</span><span class="tst '+s[1]+'">'+esc(s[0])+'</span></button>'}).join('')
    +culMtSuggestions().map(function(s){var d=culDayOf(s.date);return '<button type="button" class="cmap-mtile sug" onclick="'+escAttr("culMtFromObs('"+culFoldJs(s.obsId)+"')")+'"><b>'+esc(s.name)+'</b><span class="m">'+esc(d!=null&&d>0?'Came up in your observation on day '+d+'.':'Came up in one of your observations.')+'</span><span class="tst na">Audit it?</span></button>'}).join('')
    +'<button type="button" class="cmap-mtile addt" onclick="culMtAddPick()">+ Add a meeting</button></div>'}
/* ruling 155 (prototype 5): a meeting named in an observation, and not yet among the meetings, is suggested by a dashed tile. One tile per name, from its earliest observation. */
function culMtSuggestions(){var have=culNamed('meetings','name').map(function(r){return String(r.name).trim().toLowerCase()}),seen={},out=[];
  (data.observations||[]).filter(function(o){return o&&!o._inlineDraft&&culObsMeetingVal(o)==='other'}).slice().sort(function(a,b){return String(a.date||'9999').localeCompare(String(b.date||'9999'))}).forEach(function(o){var n=String(o.meetingOther||'').trim(),k=n.toLowerCase();if(!n||seen[k]||have.indexOf(k)>=0)return;seen[k]=1;out.push({name:n,obsId:o.id,date:o.date||''})});
  return out}
function culMtFromObs(obsId){var s=culMtSuggestions().filter(function(x){return x.obsId===obsId})[0];if(!s)return;var b=(data.meetings||[]).map(function(r){return r&&r.id});
  var r=culListAdd('meetings',{name:'',often:'',oftenOther:'',chair:'',purpose:'',aiDecided:false,observations:[],audit:{},changes:{},added:{},owner:'',start:'',noChange:false,noChangeReason:''});
  if(!r||!r.id||b.indexOf(r.id)>=0){culMapToast('Nothing was added, because another person is editing this list. Try again when they finish.');render();return}
  fldSave('mt_name_'+r.id,s.name);fldSave('mt_observations_'+r.id,[obsId]);
  (data.observations||[]).forEach(function(o){if(o&&culObsMeetingVal(o)==='other'&&String(o.meetingOther||'').trim().toLowerCase()===s.name.toLowerCase()&&!Collab.lockedByOther('observations::'+o.id))fldSave('ob_meeting_'+o.id,r.id)}); /* the observations that named it now point at it */
  culFoldOpenNew('mt24_'+r.id);UI.mtSel=r.id;if(CUL_MAP_STEPS_ON.indexOf('2.4')<0){UI.recOpen={coll:'meetings',id:String(r.id),edit:true};UI.scrollTo='recbox_meetings'}culMapToast('Added from the observation. Answer the audit to see where its habits work against the target.');render()}
/* the red marks on a band: how many meetings work against the dimension, or, with a meeting open, whether it does */
function culMtMark(d){var L=culNamed('meetings','name'),sel=UI.mtSel?L.filter(function(r){return r.id===UI.mtSel})[0]:null;
  if(sel)return culMtAgainst(sel).indexOf(d.id)>=0?'<span class="cmap-agmark" title="'+escAttr(String(sel.name).trim()+' works against this')+'">&#9888;</span>':'';
  var A=L.filter(function(r){return culMtAgainst(r).indexOf(d.id)>=0});return A.length?'<span class="cmap-agmark" title="'+escAttr('Works against this: '+A.map(function(r){return String(r.name).trim()}).join(', '))+'">&#9888; '+A.length+'</span>':''}
function culPriorityRows(){return (data.rowSettings||[]).filter(function(s){return s&&s.priority===true}).map(function(s){return Number(s.row)}).filter(function(n){return !isNaN(n)})}
function culPulseMsg(text){try{var els=document.querySelectorAll('[data-pmsg]');for(var i=0;i<els.length;i++)els[i].textContent=text||''}catch(e){}}
function culPulseReset(elId,text){try{var el=elId&&document.getElementById(elId);if(el){el.value=(text==null?'':text);el.removeAttribute('data-typed')}}catch(e){}} /* the control shows what was stored, so a redraw cannot bring back a refused or rounded entry */
function culD90Locked(r){var rv=culRvDay90();return !!(r&&r.context==='day90'&&rv&&rv.loggedAt)} /* close-out fix 6: a Day-90 round of the logged review is closed */
function culPulseGuard(r,elId,stored){if(culD90Locked(r)||Date.now()<_discardChangeUntil||Collab.lockedByOther('pulseRounds::'+r.id)){culPulseReset(elId,stored);return true}return false} /* §10, §26.1: a round another user holds is never written */
function culPulseDone(r,elId,shown){culTouch();Store.commit('pulseRounds',r.id);culPulseReset(elId,shown);culPulseMsg('');try{refreshGateInPlace()}catch(e){}try{culPulseRepaint()}catch(e){}}
/* The savers. Blank stays blank (the key is deleted), a score is one decimal from 1.0 to 5.0 and a value outside it is refused (the control returns to its stored value), respondents are whole numbers of 1 or more, percentages whole numbers from 0 to 100. None of them redraws the page. */
function culPulseSet(rid,unit,itemId,value,elId){var blank=String(value==null?'':value).trim()==='',n=null,r=culRoundResolve(rid,false);
  var cur=(r&&r.results&&r.results[unit]&&r.results[unit].avg)?r.results[unit].avg[itemId]:undefined,stored=cur==null?'':culFmt1(cur);
  if(!blank){n=Number(value);if(!isFinite(n)){culPulseReset(elId,stored);culPulseMsg(CUL_PR_ERR.range);return false}n=Math.round(n*10)/10;if(n<1||n>5){culPulseReset(elId,stored);culPulseMsg(CUL_PR_ERR.range);return false}}
  if(blank&&!r)return true;
  var grp=culRefGroup(rid,r);if(unit==='org'&&grp!=='leaders')return false; /* employees' whole-organization values are calculated from teams, never entered (31 Oct 2026 ruling; audit C1-R03) */ if(unit!=='org'&&(grp==='leaders'||!(data.teams||[]).some(function(t){return t&&t.id===unit})))return false;
  if(!r)r=culRoundResolve(rid,true,elId);if(!r)return false;
  if(culPulseGuard(r,elId,stored))return false;
  if(!r.results||typeof r.results!=='object')r.results={}; if(!blank&&r.context==='firstPulse'&&!culRoundAnyScore(r))r.scopeRows=culPriorityRows().slice(); /* the first answer records the population the first pulse is administered on (audit C3-R04) */
  var u=r.results[unit];if(!u||typeof u!=='object')u=r.results[unit]={};
  if(blank){if(u.avg)delete u.avg[itemId]}else{if(!u.avg)u.avg={};u.avg[itemId]=n}
  culPulseDone(r,elId,blank?'':culFmt1(n));return true}
function culPulseResp(rid,unit,value,elId){var blank=String(value==null?'':value).trim()==='',n=null,r=culRoundResolve(rid,false),grp=culRefGroup(rid,r),leaderOrg=(grp==='leaders'&&unit==='org');
  var cur=r?(leaderOrg?r.leaderRespondents:((r.results&&r.results[unit])?r.results[unit].respondents:undefined)):undefined,stored=(cur==null||cur==='')?'':String(cur);
  if(!blank){n=Number(value);if(!isFinite(n)||n<1||Math.floor(n)!==n){culPulseReset(elId,stored);culPulseMsg(CUL_PR_ERR.resp);return false}}
  if(blank&&!r)return true; if(unit==='org'&&!leaderOrg)return false; /* employees' whole-organization respondents are calculated from teams (audit C1-R03) */
  if(unit!=='org'&&(grp==='leaders'||!(data.teams||[]).some(function(t){return t&&t.id===unit})))return false;
  if(!r)r=culRoundResolve(rid,true,elId);if(!r)return false;
  if(culPulseGuard(r,elId,stored))return false;
  if(leaderOrg){if(blank)delete r.leaderRespondents;else r.leaderRespondents=n}
  else{if(!r.results||typeof r.results!=='object')r.results={};var u=r.results[unit];if(!u||typeof u!=='object')u=r.results[unit]={};if(blank)delete u.respondents;else u.respondents=n}
  culPulseDone(r,elId,blank?'':String(n));if(!blank&&unit!=='org'){var _tm=(data.teams||[]).filter(function(t){return t&&t.id===unit})[0],_hc=_tm?Number(_tm.headcount):NaN;if(isFinite(_hc)&&_hc>0&&n>_hc)culPulseMsg('More respondents than '+String(_tm.name||'the team').trim()+'\u2019s headcount of '+_hc+'. Check either number.')} /* stored, with a warning (ruling 53) */return true}
function culChoiceTeamMap(r,team,key){return ((r&&r.choiceTeams&&r.choiceTeams[team])||{})[key]||null}
function culChoiceTeams(r,key){return culRoundTeams().filter(function(t){var m=culChoiceTeamMap(r,t.id,key);return !!m&&typeof m==='object'})}
function culChoiceMap(r,key){var q=culChoiceQ(key),raw=(r&&r.choices&&r.choices[key])||{},out={};if(!q)return out;var tm=culChoiceTeams(r,key); /* Paul (12 Oct 2026): the whole-organization share is the teams' shares weighted by how many answered in each team; a choice map with no team figures keeps its stored figures (test fixtures only) */
  if(!tm.length){q.opts.forEach(function(o){var v=culNum(raw[o.k]);if(v!=null)out[o.k]=v});return out}
  q.opts.forEach(function(o){var sw=0,s=0,n=0,su=0;tm.forEach(function(t){var v=culNum(culChoiceTeamMap(r,t.id,key)[o.k]);if(v!=null){n++;su+=v;var w=culUnitResp(r,t.id);if(w>0){sw+=w;s+=w*v}}});if(n)out[o.k]=Math.round(sw>0?s/sw:su/n)});return out}
function culChoiceQ(qKey){return CUL_MC.filter(function(q){return q.k===qKey})[0]||null}
function culChoiceSet(rid,qKey,aKey,value,elId,team){var q=culChoiceQ(qKey);if(!q||!q.opts.some(function(o){return o.k===aKey}))return false;if(team&&!culRoundTeams().some(function(t){return t&&t.id===team})){culRefuse();return false} /* a team removed meanwhile is not recreated by a pending edit (audit C1-03, 31 Oct 2026) */
  var blank=String(value==null?'':value).trim()==='',n=null,r=culRoundResolve(rid,false),cm=team?(((r&&r.choiceTeams&&r.choiceTeams[team])||{})[qKey]||null):((r&&r.choices&&r.choices[qKey])||null),cur=cm?cm[aKey]:undefined,stored=cur==null?'':String(cur);
  if(!blank){n=Number(value);if(!isFinite(n)||n<0||n>100||Math.floor(n)!==n){culPulseReset(elId,stored);culPulseMsg(CUL_PR_ERR.pct);return false}}
  if(blank&&!r)return true;if(culRefGroup(rid,r)==='leaders')return false;
  if(!r)r=culRoundResolve(rid,true,elId);if(!r)return false;
  if(culPulseGuard(r,elId,stored))return false;
  var tgt;if(team){if(!r.choiceTeams||typeof r.choiceTeams!=='object')r.choiceTeams={};if(!r.choiceTeams[team]||typeof r.choiceTeams[team]!=='object')r.choiceTeams[team]={};if(!r.choiceTeams[team][qKey]||typeof r.choiceTeams[team][qKey]!=='object')r.choiceTeams[team][qKey]={};tgt=r.choiceTeams[team][qKey]} /* Paul (12 Oct 2026): choices are entered team by team, keyed by team id */
  else{if(!r.choices||typeof r.choices!=='object')r.choices={};if(!r.choices[qKey]||typeof r.choices[qKey]!=='object')r.choices[qKey]={};tgt=r.choices[qKey]}
  if(blank)delete tgt[aKey];else tgt[aKey]=n;
  culPulseDone(r,elId,blank?'':String(n));return true}
function culChoiceResp(rid,qKey,value,elId){if(!culChoiceQ(qKey))return false;
  var blank=String(value==null?'':value).trim()==='',n=null,r=culRoundResolve(rid,false),cur=(r&&r.choices&&r.choices[qKey])?r.choices[qKey]._respondents:undefined,stored=cur==null?'':String(cur);
  if(!blank){n=Number(value);if(!isFinite(n)||n<1||Math.floor(n)!==n){culPulseReset(elId,stored);culPulseMsg(CUL_PR_ERR.resp);return false}}
  if(blank&&!r)return true;if(culRefGroup(rid,r)==='leaders')return false;
  if(!r)r=culRoundResolve(rid,true,elId);if(!r)return false;
  if(culPulseGuard(r,elId,stored))return false;
  if(!r.choices||typeof r.choices!=='object')r.choices={};if(!r.choices[qKey]||typeof r.choices[qKey]!=='object')r.choices[qKey]={};
  if(blank)delete r.choices[qKey]._respondents;else r.choices[qKey]._respondents=n;
  culPulseDone(r,elId,blank?'':String(n));return true}
function culDatesText(r){if(!r||!r.date)return '';return r.dateEnd?fmtDate(r.date)+' to '+fmtDate(r.dateEnd):fmtDate(r.date)}
function culSurveyDates(ref,r,note,which){var base=/^baseline:/.test(String(ref||''))||!!(r&&r.context==='baseline'),g=culRefGroup(ref,r)||'employees',ex=!!r,lk=culRoundLockId(ref,r),
  d1=ex?'pr_date_'+r.id:'prgDate_'+g,d2=ex?'pr_dateEnd_'+r.id:'prgDateEnd_'+g,q=escAttr(ref),
  help=(which==='open'?'Enter the day the questionnaire went out.':which==='close'?'If the questionnaire ran for more than one day, enter the day it closed.':'Enter the day the questionnaire went out. If it ran for more than one day, also enter the day it closed.'),
  one=function(label,id,val,field,req,hp){return '<div class="mb-4"><label class="form-label" for="'+escAttr(id)+'">'+esc(label)+'</label>'+fhelp(hp||'')+'<input type="date" id="'+escAttr(id)+'" class="field-input'+(req?' gate-field':'')+'" data-lock="pulseRounds::'+escAttr(lk)+'" onchange="culRoundField(\''+q+'\',\''+field+'\',this.value,this.id)" value="'+escAttr(val||'')+'"></div>'};
  return '<div data-survey-dates="1" style="margin:18px 0 0">'+(which==='close'?'':one(which==='open'?'Date it went out *':'Date it went out',d1,r&&r.date,'date',which==='open','Enter the day the questionnaire went out.'))+(which==='open'?'':one('Date it closed',d2,r&&r.dateEnd,'dateEnd',false,'If the questionnaire ran for more than one day, enter the day it closed.')) /* copy pass (19 Oct 2026): each date\u2019s help sits under its own label */+(note?'<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:0 0 8px">'+esc(note)+'</p>':'')+'</div>'} /* 12 Oct 2026: step 1.2 asks for the date it went out on its first tab and the date it closed on its second */
function culRoundDates(rid,field,value,elId){var text=String(value==null?'':value).trim(),r=culRoundResolve(rid,false),stored=r?(r[field]||''):'';
  if(text&&!/^\d{4}-\d{2}-\d{2}$/.test(text)){culPulseReset(elId,stored);return false}
  var existed=!!r;if(!r){if(!text)return true;r=culRoundResolve(rid,true,elId)}if(!r)return false;
  if(culPulseGuard(r,elId,stored))return false;
  var o=(field==='date'?text:r.date)||'',e=(field==='dateEnd'?text:r.dateEnd)||'',created=!existed;
  if(o&&e&&e<o){culPulseReset(elId,stored);culPulseMsg('The closing date cannot be before the opening date.');return false}
  r[field]=text;
  culPulseDone(r,elId,text);if(created){try{deferRender()}catch(x){}}return true}
function culRoundField(rid,field,value,elId){if(field==='date'||field==='dateEnd')return culRoundDates(rid,field,value,elId);if(field==='name'){var rn=culRoundResolve(rid,false),nt=String(value==null?'':value).trim(),isF=rid==='first:employees'||!!(rn&&rn.context==='firstPulse'); /* 8 Oct 2026 (Batch 4, step 3.3): the round name; the first pulse round is created on a saved name, and a blank name resets it to First pulse */
    if(!isF)return false;if(!rn&&(!nt||nt===CUL_FIRST_NAME))return true;if(!rn)rn=culRoundResolve(rid,true,elId);if(!rn)return false;
    if(culPulseGuard(rn,elId,rn.name||''))return false;rn.name=nt||CUL_FIRST_NAME;if(!nt)culPulseReset(elId,CUL_FIRST_NAME);culTouch();Store.commit('pulseRounds',rn.id);try{refreshGateInPlace()}catch(e){}return true}
  if(field!=='leaderDescription')return false;var r=culRoundResolve(rid,false),text=String(value==null?'':value);
  if(!r){if(!text.trim())return true;r=culRoundResolve(rid,true,elId)}if(!r)return false;
  if(culPulseGuard(r,elId,r.leaderDescription||''))return false;
  r[field]=text;culTouch();Store.commit('pulseRounds',r.id);try{refreshGateInPlace()}catch(e){}return true}

/* ── Calculations (decision 4): calculated, never stored; one place, reused by the steps, the Pulse Round page and the report ── */
function culRoundTeamsAll(){return (data.teams||[]).filter(function(t){return t&&t.id})} /* every team with an id, named or not: Team View and the dashboard Teams tile show an unnamed team under its fallback label (close-out 2 pins) */
function culRoundTeams(){return culNamed('teams','name').filter(function(t){return t.id})} /* named teams only (§26.3, Full pass 5.3); results of a deleted team stay under its id and are ignored here; culTeamsEditor and the id lookups read data.teams directly, so a team being named is still seen there */
function culUnitRes(r,unit){return (r&&r.results&&r.results[unit])||null}
function culUnitVal(r,unit,itemId){var u=culUnitRes(r,unit);return (u&&u.avg)?culNum(u.avg[itemId]):null}
function culUnitResp(r,unit){if(!r)return null;if(r.group==='leaders'&&unit==='org')return culNum(r.leaderRespondents);if(unit==='org'&&r.group!=='leaders'&&culRoundHasTeams(r)){var s=0,any=false;culRoundTeams().forEach(function(t){var u=culUnitRes(r,t.id),v=u?culNum(u.respondents):null;if(v!=null){s+=v;any=true}});return any?s:null} /* the whole organization is the sum of its teams */var u=culUnitRes(r,unit);return u?culNum(u.respondents):null}
function culItemOrg(r,itemId){var entered=culUnitVal(r,'org',itemId),calc=null;
  if(r&&r.group!=='leaders'){var sw=0,s=0,n=0,su=0;culRoundTeams().forEach(function(t){var w=culUnitResp(r,t.id),v=culUnitVal(r,t.id,itemId);if(v!=null){n++;su+=v;if(w>0){sw+=w;s+=w*v}}});if(sw>0)calc=s/sw;else if(n)calc=su/n} /* weighted by respondents; a plain mean of the teams while no respondent counts are in */
  return {used:(r&&r.group!=='leaders'&&culRoundHasTeams(r))?calc:entered,entered:entered,calc:calc}} /* Paul (12 Oct 2026): for employees the organization-wide figure is the respondent-weighted mean of the teams, and no screen lets anyone enter it. A round holding no team figures at all keeps its stored figure: no screen can create one now, and only test fixtures written before the rule still do */
function culRoundHasTeams(r){return !!r&&culRoundTeams().some(function(t){var u=culUnitRes(r,t.id);return !!u&&((culNum(u.respondents)||0)>0||(u.avg&&Object.keys(u.avg).some(function(k){return u.avg[k]!=null})))})} /* the entered figure is used when there is one; otherwise the respondent-weighted mean of the teams that exist, have respondents and have a value */
function culRowItemIds(rowId){var ids=CUL_ITEMS.filter(function(i){return String(i.row)===String(rowId)}).map(function(i){return i.id});return ids} /* added questions retired, 12 Oct 2026 */
function culRowScore(r,rowId,unit){var sum=0,n=0;culRowItemIds(rowId).forEach(function(id){var v=(unit&&unit!=='org')?culUnitVal(r,unit,id):culItemOrg(r,id).used;if(v!=null){sum+=v;n++}});return n?sum/n:null} /* the mean of the row's item scores, added items assigned to the row included; omit unit or pass 'org' for the organization, or pass a team id */
function culOtherItems(r){return []} /* Other items belong to no row and are reported apart */
function culGap(leaders,employees){if(leaders==null||employees==null)return null;return (Math.round(leaders*10)-Math.round(employees*10))/10} /* 25 Oct 2026 (bug hunt B5): the gap is taken between the two scores as displayed (culFmt1 rounds each with Math.round), so a shown gap always equals the difference of the two shown scores */ /* leaders minus employees */
function culLowSafety(score){var v=score==null?null:Math.round(score*10)/10;return v!=null&&v<3.0}
function culTeamLowSafety(r,teamId){return culLowSafety(culRowScore(r,1,teamId))}

/* ── The items of a round (decision 7): culture items, then AI items, each in CUL_ITEMS order, then the organization's added items ── */
function culRoundScopeRows(r){return r&&r.scope==='priority'&&Array.isArray(r.scopeRows)?r.scopeRows:undefined} /* a priority round's own dimensions (Paul's ruling, audit C5-05, 31 Oct 2026) */ function culRoundScopeSet(id,v){if(fldSave('pr_scope_'+id,v)===false)return false;var r=(data.pulseRounds||[]).filter(function(x){return x&&x.id===id})[0];if(r){if(v==='priority')r.scopeRows=culPriorityRows().slice().sort(function(a,b){return a-b});else delete r.scopeRows;Store.commit('pulseRounds',r.id)}render();return true} /* choosing Priority dimensions records which they are */ function culRoundScopeFix(){(data.pulseRounds||[]).forEach(function(r){if(!r||r.scope!=='priority'||Array.isArray(r.scopeRows))return;var rows=[];culQItems(r.group,'full').forEach(function(it){var any=Object.keys(r.results||{}).some(function(u){return culUnitVal(r,u,it.id)!=null});if(any&&rows.indexOf(it.row)<0)rows.push(it.row)});r.scopeRows=(rows.length?rows:culPriorityRows().slice()).sort(function(a,b){return a-b})})} /* an existing priority round takes the dimensions it has answers for, or today's priorities if none (Paul's ruling, audit C5-05, 31 Oct 2026) */ function culQItems(group,scope,rows){var pri=scope==='priority'?(Array.isArray(rows)?rows:culPriorityRows()):scope==='round'?culFirstRows():null,wk=group==='leaders'?'leader':'employee',out=[];
  [false,true].forEach(function(aiFlag){CUL_ITEMS.forEach(function(i){var row=culRowById(i.row);if(!row||!!row.ai!==aiFlag)return;if(pri&&pri.indexOf(i.row)<0)return;out.push({id:i.id,row:i.row,text:i[wk],added:false})})});
  return out} /* Paul (12 Oct 2026): organizations no longer add questions; the questionnaire is the fixed set */
function culGridGroups(items){var gs=[],by={};items.forEach(function(it){var k=String(it.row);if(!by[k]){by[k]={row:it.row,name:it.row==='other'?'Items added by your organization':(culRowById(it.row)||{}).name,items:[]};gs.push(by[k])}by[k].items.push(it)});
  gs.sort(function(a,b){return (a.row==='other'?1:0)-(b.row==='other'?1:0)});return gs}

/* ── Repainting the calculated figures in place, so no keystroke redraws the page ── */
function culPcSpan(kind,ref,a,b,tag){tag=tag||'span';return '<'+tag+' data-pc="'+kind+'" data-ref="'+escAttr(ref)+'" data-a="'+escAttr(a==null?'':a)+'" data-b="'+escAttr(b==null?'':b)+'">'+culPcValue(kind,ref,a,b)+'</'+tag+'>'}
function culPcValue(kind,ref,a,b){if(kind==='s13b'){try{return culS13b()}catch(e){return ''}} if(kind==='respOrg'){var _rr=culRoundResolve(ref,false),_v=_rr?culUnitResp(_rr,'org'):null;return _v!=null?esc(String(_v)):'<span style="color:var(--text-faint)">Not entered</span>'} /* B10 (fix batch 2, 31 Oct 2026) */ var r=culRoundResolve(ref,false),grp=culRefGroup(ref,r);
  if(kind==='rowu'){var s=culRowScore(r,a,b==='org'?null:b);if(s==null)return '<span style="color:var(--text-faint)">–</span>';var t=culFmt1(s);if(String(a)==='1'&&b!=='org'&&culLowSafety(s))t+='<span title="Low psychological safety: below 3.0" style="display:block;color:var(--gold-text);font-weight:700;font-size:12px;line-height:1.3;margin-top:2px">Low safety</span>'; /* below the score, so the row's scores stay level (Paul's visual pass, 26 Oct 2026) */return t}
  if(kind==='orgnote'){var o=culItemOrg(r,a);if(o.entered!=null&&o.calc!=null&&culFmt1(o.entered)!==culFmt1(o.calc))return 'Entered '+culFmt1(o.entered)+'. Calculated from teams '+culFmt1(o.calc)+'. The entered figure is used.';if(o.entered==null&&o.calc!=null)return 'Calculated from teams '+culFmt1(o.calc);return ''}
  if(kind==='chorg'){var cmo=culChoiceMap(r,a);return cmo[b]!=null?cmo[b]+'%':'<span style="color:var(--text-faint);font-weight:400">\u2013</span>'}
  if(kind==='iorg'){var io=culItemOrg(r,a).used;return io!=null?culFmt1(io):'<span style="color:var(--text-faint);font-weight:400">\u2013</span>'}
  if(kind==='tot'&&b){var qt=culChoiceQ(a);if(!qt)return '';var tm=culChoiceTeamMap(r,b,a)||{},st=0,an=false;qt.opts.forEach(function(op){var v=culNum(tm[op.k]);if(v!=null){st+=v;an=true}});if(!an)return '';return st+'%'+((!qt.multi&&st!==100)?'<div style="color:var(--gold-text);font-size:12px">not 100</div>':'')}
  if(kind==='tot'&&r&&culChoiceTeams(r,a).length)return '';
  if(kind==='tot'){var q=culChoiceQ(a);if(!q)return '';var ch=(r&&r.choices&&r.choices[a])||{},sum=0,any=false;q.opts.forEach(function(op){var v=culNum(ch[op.k]);if(v!=null){sum+=v;any=true}});if(!any)return '';
    return '<strong>Total</strong> '+sum+'%'+((!q.multi&&sum!==100)?'<div style="color:var(--gold-text);margin-top:4px">These percentages add up to '+sum+', not 100. Check them against the survey results.</div>':'')}
  if(kind==='prog'){var items=culQItems('leaders',r?r.scope:'full',culRoundScopeRows(r)).filter(function(it){var rw=culRowById(it.row);return a==='culture'?(!rw||!rw.ai):a==='ai'?(!!rw&&rw.ai):true}),n=0;items.forEach(function(it){if(culUnitVal(r,'org',it.id)!=null)n++});return n+' of '+items.length+' questions entered'}
  return ''}
function culPulseRepaint(){var els=document.querySelectorAll('[data-pc]');for(var i=0;i<els.length;i++){var e=els[i];e.innerHTML=culPcValue(e.getAttribute('data-pc'),e.getAttribute('data-ref'),e.getAttribute('data-a'),e.getAttribute('data-b'))}}

/* ── The shared entry grid (decision 5): leaders (who took it, how many, one org column) and employees (a respondents row, one column per team and the whole organization). opts: {group, scope, items, gate (asterisk the leader count), respondentsReadOnly} ── */
function culCellNum(id,ref,lockKey,handler,value,ph,label,cls){var sc=ph==='1.0 to 5.0';return '<input type="'+(sc?'text" inputmode="decimal" autocomplete="off':'number')+'" id="'+escAttr(id)+'" class="score-mini'+(cls?' '+cls:'')+'" data-lock="pulseRounds::'+escAttr(lockKey)+'"'+(sc?'':' step="1" min="0"')+' value="'+escAttr(value)+'" placeholder="'+escAttr(ph)+'" aria-label="'+escAttr(label)+'" title="'+escAttr(label)+'" onchange="'+handler+'">'}
function culTopScrollFit(img){try{var w=img.parentNode,b=w.querySelector('.cul-tsbar'),t=w.querySelector('.cul-tstbl');if(!b||!t)return;b.firstChild.style.width=t.scrollWidth+'px';b.style.display=t.scrollWidth>t.clientWidth+1?'block':'none';b.scrollLeft=t.scrollLeft}catch(e){}} function culTopScrollSync(el,fromBar){try{var w=el.parentNode,o=fromBar?w.querySelector('.cul-tstbl'):w.querySelector('.cul-tsbar');if(o&&o.scrollLeft!==el.scrollLeft)o.scrollLeft=el.scrollLeft}catch(e){}} /* a second scroll bar above a wide scores table: sized once the page is drawn (the hidden image's load event), shown only when the table overflows, and kept in step with the table's own bar (Paul's visual pass, 26 Oct 2026) */
function culPulseGrid(ref,opts){opts=opts||{};var r=culRoundResolve(ref,false),group=opts.group||culRefGroup(ref,r)||'employees',scope=opts.scope||(r&&r.scope)||'full',items=opts.items||culQItems(group,scope,culRoundScopeRows(r)) /* the round's own dimensions (audit C5-R01) */,lk=culRoundLockId(ref,r),q=escAttr(ref),h='';
  h+='<div data-pmsg="'+q+'" role="status" style="font-size:14px;color:var(--gold-text);margin:0 0 8px"></div>';
  var leaders=group==='leaders',teams=leaders?[]:culRoundTeams(),units=leaders?[{k:'org',n:'Average score'+(opts.gate?' *':'')}]:teams.map(function(t){return {k:t.id,n:t.name}}).concat([{k:'org',n:'Whole organization'}]);
  if(leaders&&!opts.hideLeaderFields){
    h+='<div class="mb-4"><label class="form-label" for="prgWho_'+q+'">Who took it</label>'+fhelp('Describe the group of senior people who took the leadership questionnaire, for example by their roles.')+'<textarea id="prgWho_'+q+'" class="ta-helper" rows="2" data-lock="pulseRounds::'+escAttr(lk)+'" placeholder="For example, the executive committee and their direct reports" onchange="culRoundField(\''+q+'\',\'leaderDescription\',this.value,this.id)">'+esc(r&&r.leaderDescription||'')+'</textarea></div>';
    h+='<div class="mb-4"><label class="form-label" for="prgN_'+q+'">Number of leaders who answered'+(opts.gate?' *':'')+'</label>'+fhelp('')+'<input type="number" id="prgN_'+q+'" class="field-input'+(opts.gate?' gate-field'+(opts.gate==='quiet'?' gate-quiet':''):'')+'" style="width:140px" data-lock="pulseRounds::'+escAttr(lk)+'" value="'+escAttr(r&&r.leaderRespondents!=null?r.leaderRespondents:'')+'" placeholder="For example, 14" onchange="culPulseResp(\''+q+'\',\'org\',this.value,this.id)"></div>';
  }else if(!leaders&&!teams.length&&!opts.hideRespondents){h+='<p class="t-lead" style="margin:0 0 12px">No teams yet. Add teams in step 1.2.</p>'}
  var respRow=function(){return '<tr><td style="padding:8px">Respondents</td>'+units.map(function(u){var v=culUnitResp(r,u.k);
    return '<td style="text-align:center;padding:6px 8px">'+((opts.respondentsReadOnly||(u.k==='org'&&!leaders))?('<span data-pc="respOrg" data-ref="'+escAttr(ref)+'">'+(v!=null?esc(String(v)):'<span style="color:var(--text-faint)">Not entered</span>')+'</span>'):culCellNum('prgR_'+ref+'_'+u.k,ref,lk,'culPulseResp(\''+q+'\',\''+escAttr(u.k)+'\',this.value,this.id)',v!=null?String(v):'','Number of people',u.n+' respondents',(opts.gate?('gate-field'+(opts.gate==='quiet'?' gate-quiet':'')):'')))+'</td>'}).join('')+'</tr>'};
  if(opts.respondentsOnly&&!leaders){if(!teams.length)return h;
    return h+'<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border-faint)">Number of people who answered</th>'+units.map(function(u){return '<th style="text-align:center;padding:6px 8px;border-bottom:1px solid var(--border-faint);font-weight:600;min-width:72px">'+esc(u.n)+'</th>'}).join('')+'</tr></thead><tbody>'+respRow()+'</tbody></table></div>'}
  if(opts.leaderFieldsOnly||!items.length)return h;
  h+='<div class="cul-tsw"><div class="cul-tsbar" style="overflow-x:auto;overflow-y:hidden;display:none" onscroll="culTopScrollSync(this,true)"><div style="height:1px"></div></div><div class="cul-tstbl" style="overflow-x:auto" onscroll="culTopScrollSync(this,false)"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border-faint);min-width:200px">Question</th>'+units.map(function(u){return '<th style="text-align:center;padding:6px 8px;border-bottom:1px solid var(--border-faint);font-weight:600;min-width:72px">'+esc(u.n)+'</th>'}).join('')+'</tr></thead><tbody>';
  if(!leaders&&!opts.hideRespondents)h+=respRow();
  culGridGroups(items).forEach(function(g){
    h+='<tr><td style="padding:30px 8px 4px;font-weight:700;vertical-align:top">'+esc(g.name)+'</td>'+units.map(function(u){return g.row==='other'?'<td></td>':'<td style="text-align:center;font-weight:700;padding:30px 8px 4px;vertical-align:top">'+culPcSpan('rowu',ref,g.row,u.k)+'</td>'}).join('')+'</tr>';
    g.items.forEach(function(it){h+='<tr><td style="padding:6px 8px;line-height:1.5;min-width:200px;vertical-align:middle;border-bottom:1px solid var(--border-softer)">'+esc(it.text)+'</td>'+units.map(function(u){var v=culUnitVal(r,u.k,it.id);
      if(!leaders&&u.k==='org'){return '<td style="text-align:center;padding:6px 8px;vertical-align:middle;font-weight:600;border-bottom:1px solid var(--border-softer)">'+culPcSpan('iorg',ref,it.id,'')+'</td>'} /* Paul (12 Oct 2026): calculated, never entered */
      return '<td style="text-align:center;padding:6px 8px;vertical-align:middle;border-bottom:1px solid var(--border-softer)">'+culCellNum('prg_'+ref+'_'+u.k+'_'+it.id,ref,lk,'culPulseSet(\''+q+'\',\''+escAttr(u.k)+'\',\''+escAttr(it.id)+'\',this.value,this.id)',v!=null?culFmt1(v):'','1.0 to 5.0',(leaders?'Average score':u.n+' average score')+' for '+it.text,(opts.gate?('gate-field'+(opts.gate==='quiet'?' gate-quiet':'')):''))+'</td>'}).join('')+'</tr>'})});
  h+='</tbody></table></div><img alt="" src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7" onload="culTopScrollFit(this)" style="display:none"></div>';
  h+='<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:12px 0 0">Scale: 1 Strongly disagree, 2 Disagree, 3 Neither agree nor disagree, 4 Agree, 5 Strongly agree.</p>';
  if(leaders)h+='<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:6px 0 0"> '+culPcSpan('prog',ref,opts.progKind||'','')+'</p>';
  else h+='<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:6px 0 0">The app calculates the whole-organization column from the teams. Each score is the average of the team scores, weighted by how many people answered in each team, and the number of people is the total across the teams.</p>';
  return h}

/* ── The multiple-choice percentage grid (employee full rounds): respondents per question, whole percents, a total per question ── */
function culChoiceGrid(ref,opts){opts=opts||{};var r=culRoundResolve(ref,false),lk=culRoundLockId(ref,r),q=escAttr(ref),teams=culRoundTeams(),h='<div data-pmsg="'+q+'" role="status" style="font-size:14px;color:var(--gold-text);margin:0 0 8px"></div>'; /* Paul (12 Oct 2026): the multiple-choice answers are entered team by team, and the whole organization is calculated */
  if(!teams.length)return ''; /* the score grid above already says there are no teams */
  var th='padding:6px 8px;border-bottom:1px solid var(--border-faint);font-weight:600;min-width:72px;text-align:center',td='text-align:center;padding:6px 8px;vertical-align:middle;border-bottom:1px solid var(--border-softer)';
  CUL_MC.filter(function(mc){return !opts.keys||opts.keys.indexOf(mc.k)>=0}).forEach(function(mc){
    h+='<div style="margin:0 0 26px"><div style="font-weight:700;font-size:15px;line-height:1.5;margin:0 0 6px">'+esc(mc.q)+'</div>'
      +fhelp(mc.multi?'Enter the percentage of each team that chose each option. Employees could choose more than one option, so a team\'s percentages can add up to more than 100.':'Enter the percentage of each team that gave each answer. Each team\'s percentages should add up to 100.')
      +'<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border-faint);min-width:200px">Option</th>'
      +teams.map(function(tm){return '<th style="'+th+'">'+esc(tm.name)+'</th>'}).join('')+'<th style="'+th+'">Whole organization</th></tr></thead><tbody>';
    mc.opts.forEach(function(o){h+='<tr><td style="padding:6px 8px;vertical-align:middle;border-bottom:1px solid var(--border-softer)">'+esc(o.label)+(opts.marks?opts.marks(mc.k,o.k):'')+(o.def?'<div style="font-size:13px;color:var(--stone)">'+esc(o.def)+'</div>':'')+'</td>'
      +teams.map(function(tm){var v=(culChoiceTeamMap(r,tm.id,mc.k)||{})[o.k];return '<td style="'+td+'">'+culCellNum('prgC_'+ref+'_'+tm.id+'_'+mc.k+'_'+o.k,ref,lk,'culChoiceSet(\''+q+'\',\''+mc.k+'\',\''+o.k+'\',this.value,this.id,\''+escAttr(tm.id)+'\')',v!=null?String(v):'','0 to 100',tm.name+', '+o.label+' percentage')+'</td>'}).join('')
      +'<td style="'+td+';font-weight:600">'+culPcSpan('chorg',ref,mc.k,o.k)+'</td></tr>'});
    h+=(mc.multi?'':'<tr><td style="padding:8px;font-weight:600">Total</td>'+teams.map(function(tm){return '<td style="text-align:center;padding:8px;font-size:13px">'+culPcSpan('tot',ref,mc.k,tm.id)+'</td>'}).join('')+'<td></td></tr>')+'</tbody></table></div>' /* no total where people may tick several answers, since the sum can pass 100% (UAT, 31 Oct 2026) */
      +'<p style="font-size:13px;color:var(--stone);line-height:1.6;margin:8px 0 0">The app calculates the whole-organization column from the teams, weighted by how many people answered in each team.</p></div>'});
  return h}

/* ── Bars (decision C): rows as labelled bars on theme tokens. A bar's track is 7px and its fill is the score out of 5. ── */
var CUL_BAR_L='var(--head-blue)',CUL_BAR_E='var(--gold-text)';
function culBarTrack(v,color,hgt){var w=v==null?0:Math.max(0,Math.min(100,v/5*100));return '<div style="height:'+(hgt||7)+'px;background:rgba(var(--fg-rgb),.08);border-radius:4px;overflow:hidden"><div style="height:100%;width:'+w+'%;background:'+color+';border-radius:4px"></div></div>'}
function culScoreText(v){return v==null?'<span style="color:var(--text-faint)">Not entered</span>':culFmt1(v)+' / 5'}
function culBarRound(round,opts){var r=typeof round==='string'?culRoundResolve(round,false):round;return r||{group:(opts&&opts.group)||'employees',scope:'full',results:{},choices:{}}}
function culBars(round,opts){opts=opts||{};var r=culBarRound(round,opts),items=culQItems(r.group,r.scope||'full',culRoundScopeRows(r)),h='';
  CUL_ROWS.forEach(function(row){if(opts.ai!==undefined&&!!row.ai!==!!opts.ai)return;var its=items.filter(function(it){return String(it.row)===String(row.id)});if(!its.length)return;var s=culRowScore(r,row.id);
    h+='<div style="margin:0 0 18px"><div style="display:grid;grid-template-columns:40% 1fr 110px;gap:12px;align-items:center"><div style="font-weight:700;font-size:14px">'+esc(row.name)+'</div>'+culBarTrack(s,CUL_BAR_L)+'<div style="text-align:right;font-family:var(--mono);font-size:13px">'+culScoreText(s)+'</div></div>'
      +'<div style="margin:6px 0 0 0">'+its.map(function(it){return '<div style="display:flex;justify-content:space-between;gap:16px;font-size:13px;color:var(--stone);line-height:1.5;padding:2px 0"><span>'+esc(it.text)+'</span><span style="font-family:var(--mono);white-space:nowrap">'+culScoreText(culItemOrg(r,it.id).used)+'</span></div>'}).join('')+'</div></div>'});
  var oth=items.filter(function(it){return it.row==='other'});
  if(oth.length&&!opts.noOther)h+='<div style="margin:22px 0 0"><div style="font-weight:700;font-size:14px;margin:0 0 6px">Items added by your organization</div>'+oth.map(function(it){return '<div style="display:flex;justify-content:space-between;gap:16px;font-size:13px;color:var(--stone);line-height:1.5;padding:2px 0"><span>'+esc(it.text)+'</span><span style="font-family:var(--mono);white-space:nowrap">'+culScoreText(culItemOrg(r,it.id).used)+'</span></div>'}).join('')+'</div>';
  return h}
function culGapText(g){return g==null?'':((g>0?'+':(g<0?'−':''))+Math.abs(g).toFixed(1))}
function culPairedBars(lRound,eRound,opts){opts=opts||{};var lr=culBarRound(lRound,{group:'leaders'}),er=culBarRound(eRound,{group:'employees'}),h='';
  h+='<div style="display:flex;gap:20px;flex-wrap:wrap;font-size:13px;color:var(--text-body);margin:0 0 12px"><span><span style="display:inline-block;width:12px;height:7px;border-radius:3px;background:'+CUL_BAR_L+';margin-right:6px"></span>Leaders</span><span><span style="display:inline-block;width:12px;height:7px;border-radius:3px;background:'+CUL_BAR_E+';margin-right:6px"></span>Employees</span></div>';
  CUL_ROWS.forEach(function(row){if(opts.ai!==undefined&&!!row.ai!==!!opts.ai)return;if(!culRowItemIds(row.id).length)return;var l=culRowScore(lr,row.id),e=culRowScore(er,row.id),g=culGap(l,e);
    h+='<div style="display:grid;grid-template-columns:34% 1fr 150px;gap:12px;align-items:center;margin:0 0 14px"><div style="font-weight:700;font-size:14px">'+esc(row.name)+'</div><div style="display:flex;flex-direction:column;gap:5px">'+culBarTrack(l,CUL_BAR_L)+culBarTrack(e,CUL_BAR_E)+'</div>'
      +'<div style="font-family:var(--mono);font-size:12.5px;line-height:1.6;text-align:right"><div>'+(l==null?'<span style="color:var(--text-faint)">Not entered</span>':culFmt1(l))+'</div><div>'+(e==null?'<span style="color:var(--text-faint)">Not entered</span>':culFmt1(e))+'</div><div style="font-weight:700">'+(g==null?'':'Gap '+culGapText(g))+'</div></div></div>'});
  return h}
/* Teams down, culture rows across (decision 15). opts.ai shows the AI rows instead. The name culPsHeatmap is retired and pinned absent. */
function culTeamGrid(round,opts){opts=opts||{};var r=culBarRound(round,{group:'employees'}),rows=CUL_ROWS.filter(function(x){return !!x.ai===!!opts.ai}),teams=culRoundTeams();
  if(!teams.length)return '<p class="t-lead" style="margin:0">No teams yet. Add teams in step 1.2.</p>';
  var h='<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr><th style="text-align:left;padding:6px 8px;border-bottom:1px solid var(--border-faint)">Team</th>'+rows.map(function(x){return '<th style="text-align:center;padding:6px 8px;border-bottom:1px solid var(--border-faint);font-weight:600;min-width:84px">'+esc(x.name)+'</th>'}).join('')+'</tr></thead><tbody>';
  teams.forEach(function(t){h+='<tr><td style="padding:7px 8px;border-bottom:1px solid var(--border-softer)">'+esc(t.name)+'</td>'+rows.map(function(x){var s=culRowScore(r,x.id,t.id),low=(x.id===1&&culLowSafety(s));return '<td style="text-align:center;padding:7px 8px;border-bottom:1px solid var(--border-softer)'+(low?';background:rgba(var(--gold-rgb),.14);font-weight:700':'')+'">'+(s==null?'<span style="color:var(--text-faint)">–</span>':culFmt1(s)+(low?' <span title="Low psychological safety: below 3.0" style="color:var(--gold-text)">Low safety</span>':''))+'</td>'}).join('')+'</tr>'});
  h+='<tr><td style="padding:7px 8px;font-weight:700">Whole organization</td>'+rows.map(function(x){var s=culRowScore(r,x.id);return '<td style="text-align:center;padding:7px 8px;font-weight:700">'+(s==null?'<span style="color:var(--text-faint)">–</span>':culFmt1(s))+'</td>'}).join('')+'</tr></tbody></table></div>';
  return h}
/* The same bars on paper: a headed block of label, bar and score rows, plain, for the Baseline Report parts. Rows with no score are left out (§22.4.7). */
function culDocBars(round,opts){opts=opts||{};var r=culBarRound(round,opts),h='';
  CUL_ROWS.forEach(function(row){if(opts.ai!==undefined&&!!row.ai!==!!opts.ai)return;var s=culRowScore(r,row.id);if(s==null)return;var w=Math.max(0,Math.min(100,s/5*100));
    h+='<tr><td style="width:40%;padding:5px 10px;font-size:12.5px;color:#111;border-bottom:1px solid #eee">'+esc(row.name)+'</td><td style="padding:5px 10px;border-bottom:1px solid #eee"><div style="height:7px;background:#e5e5e5;border-radius:4px"><div style="height:7px;width:'+w+'%;background:#333;border-radius:4px"></div></div></td><td style="width:90px;padding:5px 10px;text-align:right;font-family:var(--mono,monospace);font-size:12.5px;color:#111;border-bottom:1px solid #eee">'+culFmt1(s)+' / 5</td></tr>'});
  return h}

/* ── Opening a questionnaire, and the page chrome (ruling 7: Architecture's standalone page — back button, 22px heading, 14px lead, cards) ──
   Architecture's page draws the family back button, which draws nothing when there is no history. These two pages can be opened from a step, a link or a
   bookmark, so they fall back to a Back button that returns home (logged as a conflict; the family rule on the back button is kept for every other page). */
function culBackBtn(){return navHistory.length?backBtn():'<button class="btn-ghost pad-chip-sm" onclick="go(\'home\')">← Back</button>'}
function culOpenQ(group,scope,rid){UI.qGroup=group==='employees'?'employees':'leaders';UI.qScope=scope==='priority'||scope==='round'?scope:'full';UI.qRound=rid||''; /* a round's questionnaire shows that round's own dimensions (audit C5-R01) */UI.qNote='';go('questionnaire')}
function culPageHead(title,lead){return printBar()+'<h2 style="font-size:22px;font-weight:700;margin:0 0 4px">'+esc(title)+'</h2><p class="t-lead">'+esc(lead)+'</p>'}
var CUL_CONTEXT_WORDS={baseline:'Baseline',firstPulse:'First pulse round',day90:'Day 90',review:'Pulse round'} /* copy pass, Pass 2 (20 Oct 2026): every round started with + New round has context 'review'; it is an ordinary pulse round, not a Culture Review */;
var CUL_SCALE_LINE='Scale: 1 Strongly disagree, 2 Disagree, 3 Neither agree nor disagree, 4 Agree, 5 Strongly agree.';

/* ── The Pulse Round page (decision 6), route 'pulseRound' ── */
function culRoundNew(){try{sweepBlankInline(true)}catch(e){}if(currentPage!=='pulseRound'){UI.pulseRoundId=null;go('pulseRound')} /* from the Dashboard, open the Pulse Round page first, so the new round is made where it is filled in (Paul, 28 Oct 2026) */ var r={id:culNew('pulseRounds'),date:'',name:'',group:'',scope:'',context:'review',results:{},choices:{}};culEnsure('pulseRounds',[]).push(r);culInlineAdded('pulseRounds');UI.pulseRoundId=r.id;culTouch();Store.commit('pulseRounds',r.id);render()} /* a draft until it is named (§26.3) */
function culRoundPick(id){try{sweepBlankInline(true)}catch(e){}UI.pulseRoundId=id;render()}
function culRoundDel(id){var list=culLinksTo('pulseRounds',id);if(culDelBlocked('pulseRounds',id,list))return;var n=list.filter(function(l){return l.act==='strip'}).length,g=list.some(function(l){return l.act==='remove'}),m='Remove this round? Any results entered for it will also be removed.';if(n)m+=' It will be removed from '+n+(n===1?' record that links':' records that link')+' to it.';if(g)m+=' '+CUL_LINKS.pulseRounds.goneText.charAt(0).toUpperCase()+CUL_LINKS.pulseRounds.goneText.slice(1)+' will be deleted too.';if(!confirm(m))return;culUnlinkApply('pulseRounds',id,list);Store.removeRec('pulseRounds',id);if(UI.pulseRoundId===id)UI.pulseRoundId=null;culTouch();render()}
function culRoundsNewestFirst(){var L=(data.pulseRounds||[]).map(function(r,i){return {r:r,i:i}}).filter(function(p){return p.r&&p.r.id}),last='';L.forEach(function(p){var d=culPmDateOk(p.r.date)?String(p.r.date):'';p.k=d||last;if(d)last=d});return L.sort(function(a,b){return String(b.k).localeCompare(String(a.k))||b.i-a.i}).map(function(p){return p.r})} /* B5 (fix batch 2, 31 Oct 2026; Paul's ruling Q-1): rounds by date; a round with no date takes the date of the latest dated round created before it, so it is never the newest by default */
function culRoundSummary(r){var bits=[];if(r.date)bits.push(culDatesText(r));bits.push(r.group==='leaders'?'Leaders':r.group==='employees'?'Employees':'Group not chosen');bits.push(r.scope==='priority'?'Priority dimensions only':r.scope==='full'?'Full questionnaire':'Scope not chosen');bits.push(CUL_CONTEXT_WORDS[r.context]||CUL_CONTEXT_WORDS.review);return bits.join(' · ')}
function renderPulseRound(){var h=renderPulseRound0(),rd=culRoundById(UI.pulseRoundId);if(rd&&culD90Locked(rd)){h=h.replace(/<(input|textarea|select) /g,'<$1 disabled ');h=h.replace('<!--pr-head-end-->','<p style="font-size:13px;color:var(--stone);margin:0 0 10px" data-d90-locked="1">'+esc(CUL_RV_COPY['pulse.d90.locked'])+'</p>')}return h}
function culTeamsMissingResp(r,items){if(!r)return [];return culRoundTeams().filter(function(t){return (items||[]).some(function(it){return culUnitVal(r,t.id,it.id)!=null})&&!(culUnitResp(r,t.id)>=1)})} /* the participating-team rule for every employee round: a team with any score needs its respondent count, or it drops out of the organization's average unseen (31 Oct 2026 ruling; audit C1-01, C3-R02, C4-R02) */ function culPrHasScores(rd){if(!rd||!rd.results)return false;var its=[];try{its=culQItems(rd.group||'employees',rd.scope==='priority'?'priority':(rd.scope||'full'),culRoundScopeRows(rd))||[]}catch(e){its=[]}var units=Object.keys(rd.results);if(!its.length)return units.some(function(u){var a=rd.results[u]&&rd.results[u].avg;return !!a&&Object.keys(a).some(function(k){return a[k]!=null})});return units.some(function(u){return its.some(function(it){return culUnitVal(rd,u,it.id)!=null})})} /* a real score for the round's own population, not just a respondents entry or an emptied object (audit C5-R03) */ function culPrDone(rd,n){if(!rd)return false;if(n===1)return !!(rd.group&&rd.scope&&String(rd.name||'').trim());if(n===2)return !!culPmDateOk(rd.date);if(n===3)return culPrHasScores(rd);return false} function culPrTabOf(rd){UI.prStage=UI.prStage||{};var t=UI.prStage[rd.id];if(t>=1&&t<=4)return t;for(var n=1;n<=3;n++)if(!culPrDone(rd,n))return n;return 4} function culPrTabSet(rid,n){n=Number(n);if(!(n>=1&&n<=4))return false;UI.prStage=UI.prStage||{};UI.prStage[rid]=n;render();return true} function culPrTabs(rd){var cur=culPrTabOf(rd),L=['1. Prepare','2. Who took it','3. Results','4. Read the results'];return '<div class="cul-urtabs cul-pstabs" role="tablist" style="margin-top:6px">'+L.map(function(l,i){var n=i+1;return '<button type="button" role="tab" class="cul-urtab'+(n===cur?' on':'')+'" aria-selected="'+(n===cur)+'" onclick="culPrTabSet(\''+culFoldJs(rd.id)+'\','+n+')">'+(culPrDone(rd,n)?'<span class="tk">\u2713</span> ':'')+esc(l)+'</button>'}).join('')+'</div>'} function culPrStage(n,t,l,body){var rd=(data.pulseRounds||[]).filter(function(r){return r&&r.id===UI.pulseRoundId})[0],on=!rd||culPrTabOf(rd)===n;return '<div role="tabpanel" data-prstage="'+n+'"'+(on?'':' hidden')+'>'+culStage(n,t,l,body)+'</div>'} /* every stage is drawn; only the open tab shows (Paul, 28 Oct 2026) */ /* the open round in four tabs, one per stage, each ticked when complete; a round opens on its first unfinished stage (Paul, 28 Oct 2026) */
function renderPulseRound0(){var h='<div class="content-area"><div class="content-inner">'+'<div class="u-79840ab">'+culBackBtn()+'<div class="u-463b2e1">'+esc('Pulse Round')+'</div></div>'+'<div class="step-header"><div class="step-eyebrow">Ongoing</div><h1 class="step-title">Pulse Round</h1><p class="step-subtitle">This page keeps every pulse round you have run, so you can set the latest results beside earlier ones.</p></div><!--pr-head-end-->'+culRvProgLine()+culPulseIntro('A pulse round is a later run of the questionnaire from step 1.2, for employees or for leaders. The questionnaire itself runs outside this app, in your survey tool. On this page you choose the group and the scope, prepare the questionnaire, record who took it and when, enter the average scores, and read the results.');
  var rounds=culRoundsNewestFirst(),rd=culRoundById(UI.pulseRoundId);
  h+=card('<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 12px"><h3 class="h-sub" style="margin:0">Rounds so far</h3>'+btnAdd('+ New round','culRoundNew()')+'</div>'
    +(rounds.length?rounds.map(function(r){var on=rd&&rd.id===r.id;return '<div onclick="culRoundPick(\''+escAttr(r.id)+'\')" style="cursor:pointer;padding:12px 14px;margin:0 0 6px;border:1px solid '+(on?'var(--gold-text)':'var(--border-faint)')+';background:'+(on?'rgba(var(--gold-rgb),.08)':'transparent')+'"><div style="font-weight:700;font-size:15px">'+esc(r.name||'Unnamed round')+'</div><div style="font-size:13px;color:var(--stone);margin-top:2px">'+esc(culRoundSummary(r))+'</div>'+(on&&(!r.date||!culPrHasScores(r))?'<div class="cul-prfill">Fill in details below.</div>':'')+'</div>' /* the open round says it still needs its details (Paul, 27 Oct 2026) */}).join(''):'<p class="t-lead" style="margin:0">No rounds recorded yet.</p>')+(!rd&&rounds.length?'<p class="t-lead" style="margin:12px 0 0">Choose a round to see its setup and results, or add a new one.</p>':''),'padding:20px 24px;margin-bottom:20px');
  if(!rd)return h+'</div></div>';
  var id=rd.id,base=rd.context==='baseline'||rd.context==='firstPulse'||rd.context==='day90',ready=!!(rd.group&&rd.scope),named=!!String(rd.name||'').trim(),pri=culPriorityRows(),priEmpty=rd.scope==='priority'&&!((culRoundScopeRows(rd)||pri).length); /* a round with its own dimensions is never empty because today's priorities are (audit C5-R01) */
  var fact=function(label,val,help){return '<div class="mb-4"><div class="form-label">'+esc(label)+'</div>'+fhelp(help)+'<div style="font-size:14px;color:var(--text-body)">'+esc(val)+'</div></div>'};
  var gHelp='Whether this round is for employees or for leaders.',sHelp='“Full questionnaire” includes every item. “Priority dimensions only” includes the items for the dimensions the organization has marked as priorities.';
  h+='<p style="font-size:14px;color:var(--stone);margin:0 0 12px">Working on: '+esc(rd.name||'Unnamed round')+'</p>';
  var s1=(inp('Round name','pr_name_'+id,rd.name||'','For example, Quarter 1 2027 pulse','text','A short name so that you can recognize this round later.'))+(base?fact('Group',rd.group==='leaders'?'Leaders':'Employees',gHelp):sel('Group','pr_group_'+id,rd.group||'',[{v:'',l:'Choose a group'},{v:'employees',l:'Employees'},{v:'leaders',l:'Leaders'}],gHelp));
  s1+=base?fact('Scope',rd.scope==='priority'?'Priority dimensions only':'Full questionnaire',sHelp):(sel('Scope','pr_scope_'+id,rd.scope||'',[{v:'',l:'Choose a scope'},{v:'full',l:'Full questionnaire'},{v:'priority',l:'Priority dimensions only'}],sHelp)).split('fldSave(this.id,this.value)').join("culRoundScopeSet('"+id+"',this.value)");
  if(!ready)s1+='<p class="t-lead" style="margin:0">Choose a group and a scope to see the questionnaire.</p>';
  else if(priEmpty)s1+='<p class="t-lead" style="margin:0" data-priority-empty="1">No priority dimensions are marked yet. Choose “Full questionnaire” as this round’s scope, or mark the priority dimensions in step 2.1 first.</p>';
  else{var n=culQItems(rd.group,rd.scope,culRoundScopeRows(rd)).length,sc=rd.scope==='priority'?'priority dimensions only':'full questionnaire';
    s1+='<p class="t-lead" style="margin:0 0 10px">'+esc((rd.group==='leaders'?'Leadership questionnaire':'Employee questionnaire')+', '+sc+'. '+n+(n===1?' scaled item.':' scaled items.'))+'</p>';
    if(rd.group==='employees')s1+='<p class="t-lead" style="margin:0 0 12px">'+esc(rd.scope==='priority'?'A priority-dimensions round has only the scaled items for the priority dimensions, worded for employees.':'A full employee questionnaire also includes three multiple-choice questions on what AI is for and how people use it, and three optional open questions on fears and trust.')+'</p>';
    s1+='<div class="cul-actline">'+btn('View questionnaire','culOpenQ(\''+rd.group+'\',\''+rd.scope+'\',\''+rd.id+'\')','bs')+'<p class="cul-actnote">The questionnaire shows every item in order, with the scale. Copy the questionnaire or save it as a PDF.</p></div>'}
  h+=culPrTabs(rd); h+=culPrStage(1,'Prepare the questionnaire',base?'This round'+"\u2019"+'s group and questionnaire are set. View the questionnaire to copy it into your survey tool or save it as a PDF.':'Choose who takes this round and how much of the questionnaire it covers, then copy the questionnaire or save it as a PDF.',s1);
  var s2=''; /* the round name moved to the top of Prepare, so a new round is named, and kept, from the start (Paul, final pass) */
  s2+=culSurveyDates(id,rd);
  if(rd.group&&rd.scope&&named&&!priEmpty)s2+='<div style="margin:18px 0 0">'+(rd.group==='leaders'?culPulseGrid(id,{group:'leaders',scope:rd.scope,leaderFieldsOnly:true}):culPulseGrid(id,{group:'employees',scope:rd.scope,respondentsOnly:true}))+'</div>';
  if(!base)s2+='<div style="margin:18px 0 0">'+btn('Remove round','culRoundDel(\''+escAttr(id)+'\')','bg2')+'</div>';
  h+=culPrStage(2,'Record who took it','Record when this round of the questionnaire ran and how many people took it.',s2);
  var s3;
  if(!ready)s3='<p class="t-lead" style="margin:0">Results appear here once you choose a group and a scope.</p>';
  else if(priEmpty)s3='<p class="t-lead" style="margin:0">No priority dimensions are marked yet. Choose “Full questionnaire” as this round’s scope, or mark the priority dimensions in step 2.1 first.</p>';
  else if(!named)s3='<p class="t-lead" style="margin:0">Give the round a name before you enter results. A round without a name is not kept.</p>';
  else{s3=culPulseGrid(id,{group:rd.group,scope:rd.scope,hideLeaderFields:true,hideRespondents:true});
    if(rd.group==='employees'&&rd.scope==='full')s3+='<h4 class="h-sub" style="margin:26px 0 12px">Questions about AI at work</h4>'+culChoiceGrid(id)}
  h+=culPrStage(3,'Enter the results','Enter the average score for each item, including any items your organization added. Scores run from 1.0 to 5.0.',s3);
  var any=ready&&!priEmpty&&culQItems(rd.group,rd.scope,culRoundScopeRows(rd)).some(function(it){return culItemOrg(rd,it.id).used!=null});
  h+=culPrStage(4,'Read the results','Each dimension shows its score, with the scores of its items below it.',any?culBars(rd):'<p class="t-lead" style="margin:0">Results will appear here once you enter the scores in stage 3.</p>');
  return h+'</div></div>'}

/* ── The questionnaire views (decision 7), route 'questionnaire': one model, drawn on screen, copied as plain text, printed ── */
function culQModel(g,sc){var L=g==='leaders',m={group:g,scope:sc,title:L?'Leadership Questionnaire':'Employee Questionnaire',empty:false,blocks:[],
    intro:L?'This is the leadership questionnaire for the scope you chose. It lists the items in a fixed order, with any items your organization added at the end. Copy it into your survey tool or save it as a PDF.':'This is the employee questionnaire for the scope you chose. It lists the items in a fixed order, with any items your organization added at the end. The full questionnaire also has multiple-choice and open questions. Copy it into your survey tool or save it as a PDF.',
    printLead:L?'The leadership questionnaire, with its items in the order they are asked.':'The employee questionnaire, with its items in the order they are asked.',
    instr:L?'Answer every statement about the organization as a whole, as you understand it. Do not answer about your own experience, and do not try to predict how employees will answer.':'Answer each statement as honestly as you can. In this questionnaire, "my team" means the team you work in day to day.'+(sc==='full'?' The open questions at the end are optional.':''), /* Paul (20 Oct 2026): only the full employee questionnaire has open questions */
    scale:CUL_SCALE_LINE};
  var _qr=UI.qRound?culRoundResolve(UI.qRound,false):null,_qrows=culRoundScopeRows(_qr); if((sc==='priority'||sc==='round')&&!((_qrows||culPriorityRows()).length)&&!(sc==='round'&&culFirstRows().length)){m.empty=true;return m}
  var it=culQItems(g,sc,_qrows), /* the round's own dimensions when opened from a round (audit C5-R01) */n=0,take=function(list){return list.map(function(i){n++;return {n:n,text:i.text}})};
  var cul=it.filter(function(i){return !i.added&&!culRowById(i.row).ai}),ai=it.filter(function(i){return !i.added&&culRowById(i.row).ai}),ad=it.filter(function(i){return i.added});
  if(cul.length)m.blocks.push({heading:'Culture items',entries:take(cul)});
  if(ai.length)m.blocks.push({heading:'AI items',entries:take(ai)});
  if(!L&&sc==='full'){
    m.blocks.push({heading:'Questions about AI at work',note:'Choose one answer for each question, unless it says to select all that apply.',entries:CUL_MC.map(function(q){n++;return {n:n,text:q.q,opts:q.opts.map(function(o){return o.label+(o.def?' – '+o.def:'')})}})});
    m.blocks.push({heading:'Open questions',note:'Write as much or as little as you like. You can leave these blank.',entries:CUL_OPEN_Q.map(function(q){n++;return {n:n,text:q.q}})})}
  /* Paul (19 Oct 2026, visual pass): no box for items added by the organization, since organizations no longer add their own questions (decision 22) */
  return m}
function culQText(m){var t=[m.title,'',m.intro,'',m.instr,'',m.scale];if(m.empty)t.push('','No priority dimensions are marked yet. Choose “Full questionnaire” as this round’s scope, or mark the priority dimensions in step 2.1 first.');
  m.blocks.forEach(function(b){t.push('',b.heading);if(b.note)t.push(b.note);if(b.none)t.push(b.none);b.entries.forEach(function(e){t.push(e.n+'. '+e.text);(e.opts||[]).forEach(function(o){t.push('   - '+o)})})});return t.join('\n')}
function culQCopy(){var m=culQModel(UI.qGroup==='employees'?'employees':'leaders',UI.qScope==='priority'?'priority':'full'),txt=culQText(m);
  var fail=function(){UI.qNote='The text could not be copied. Select it and copy it yourself.';render()},good=function(){UI.qNote='Copied to clipboard.';render()};
  try{if(typeof navigator!=='undefined'&&navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(good,fail)}else fail()}catch(e){fail()}}
function culQPrint(){var m=culQModel(UI.qGroup==='employees'?'employees':'leaders',UI.qScope==='priority'?'priority':'full'),h=printDocCover(m.title,m.printLead,'');
  h+='<p style="font-size:14px;color:#222;line-height:1.6;margin:0 0 8px">'+esc(m.instr)+'</p><p style="font-size:13px;color:#444;line-height:1.6;margin:0 0 20px">'+esc(m.scale)+'</p>';
  if(m.empty)h+='<p style="font-size:14px;color:#222">No priority dimensions are marked yet. Choose “Full questionnaire” as this round’s scope, or mark the priority dimensions in step 2.1 first.</p>';
  m.blocks.forEach(function(b){var rows='';b.entries.forEach(function(e){rows+='<tr><td style="width:34px;padding:5px 6px;vertical-align:top;font-size:12.5px;color:#555;border-bottom:1px solid #eee">'+e.n+'.</td><td style="padding:5px 10px;vertical-align:top;font-size:12.5px;color:#111;line-height:1.5;border-bottom:1px solid #eee">'+esc(e.text)+((e.opts&&e.opts.length)?'<div style="margin-top:4px;color:#444">'+e.opts.map(function(o){return '<div>• '+esc(o)+'</div>'}).join('')+'</div>':'')+'</td></tr>'});
    if(b.none)rows+='<tr><td colspan="2" style="padding:5px 10px;font-size:12.5px;color:#444">'+esc(b.none)+'</td></tr>';
    h+=docSection(b.heading,rows,b.note||'')});
  printDocument(m.title,h,'')}
function renderQuestionnaire(){var g=UI.qGroup==='employees'?'employees':'leaders',sc=UI.qScope==='priority'||UI.qScope==='round'?UI.qScope:'full',m=culQModel(g,sc);if(sc==='round'){m.title='Pulse round questionnaire';m.intro='This round'+"\u2019"+'s questionnaire holds the items from the baseline questionnaire for your priority dimensions. Add any other dimension you want to measure in this round. Copy the questionnaire into your survey tool, or save it as a PDF.'}
  var h='<div class="content-area"><div class="content-inner">'+culBackBtn()+'<div class="print-bar" style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px"><h2 style="font-size:22px;font-weight:700;margin:0 0 4px">'+esc(m.title)+'</h2><button class="btn bg2" onclick="culQPrint()">\u25BE Save as PDF</button></div><p class="t-lead">'+esc(m.intro)+'</p>';
  if(sc==='round'){var pr=culPriorityRows(),fr=culFirstRows();h+=card('<h3 class="h-sub" style="margin:0 0 6px">Dimensions in this round</h3><p class="cul-sec-purpose" style="margin:0 0 10px">The questionnaire always includes the priority dimensions. Tick any other dimension to add its items.</p><div class="cul-qdims">'+CUL_ROWS.map(function(rw){var isP=pr.indexOf(rw.id)>=0,on=fr.indexOf(rw.id)>=0;return '<label class="cul-tickline"><input type="checkbox"'+(on?' checked':'')+(isP?' disabled':'')+' onchange="culFirstExtra('+rw.id+',this.checked)"> <span>'+esc(rw.name)+(isP?' <em class="cmap-none">(priority)</em>':'')+'</span></label>'}).join('')+'</div>','padding:20px 24px;margin-bottom:20px')} /* Paul (20 Oct 2026): add dimensions to the round here; the page's own Copy to clipboard copies it */ /* §22.2.1: the family Save as PDF control, right-justified on the title line as printBar draws it */
  h+='<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 16px">'+btn('Copy to clipboard','culQCopy()','bs')+(UI.qNote?'<span role="status" style="font-size:14px;color:var(--text-body)">'+esc(UI.qNote)+'</span>':'')+'</div>';
  if(m.empty)return h+card('<p class="t-lead" style="margin:0" data-priority-empty="1">No priority dimensions are marked yet. Choose “Full questionnaire” as this round’s scope, or mark the priority dimensions in step 2.1 first.</p>','padding:20px 24px')+'</div></div>';
  h+=card('<p style="font-size:14px;color:var(--text-body);line-height:1.6;margin:0 0 8px">'+esc(m.instr)+'</p><p style="font-size:14px;color:var(--stone);line-height:1.6;margin:0">'+esc(m.scale)+'</p>','padding:20px 24px;margin-bottom:20px');
  m.blocks.forEach(function(b){var body='<h3 class="h-sub" style="margin:0 0 10px">'+esc(b.heading)+'</h3>'+(b.note?'<p class="t-lead" style="margin:0 0 10px">'+esc(b.note)+'</p>':'')+(b.none?'<p class="t-lead" style="margin:0">'+esc(b.none)+'</p>':'');
    b.entries.forEach(function(e){body+='<div style="display:flex;gap:12px;padding:9px 0;border-bottom:1px solid var(--border-softer)"><span style="min-width:30px;color:var(--stone);font-family:var(--mono);font-size:13px">'+e.n+'.</span><div style="font-size:14px;line-height:1.55;color:var(--text-body)">'+esc(e.text)+((e.opts&&e.opts.length)?'<div style="margin-top:6px;color:var(--stone)">'+e.opts.map(function(o){return '<div>• '+esc(o)+'</div>'}).join('')+'</div>':'')+'</div></div>'});
    h+=card(body,'padding:20px 24px;margin-bottom:20px')});
  return h+'</div></div>'}

/* ── The Baseline Report shell (decision 16): Phase 1's output, composed from parts that each step job appends to CUL_BASELINE_PARTS as {key, html()}.
   A part with nothing entered returns '' and is left out (§22.4.7). With no parts the screen shows one plain line and the Report Manager still lists it. ── */
var CUL_BASELINE_PARTS=[];
function culBaselineBody(){return CUL_BASELINE_PARTS.map(function(p){try{return p.html()||''}catch(e){return ''}}).join('')}
function baselineReportDocRetired(){var body=culBaselineBody();return printDocCover('Baseline Report','Where the organization starts. It sets what the organization says about its culture and about AI beside what its people report and do.','')+(body||'<p style="font-size:14px;color:#444;line-height:1.6;margin:0">Nothing has been recorded for this report yet.</p>')}
function renderBaselineOutputRetired(){var body=culBaselineBody(),h='<h1 style="font-size:28px;font-weight:700;margin:0 0 6px">Baseline Report</h1><p class="t-lead">Where the organization starts. It sets what the organization says about its culture and about AI beside what its people report and do.</p>'+printBar();
  h+=body?'<div style="background:#fff;color:#1e2530;padding:28px 32px;border-radius:6px">'+body+'</div>':card('<p class="t-lead" style="margin:0">Nothing has been recorded for this report yet. It fills in as the four steps of Phase 1 are completed.</p>','padding:20px 24px');
  return h}

/* ═══════════════════════════════════════════════════════════════════════
   STEP 1.1 STATED CULTURE (7 Oct 2026, Batch 2 step 3): three tabbed sections on the shared battery,
   the leaders Baseline round on the shared grid, and the step's part of the Baseline Report.
   ═══════════════════════════════════════════════════════════════════════ */
var CUL_MADE_TO=[{v:'employees',l:'Employees'},{v:'customers',l:'Customers'},{v:'society',l:'Society'},{v:'other',l:'Other'}];
var CUL_FLAG_LINES={performance:'No performance evaluation and rewards policy recorded.',speakUp:'No speaking up and whistleblowing policy recorded.',aiUse:'No AI use policy recorded.',experimentation:'No experimentation and innovation policy recorded.'};
function culStated(){return data.statements||{}}
function culLowerUnlessOther(other,label){label=String(label==null?'':label);return other?label:label.toLowerCase()} /* a standard option reads in lower case mid-sentence; an Other answer keeps the case it was typed in (Sweep 4 item 5) */ function culMadeToLabel(c){var o=String(c&&c.madeToOther||'').trim();return (c&&c.madeTo==='other')?o:culWord(CUL_MADE_TO,c&&c.madeTo)} /* A8: Other prints with the Please specify text when there is some */
function culPolTypeLabel(p){var t=CUL_POLICY_TYPES.filter(function(x){return x.k===p.type})[0],o=String(p&&p.typeOther||'').trim();if(p&&p.type==='other')return o;return t?t.name:''} /* Paul (12 Oct 2026, 1.1 item 12): Other shows only what was typed */
function culFoldTitle60(t){t=String(t||'').trim();var m=t.match(/^(.+?[.!?])\s+\S/);return (m&&m[1].length<=150)?m[1]:t} /* Paul (12 Oct 2026, 1.1 item 8): the whole text, or its first sentence when there are several and it is short; the stylesheet shows up to two lines */
function culNamedCount(recs,field){return recs.filter(function(r){return r&&!r._inlineDraft&&String(r[field]||'').trim()}).length} /* §26.3: the count chip leaves out a nameless draft */
function culNamed(coll,field){return (data[coll]||[]).filter(function(r){return r&&!r._inlineDraft&&String(r[field]||'').trim()})} /* a draft that was never named is not counted (§26.3) */
function culToldLabel(r){var o=String(r&&r.toldOther||'').trim();return (r&&r.told==='other'&&o)?'Another way: '+o:culWord(CUL_CUT_TOLD,r&&r.told)} /* A8: Another way prints with the Please specify text when there is some */
function culObsSettingLabel(o){var t=String(o&&o.settingOther||'').trim();return (o&&o.setting==='other'&&t)?t:culWord(CUL_OBS_SETTING,o&&o.setting)}
function culWord(list,key){var f=list.filter(function(o){return o.v===key})[0];return f?f.l:''}
/* add and remove, shared by every list on the page: an add makes a draft that is swept if never named; a remove takes the lock, asks, and for an added pulse item also removes its scores */
function culListAdd(coll,fields){try{sweepBlankInline(true)}catch(e){}var r={id:culNew(coll)};Object.keys(fields).forEach(function(k){r[k]=fields[k]});culEnsure(coll,[]).push(r);culInlineAdded(coll);culTouch();Store.commit(coll,r.id);render();return r}
function culListDelRefs(coll,id){var out=[]; /* 25 Oct 2026 (bug hunt B7, B12): what a removal must also clear. B7: a removed theme leaves the Communication Planning Hub (commsPlan[n].plans). B12: an observation that pointed at a removed meeting goes back to 'A meeting not listed', keeping the meeting's name as its own text — what the page already showed */ if(coll==='themes')(data.commsPlan||[]).forEach(function(c){if(c&&Array.isArray(c.plans)&&c.plans.indexOf(id)>=0)out.push({coll:'commsPlan',rec:c,fix:function(r){r.plans=r.plans.filter(function(x){return x!==id})}})}); if(coll==='meetings'){var mt=(data.meetings||[]).find(function(m){return m&&m.id===id});(data.observations||[]).forEach(function(o){if(o&&o.meeting===id)out.push({coll:'observations',rec:o,fix:function(r){r.meeting='other';if(!String(r.meetingOther||'').trim()&&mt&&mt.name)r.meetingOther=mt.name}})})} var _wks=[coll+'::'+id].concat(coll==='themes'?['themePlans::'+id]:[]);(data.chCommits||[]).forEach(function(ck){if(ck&&Array.isArray(ck.work)&&ck.work.some(function(w){return _wks.indexOf(w)>=0}))out.push({coll:'chCommits',rec:ck,fix:function(r){r.work=(r.work||[]).filter(function(x){return _wks.indexOf(x)<0})}})}); /* a theme's plan is linked as themePlans::<theme id> (Sweep 6 item 1) */ /* a removed item leaves no dead link in a Charter clause's work (Sweep 5 item 6) */ return out}
function culListDel(coll,id,msg,noAsk){if(!(data[coll]||[]).some(function(r){return r&&r.id===id}))return; /* §23.3: an id that no longer resolves does nothing, and no confirm shows */
  if(lockBlocked(coll+'::'+id))return;
  if(coll==='addedItems'){var held=(data.pulseRounds||[]).filter(function(rd){return Object.keys(rd.results||{}).some(function(u){var a=rd.results[u]&&rd.results[u].avg;return a&&(id in a)})});for(var hi=0;hi<held.length;hi++){if(lockBlocked('pulseRounds::'+held[hi].id))return}} /* §26.1: removing an added item also writes every round that holds its scores, so each of those rounds is checked first */ var refW=culListDelRefs(coll,id);for(var ri=0;ri<refW.length;ri++){if(lockBlocked(refW[ri].coll+'::'+refW[ri].rec.id))return} /* 25 Oct 2026 (bug hunt B7, B12): records that point at the one being removed are written too, so each is checked first */
  var _cks=refW.filter(function(w){return w.coll==='chCommits'});if(_cks.length)msg=(msg||'Remove this?')+' It delivers '+(_cks.length===1?'a Charter clause':_cks.length+' Charter clauses')+': '+_cks.map(function(w){return '\u201C'+culMapShort(String(w.rec.commitment||'').trim()||'An unnamed clause',70)+'\u201D'}).join(', ')+'. '+(_cks.length===1?'The link is':'The links are')+' removed with it.'; /* the removal names the clauses it unlinks (Sweep 5 item 6) */ if(!noAsk&&!confirm(msg||'Remove this?'))return; /* never an empty confirmation (Paul, final pass: the x showed an empty confirmation) */ refW.forEach(function(w){w.fix(w.rec);Store.commit(w.coll,w.rec.id)});
  if(coll==='addedItems'){(data.pulseRounds||[]).forEach(function(rd){if(culD90Locked(rd))return;var ch=false;Object.keys(rd.results||{}).forEach(function(u){var a=rd.results[u]&&rd.results[u].avg;if(a&&(id in a)){delete a[id];ch=true}});if(ch)Store.commit('pulseRounds',rd.id)})}
  Store.removeRec(coll,id);culTouch();render()}
/* ═══ Paul (19 Oct 2026): the family layout with records as cards. A tab keeps the family's tabs, card and completion button. A list of records shows as cards, with "+ Add" above them. Opening a card shows the record below the cards, read-only, built from its own form, with Edit to turn it back into the form. Adding a record creates it at once and opens it for editing. Forms save as they are typed, as everywhere in the family, so there is no Save button. ═══ */
function culByDate(L){return (L||[]).map(function(r,i){return {r:r,i:i}}).sort(function(a,b){var x=String(a.r&&a.r.date||'9999'),y=String(b.r&&b.r.date||'9999');return x<y?-1:x>y?1:a.i-b.i}).map(function(x){return x.r})} /* a log in date order, undated last, ties in entry order */
function culLifeTag(st){var o=CUL_LIFE.filter(function(x){return x.v===st})[0];return o?culTag(o.l,st==='inPlace'?'ok':st==='agreed'?'info':''):''}
function culNoHead(h){return String(h||'').replace(/<div class="cul-flat-head">[\s\S]*?<\/label><\/div>/,'')} /* a form drawn in a record box, without the tick that already sits on the card */
function culRecIs(coll,id){var o=UI.recOpen;return !!(o&&o.coll===coll&&o.id===String(id))}
function culRecOpen(coll,id,edit){var o=UI.recOpen;if(o&&o.coll===coll&&o.id===String(id)&&!o.edit&&!edit)UI.recOpen=null;else UI.recOpen={coll:coll,id:String(id),edit:!!edit};if(UI.recOpen)UI.scrollTo='recbox_'+coll;render()}
function culRecEdit(on){if(UI.recOpen){UI.recOpen.edit=!!on;UI.scrollTo='recbox_'+UI.recOpen.coll}render()}
function culRecClose(){UI.recOpen=null;render()}
var CUL_REC_DATA={ad41loc:'publishLocations',ad41pol:'policies',ad41vc:'values'}; /* a box keyed by its own name, whose records live in another collection */
function culRecAdd(coll,addFn,arg){var dc=CUL_REC_DATA[coll]||coll,before=(data[dc]||[]).map(function(r){return r&&r.id});var f=window[addFn];if(typeof f==='function')f(arg);var L=(data[dc]||[]).filter(function(r){return r&&before.indexOf(r.id)<0});if(L.length){UI.recOpen={coll:coll,id:String(L[L.length-1].id),edit:true};UI.scrollTo='recbox_'+coll}render()}
function culRecDraw(fn,ro){var K={fhelp:fhelp,ta:ta,inp:inp,sel:sel,multi:multi,tick:tick,culSelOther:culSelOther,btn:btn,btnAdd:btnAdd,culFold:culFold},out='';
  culFold=function(key,title,chipHtml,bodyHtml,opts){opts=opts||{};return (opts.headExtra&&!ro?'<div class="cul-flat-head">'+opts.headExtra+'</div>':'')+(bodyHtml||'')};
  if(ro){fhelp=function(){return ''};btn=function(){return ''};btnAdd=function(){return ''};
    ta=function(label,id,val){return culRoRow(label,culRoText(val))};
    inp=function(label,id,val,ph,type){var v=String(val==null?'':val).trim();return culRoRow(label,v?(type==='date'&&typeof fmtDate==='function'?esc(fmtDate(v)):type==='month'&&typeof culMonthWords==='function'?esc(culMonthWords(v)):culRoText(v)):'')};
    sel=function(label,id,val,opts){if(!label)return '';var o=(opts||[]).filter(function(x){return x.v===val&&x.v!==''})[0];return culRoRow(label,o?esc(o.l):'')};
    multi=function(label,id,opts,selected){var s=Array.isArray(selected)?selected.map(String):[];return culRoRow(label,(opts||[]).filter(function(o){return s.indexOf(String(o.v))>=0}).map(function(o){return esc(String(o.l).replace(/^\d+\.\s*/,'').replace(/\s*\(Priority\)$/,''))}).join(', '))};
    tick=function(label,id,checked){var m=/^(.*?)\bwill not\b(.*)$/.exec(String(label||''));if(m)return culRoRow(m[1]+'will'+m[2],checked?'No':'Yes');return culRoRow(label,checked?'Yes':'No')}; /* a negative tick reads positively in read-only form (Paul, final pass) */
    culSelOther=function(label,id,val,opts,otherVal,otherId,help,trigger){if(val===(trigger||'other'))return culRoRow(label,culRoText(String(otherVal||'').trim()||'Other'));return sel(label,id,val,opts,help)}}
  CUL_RO=!!ro;try{out=fn()}catch(e){out='<p class="t-lead">This record could not be drawn.</p>'}finally{CUL_RO=false;fhelp=K.fhelp;ta=K.ta;inp=K.inp;sel=K.sel;multi=K.multi;tick=K.tick;culSelOther=K.culSelOther;btn=K.btn;btnAdd=K.btnAdd;culFold=K.culFold}
  return out}
function culRecCard(coll,r,title,meta,tag,c,extra,cls){var on=culRecIs(coll,r.id);return '<div class="cmap-wcard'+(on?' sel':'')+(cls?' '+cls:'')+'" style="--c:'+(c||'var(--p1)')+'"><div class="cmap-wcard-h"><button type="button" class="cmap-wcard-t" aria-pressed="'+on+'" aria-expanded="'+on+'"'+(culFullOf(title)?' title="'+escAttr(culFullOf(title))+'"':'')+' onclick="'+escAttr("culRecOpen('"+coll+"','"+culFoldJs(r.id)+"')")+'">'+esc(title)+'</button>'+(tag?'<span class="cmap-wcard-l">'+tag+'</span>':'')+'</div>'+(meta||[]).filter(function(x){return String(x||'').trim()}).map(function(x){var f=culFullOf(x);return '<div class="m"'+(f?' title="'+escAttr(f)+'"':'')+'>'+esc(x)+'</div>'}).join('')+(extra||'')+'</div>'}
function culRecBox(coll,recs,titleFn,formFn,noEdit){var o=UI.recOpen;if(noEdit&&o&&o.coll===coll)o.edit=false;if(!o||o.coll!==coll)return '';var r=recs.filter(function(x){return x&&String(x.id)===o.id})[0];if(!r)return '';
  var head='<div class="cul-recbox-h"><h4>'+esc(titleFn(r))+'</h4><div class="cul-recbox-acts">'+(noEdit?'':o.edit?btn('Done editing','culRecEdit(false)','bp'):btn('Edit','culRecEdit(true)','bs'))+btn('Close','culRecClose()','bs')+'</div></div>',body='';
  body=culRecDraw(function(){return formFn(r)},!o.edit);
  return '<div class="cul-recbox'+(o.edit?' editing':'')+'" id="recbox_'+escAttr(coll)+'">'+head+(o.edit?body:'<div class="cul-ro">'+body+'</div>')+'</div><!--/recbox-->'}
function culRecList(a){var recs=a.recs||[];return '<div class="cul-reclist">'+(a.addLabel?'<div style="margin:0 0 14px">'+btnAdd(a.addLabel,"culRecAdd('"+a.coll+"','"+a.addFn+"'"+(a.addArg!=null?",'"+culFoldJs(a.addArg)+"'":'')+")",a.addVariant||'')+'</div>':'')+(recs.length?(a.groups?a.groups.map(function(g){var L=recs.filter(g.has);return L.length?'<h4 class="cul-recgrp">'+esc(g.label)+' <span class="cul-count">'+L.length+'</span></h4><div class="cmap-cards">'+L.map(a.card).join('')+'</div>':''}).join(''):'<div class="cmap-cards">'+recs.map(a.card).join('')+'</div>'):'<p class="t-lead" style="margin:0 0 10px">'+esc(a.empty)+'</p>')+culRecBox(a.coll,recs,a.title,a.form,a.noEdit)+'</div>'}
function culValueAdd(){var r=culListAdd('values',{name:'',description:'',published:'',origin:'baseline'});culFoldOpenNew(r.id);render()} /* A2: the entry just added opens */
function culCommitAdd(){var r=culListAdd('commitments',{text:'',madeTo:'',madeToOther:'',published:'',origin:'baseline'});culFoldOpenNew(r.id);render()}
function culPolicyAdd(){var r=culListAdd('policies',{name:'',type:'',typeOther:'',says:'',lives:'',year:''});culFoldOpenNew(r.id);render()}
function culValueDel(id){culDelLinked('values',id,'value')} /* 7 Oct 2026 (Batch 3, step 2.1, Paul's ruling, Spec §26.1): themes that link the value lose the link; guard, confirm, apply, remove */
function culCommitDel(id){culDelLinked('commitments',id,'commitment')} /* same, for commitments */
function culPolicyDel(id){culDelLinked('policies',id,'policy')} /* 7 Oct 2026 (Batch 3, step 2.3, job C1): a contradiction that points at this policy loses the link; guard, confirm, apply, remove */
function culPolicyYear(id,value,elId){var v=String(value==null?'':value).trim(),m=null,rec=(data.policies||[]).filter(function(x){return x&&x.id===id})[0],stored=rec&&rec.year!=null?String(rec.year):'';try{m=document.getElementById('polYrMsg_'+id)}catch(e){} if(v&&!/^\d{4}$/.test(v)){var msg='Enter a four-digit year, for example 2024. The year stays '+(stored||'blank')+'.';UI.polYrMsg={id:id,msg:msg};culPulseReset(elId,stored);if(m)m.textContent=msg;return false} UI.polYrMsg=null;if(m)m.textContent='';return fldSave('po_year_'+id,v)} /* a refused year says why and the box shows the stored year; the message survives a redraw (Sweep 4 item 12) */ /* optional, and a year when given */
var CUL_REQ_STYLE='font-size:14px;margin:0 0 10px';
function culEntryBox(inner){return '<div style="padding:14px 16px;margin:0 0 10px;border:1px solid var(--border-faint)">'+inner+'</div>'}
function culValueRow(v){return culFold(v.id,v.name,'',inp('Value','vl_name_'+v.id,v.name,'For example, We tell the truth early, even when it is uncomfortable','text','The value as the organization names it.')+ta('Description as written','vl_description_'+v.id,v.description,'Paste the organization\'s own wording.',2,'The organization\u2019s own explanation of the value, if it publishes one.')+inp('Where it is published','vl_published_'+v.id,v.published,'For example, the website or the employee handbook','text')+'<div>'+btn('Remove','culValueDel(\''+escAttr(v.id)+'\')','bg2')+'</div>',{noun:'value'})} /* ruling 150 (step 1.1): the dimensions a stated value speaks to show as chips and as the anchors on the map */
function culCommitRow(c){return culFold(c.id,culFoldTitle60(c.text),'',ta('Commitment as written','co_text_'+c.id,c.text,'Paste the organization\'s own wording.',2)+culSelOther('Made to','co_madeTo_'+c.id,c.madeTo||'',[{v:'',l:'Choose who it is made to'}].concat(CUL_MADE_TO),c.madeToOther,'co_madeToOther_'+c.id)+inp('Where it is published','co_published_'+c.id,c.published,'For example, the annual report','text')+'<div>'+btn('Remove','culCommitDel(\''+escAttr(c.id)+'\')','bg2')+'</div>',{noun:'commitment'})}
function culPolicyFieldsOnly(p){var ty=CUL_POLICY_TYPES.filter(function(t){return t.k===p.type})[0]; return inp('Policy name','po_name_'+p.id,p.name,'For example, Speak Up and Non-Retaliation Policy','text')
    +culSelOther('Type','po_type_'+p.id,p.type||'',[{v:'',l:'Choose a type'}].concat(CUL_POLICY_TYPES.map(function(t){return {v:t.k,l:t.name}})),p.typeOther,'po_typeOther_'+p.id,ty?(ty.k==='other'?'Any other policy you think is relevant.':'Typical examples include '+culJoinSerial(String(ty.examples||'').split(', ').map(culTypeLower))+'.'):'')
    +ta('What it says about how people should behave','po_says_'+p.id,p.says,'A short summary in your own words, one or two sentences.',2)
    +inp('Where to find it','po_lives_'+p.id,p.lives,'For example, the intranet policy library, or a link','text')
    +(CUL_RO?culRoRow('Year last updated',culRoText(p.year)):'<div class="mb-4"><label class="form-label" for="po_year_'+escAttr(p.id)+'">Year last updated</label><input type="text" id="po_year_'+escAttr(p.id)+'" class="field-input" style="width:140px" value="'+escAttr(p.year||'')+'" placeholder="For example, 2024" onchange="culPolicyYear(\''+escAttr(p.id)+'\',this.value,this.id)"><div id="polYrMsg_'+escAttr(p.id)+'" role="status" style="font-size:14px;color:var(--gold-text);margin-top:4px">'+(UI.polYrMsg&&UI.polYrMsg.id===p.id?esc(UI.polYrMsg.msg):'')+'</div></div>')
    } function culPolicyRow(p){return culFold(p.id,p.name,'',culPolicyFieldsOnly(p)+'<div>'+btn('Remove','culPolicyDel(\''+escAttr(p.id)+'\')','bg2')+'</div>',{noun:'policy'})} /* the fields are shared with the policy actions card, where a policy recorded from its plan is completed (Paul, 26 Oct 2026) */
/* the culture items of the leaders pulse: the core culture items, then the added items assigned to a culture row or to Other (an item assigned to an AI row is entered in step 1.1) */
function culS11Items(){return culQItems('leaders','full').filter(function(it){var rw=culRowById(it.row);return !rw||!rw.ai})}
function culBaseRec(r){return r.origin!=='new'} /* 7 Oct 2026 (Batch 3, step 2.1): values and commitments added in step 2.1 (origin new) belong to the target culture; step 1.1 and the Baseline Report show only what the organization stated today */
function culPolicyList(){return culNamed('policies','name').filter(culBaseRec)} /* 7 Oct 2026 (Batch 3, step 2.3): the policies step 1.1 recorded. A policy added in step 2.3 as the action for a missing type (origin new) is a plan, not a baseline fact, so it never shows in 1.1 or 1.3, never counts toward step 1.1, never clears the missing-type flag and never reaches the Baseline Report */
function culMissing11a(){var st=culStated(),m=[];if(!String(st.mission||'').trim()&&!st.missionNone)m.push('Enter the mission statement, or tick “None written.”');if(!culNamed('values','name').filter(culBaseRec).length)m.push('Enter at least one value.');return m}
function culMissing11b(){var m=[];if(!culPolicyList().length&&!culStated().policiesNone)m.push('Enter at least one policy, or tick that none of the listed policy types exists.');return m}
function culS11aMission(){var st=culStated(); /* the mission, purpose and culture statements: drawn on the tab and in step 1.1's panel */
  return culSection('Mission, Purpose, and Culture','Record how the organization formally states what it does, why it exists, and how it describes its culture.',
    culNoneText({label:'Mission statement',id:'sm_mission',val:st.mission,ph:'Copy the mission statement as written, for example from the website.',rows:3,help:'The organization\'s formal statement of what it does and for whom.',noneLabel:'None written. The organization has no formal mission statement.',noneId:'sm_missionNone',checked:!!st.missionNone})
    +ta('Purpose statement','sm_purpose',st.purpose,'Copy the purpose statement as written.',3,'The organization\'s formal statement of why it exists, beyond what it does.')
    +ta('Culture statement','sm_baselineStatement',st.baselineStatement,'Copy the description as written, for example from a culture code.',3,'A formal description of the organization\'s culture, such as a culture code or a document on how people work together.'))}
