var CUL_CON_OUT=[{v:'acted',l:'Heard and acted on',def:'The concern was taken up and something changed because of it.'},{v:'noAction',l:'Heard with no action',def:'The concern was acknowledged but nothing changed.'},{v:'ignored',l:'Ignored',def:'The concern received no response.'},{v:'sidelined',l:'Sidelined or penalized',def:'The person lost standing, influence, or opportunities, or faced a formal consequence, after raising it.'},{v:'dk',l:'Don\'t know',def:''}];
