/* ── Section 1: the teams editor, the employee questionnaire and its results ── */
function culTeamHeadSet(id,value,elId,live){var t=(data.teams||[]).filter(function(x){return x&&x.id===id})[0],stored=t&&t.headcount!=null?String(t.headcount):'',v=String(value==null?'':value).trim();if(v===''){return live?true:fldSave('tm_headcount_'+id,'')}if(live)return true; /* the headcount saves on change only (Sweep 6 item 20) */ var n=Number(v);if(!isFinite(n)||n<1||Math.floor(n)!==n){culPulseReset(elId,stored);culMapToast('Enter the headcount as a whole number, 1 or more.');try{render()}catch(e){}return false}return fldSave('tm_headcount_'+id,String(n),live)} /* refused with a reason, like the respondent boxes; nothing half-typed is saved (Sweep 5 item 7) */ function culTeamRow(t){var i=escAttr(t.id),f=function(fld,type,ph,lab,w){return '<input type="'+type+'" id="tm_'+fld+'_'+i+'" class="field-input" style="'+(w||'')+'" value="'+escAttr(t[fld]==null?'':t[fld])+'" placeholder="'+escAttr(ph)+'" aria-label="'+escAttr(lab)+'" onchange="fldSave(this.id,this.value)" oninput="fldSave(this.id,this.value,true)">'};
  return '<div style="display:grid;grid-template-columns:2fr 2fr 1fr auto;gap:10px;align-items:center;margin:0 0 8px">'+f('name','text','For example, Claims Processing','Team name')+f('manager','text','For example, Marisol Vega','Manager')+(f('headcount','number','Number of people on the team','Headcount','min-width:0" min="1" step="1')).split('fldSave(this.id,this.value,true)').join("culTeamHeadSet('"+i+"',this.value,this.id,true)").split('fldSave(this.id,this.value)').join("culTeamHeadSet('"+i+"',this.value,this.id)") /* a headcount is a whole number, 1 or more (Sweep 5 item 7) */+btn('Remove team','culTeamDel(\''+i+'\')','bg2')+'</div>'}
function culTeamsEditor(){var ts=data.teams||[],h='<h4 class="h-sub" style="margin:0 0 6px">Teams</h4><p style="font-size:14px;color:var(--text-body);line-height:1.6;margin:0 0 10px">Add each team that will answer the employees\u2019 questionnaire, with its manager and the number of people in it. The whole program uses this one list of teams, so a team added here appears wherever teams are chosen.</p>';
  if(ts.length)h+='<div style="display:grid;grid-template-columns:2fr 2fr 1fr auto;gap:10px;margin:0 0 4px;font-size:14px;font-weight:600;color:var(--text-muted)"><div>Team name</div><div>Manager</div><div>Headcount</div><div aria-hidden="true" style="visibility:hidden;height:0;overflow:hidden">'+btn('Remove team','','bg2')+'</div></div>'+ts.map(culTeamRow).join(''); /* copy pass (19 Oct 2026): the teams line above asks for each manager */
  else h+='<p class="t-lead" style="margin:0 0 10px">No teams yet.</p>';
  return h+btnAdd('+ Add a team','culTeamAdd()')+culAddForm('team')}
function culMissing13a(){var r=culBaselineFind('employees'),n=culS13Items().filter(function(it){return culItemOrg(r,it.id).used==null}).length,resp=!!r&&(culUnitResp(r,'org')>=1||culRoundTeams().some(function(t){return culUnitResp(r,t.id)>=1}));
  return (n||!resp)?['Employee Questionnaire: every culture item needs an organization-wide average, entered or calculated from teams, and the number of respondents.']:[]}
function culLeadersHaveScores(){var lr=culBaselineFind('leaders');return !!lr&&culS11Items().some(function(it){return culUnitVal(lr,'org',it.id)!=null})}
function culEmpHaveScores(){var er=culBaselineFind('employees');return !!er&&culS13Items().some(function(it){return culItemOrg(er,it.id).used!=null})}
function culS13Results(){var ref=culEmpRef(),h='<h4 class="h-sub" style="margin:0 0 6px">Leaders and employees compared</h4>';
  if(!culEmpHaveScores())return h+'<p class="t-lead" style="margin:0 0 12px">Waiting for the employee questionnaire. Enter the results in Section 1 to see them here.</p>';
  h+='<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:0 0 12px">Each culture row shows the leaders\' score from step 1.2 beside the employees\' score from this pulse. A positive gap means leaders see the culture as healthier than employees report it. The gap shows where views differ. It is not a target.</p>';
  if(culLeadersHaveScores())h+=culPairedBars(culBaselineRef('leaders'),ref,{ai:false});
  else h+='<p class="t-lead" style="margin:0 0 12px">Waiting for the leadership questionnaire. Enter the leadership results in step 1.2 and the paired bars will appear here. The employee scores are shown below in the meantime.</p>'+culBars(ref,{group:'employees',ai:false,noOther:true});
  h+='<h4 class="h-sub" style="margin:28px 0 6px">Scores by team</h4><p style="font-size:14px;color:var(--stone);line-height:1.6;margin:0 0 12px">Teams are listed down the side and culture rows across the top. A marked team has a psychological safety score below 3.0.</p>'+culTeamGrid(ref,{ai:false});
  return h}
function culS13a(){var ref=culEmpRef(),er=culBaselineFind('employees'),h='';
  h+=culPulseIntro('The employee questionnaire is a short survey that asks employees how far they agree with statements about the culture they experience at work. Employees answer the questionnaire outside this app, in your survey tool.',
    '<p style="font-size:14px;color:var(--text-body);line-height:1.6;margin:0 0 8px">This is the Baseline round. Later rounds are entered on the Pulse Round page, which keeps every round side by side.</p>'+btn('Go to the Pulse Round page \u2192','go(\'pulseRound\')','bs'));
  h+=culStage(1,'Prepare the questionnaire','See the items, then copy the questionnaire or save it as a PDF.',
    '<p style="font-size:14px;color:var(--text-body);line-height:1.6;margin:0 0 12px">The complete employee questionnaire lists the culture items, then the AI items, the three multiple-choice questions, and the three open questions from step 1.4.</p>'
    +'<div class="cul-actline">'+btn('Open the questionnaire','culOpenQ(\'employees\',\'full\')','bs')+'<p class="cul-actnote">The questionnaire shows every item in order, with the scale.</p></div>');
  h+=culStage(2,'Record who took it','Set up the teams. Record when the questionnaire ran and how many employees took it, in each team and in the whole organization.',
    culTeamsEditor()+culSurveyDates(ref,er)
    +'<div style="margin:18px 0 0">'+culPulseGrid(ref,{group:'employees',items:culS13Items(),respondentsOnly:true})+'</div>');
  h+=culStage(3,'Enter the results','Enter the average score for each item, including your own items. Scores run from 1.0 to 5.0.',
    ''
    +culPulseGrid(ref,{group:'employees',items:culS13Items(),hideRespondents:true})
    +'<p style="font-size:14px;color:var(--stone);line-height:1.6;margin:10px 0 0">The results show every team, however few people answered. The psychological safety items are adapted from Amy Edmondson\'s research. They are not a validated instrument.</p>');
  h+=culStage(4,'Read the results','See how employees and leaders compare on each dimension, and how each team scored.',
    '<div data-gate="res13">'+(culEmpHaveScores()?culS13Results():'<p class="t-lead" style="margin:0">Results will appear here once you enter the scores in stage 3.</p>')+'</div>');
  return h}
/* ── Section 2: pockets of low safety, calculated and never entered ── */
function culFlaggedTeams(){var er=culBaselineFind('employees');if(!er)return [];return culRoundTeams().filter(function(t){return culTeamLowSafety(er,t.id)})}
function culSafetyNoteOf(roundId,teamId){return (data.safetyNotes||[]).filter(function(n){return n&&n.round===roundId&&n.team===teamId})[0]||null}
function culSafetyNote(roundId,teamId,value,elId){var n=culSafetyNoteOf(roundId,teamId),text=String(value==null?'':value);
  if(!n){if(!text.trim())return true;n={id:culNew('safetyNotes'),round:roundId,team:teamId,note:text};culEnsure('safetyNotes',[]).push(n);culTouch();Store.commit('safetyNotes',n.id);return true} /* created on first typing, never on render */
  if(Date.now()<_discardChangeUntil||Collab.lockedByOther('safetyNotes::'+n.id)){culPulseReset(elId,n.note||'');return false}
  n.note=text;culTouch();Store.commit('safetyNotes',n.id);return true}
function culS13b(){var er=culBaselineFind('employees'),h='',sh='Teams flagged for low safety',sp='The app flags a team when its psychological safety score is below 3.0, using the questionnaire results, so you do not enter the flags.'; /* design rule 11 (14 Oct 2026): the note joins the purpose line */
  var hasTeamScores=!!er&&culRoundTeams().some(function(t){return culRowScore(er,1,t.id)!=null});
  if(!hasTeamScores)return h+culSection(sh,sp,'<p class="t-lead" style="margin:0">Flags appear once you enter team scores above.</p>');
  var fl=culFlaggedTeams();
  if(!fl.length)return h+culSection(sh,sp,'<p class="t-lead" style="margin:0">No team has a psychological safety score below 3.0.</p>');
  var noteForm=function(tm){var n=culSafetyNoteOf(er.id,tm.id),lab='What do you already know about the cause?',labHelp='Note anything you already know that might explain the low score. You can leave it empty.';
    if(CUL_RO)return culRoRow(lab,culRoText(n?n.note:''));
    return '<div class="mb-4"><label class="form-label" for="prgSN_'+escAttr(tm.id)+'">'+lab+'</label>'+fhelp(labHelp)+'<textarea id="prgSN_'+escAttr(tm.id)+'" class="ta-helper" rows="2"'+(n?' data-lock="safetyNotes::'+escAttr(n.id)+'"':'')+' placeholder="For example, a recent restructure, a manager change, or a case where someone was criticized for a mistake." onchange="culSafetyNote(\''+escAttr(er.id)+'\',\''+escAttr(tm.id)+'\',this.value,this.id)">'+esc(n?n.note:'')+'</textarea></div>'};
  return h+culSection(sh,sp,culRecList({coll:'flags',recs:fl,empty:'',
    card:function(tm){var n=culSafetyNoteOf(er.id,tm.id);return culRecCard('flags',tm,tm.name,[n&&String(n.note||'').trim()?'What we know: '+culMapShort(String(n.note).trim(),120):'Nothing recorded yet about the cause'],culTag('Score: '+culFmt1(culRowScore(er,1,tm.id)),'warn'))},
    title:function(tm){return tm.name},form:noteForm}),{count:culNamedCount(fl,'name')})} /* Paul (19 Oct 2026): each flagged team is a card that opens below, read-only, with Edit */
/* ── Section 3: signals in practice ── */
function culExpRow(x){var o=culWord(CUL_EXP_OUT,x.happened),w=String(x.who||'').trim();return culFold(x.id,culFoldTitle60((w?w+': ':'')+String(x.tried||'')),o?esc(o):'',inp('Who','ex_who_'+x.id,x.who,'For example, a claims adjuster in Claims Processing','text','Describe the person by role and team. Never enter a name.')+ta('What they tried','ex_tried_'+x.id,x.tried,'For example, tested an AI tool to summarize adjuster notes on 20 closed files.',2)+inp('When it happened','ex_date_'+x.id,x.date,'','date','The date the person tried it. The Analytics page groups these cases by quarter.')+sel('Did it work?','ex_worked_'+x.id,x.worked||'',[{v:'',l:'Choose an answer'}].concat(CUL_WORKED))+sel('What happened to them','ex_happened_'+x.id,x.happened||'',[{v:'',l:'Choose an outcome'}].concat(CUL_EXP_OUT),culDefAll(CUL_EXP_OUT),true)+'<div>'+btn('Remove case','culExpDel(\''+escAttr(x.id)+'\')','bg2')+'</div>',{noun:'case'})}
function culConRow(x){var o=culWord(CUL_CON_OUT,x.happened),w=String(x.who||'').trim();return culFold(x.id,culFoldTitle60((w?w+': ':'')+String(x.concern||'')),o?esc(o):'',inp('Who','cc_who_'+x.id,x.who,'For example, an underwriter in Underwriting','text','Describe the person by role and team. Never enter a name.')+ta('The concern','cc_concern_'+x.id,x.concern,'For example, raised that a claims triage tool was sending complex injury claims to the fast-track queue.',2)+inp('When it was raised','cc_date_'+x.id,x.date,'','date','The date the concern was raised. The Analytics page groups these cases by quarter.')+sel('What happened to them','cc_happened_'+x.id,x.happened||'',[{v:'',l:'Choose an outcome'}].concat(CUL_CON_OUT),culDefAll(CUL_CON_OUT),true)+'<div>'+btn('Remove case','culConDel(\''+escAttr(x.id)+'\')','bg2')+'</div>',{noun:'case'})}
function culOutHelp(list,key){var f=list.filter(function(o){return o.v===key})[0];if(f)return f.def;return list.filter(function(o){return o.def}).map(function(o){return '\u201C'+o.l+'\u201D: '+o.def}).join(' ')}
function culCutRec(){return (data.jobCuts||[])[0]||null}
function culCutSet(field,value,elId){var r=culCutRec(),text=String(value==null?'':value);
  if(!r){if(!text.trim())return true;if(Collab.lockedByOther('jobCuts::jbcuts')){culPulseReset(elId,'');return false} /* 8 Oct 2026 (R8): one record, deterministic id */
    r={id:'jbcuts',toldOther:''};culEnsure('jobCuts',[]).push(r);Store.commit('jobCuts',r.id)} /* the one record is created on first entry */
  var ok=fldSave('jb_'+field+'_'+r.id,text);if(ok&&field==='told')render(); /* A8: the Please specify box shows or hides */
  return ok}
function culCutsFilled(){var r=culCutRec();return culSg().cutsNone===true||(!!r&&!!String(r.when||'').trim()&&!!r.told&&!!r.reasonsExplained&&!!r.aiGiven)}
function culPolAnswered(){return culPolicyList().every(function(p){return !!p.practiceAnswer})}
function culMissing13c(){var sg=culSg(),m=[];
  if(!(culNamed('experimenters','tried').length>0||sg.experimentersNone===true))m.push('Signals in Practice: add at least one case of someone trying something new, or tick that you found none.');
  if(!(culNamed('concerns','concern').length>0||sg.concernsNone===true))m.push('Signals in Practice: add at least one case of someone raising a concern, or tick that you found none.');
  if(!culCutsFilled())m.push('Signals in Practice: answer the four questions about the most recent round of job cuts, or tick “None in the last two years.”');
  if(!culPolAnswered())m.push('Signals in Practice: answer every policy from step 1.1.');
  return m}
function culOutCountsHtml(){var ex=culNamed('experimenters','tried'),cs=culNamed('concerns','concern'),ln=function(list,items){return '<p style="font-size:14px;color:var(--stone);margin:0 0 10px"><strong>Outcomes so far</strong> '+esc(culOutCounts(list,'happened',items))+'</p>'};return {ex:ex.length?ln(CUL_EXP_OUT,ex):'',cs:cs.length?ln(CUL_CON_OUT,cs):''}}
function culCutsBody(){var sg=culSg(),r=culCutRec()||{},b; /* the most recent round of job cuts: drawn in Signals in Practice and in step 1.3's panel */
  var _cutDate=!!String((r&&r.when)||'').trim()&&!sg.cutsNone; b=tick('None in the last two years','sg_cutsNone',!!sg.cutsNone,_cutDate?'Clear the date of the job cuts to tick this.':''); if(_cutDate)b=b.replace('<input type="checkbox"','<input type="checkbox" disabled').replace('cursor:pointer','cursor:default;opacity:.55'); /* the tick always shows: grayed out while there is a date, tickable otherwise (Paul, final pass, 30 Oct 2026; was: gone once anything was recorded) */ /* Paul (12 Oct 2026): the none tick goes once job cuts are recorded */
  if(!sg.cutsNone){ /* design rule 11 (14 Oct 2026): with None ticked the questions simply do not show, with no box saying so */var selc=function(label,fld,list,help){return '<div class="mb-4"><label class="form-label" for="jbSel_'+fld+'">'+label+'</label>'+fhelp(help)+'<select id="jbSel_'+fld+'" class="sel-helper" onchange="culCutSet(\''+fld+'\',this.value,this.id)" data-lock="jobCuts::'+escAttr(r.id||'jbcuts')+'"><option value="">Choose an answer</option>'+list.map(function(o){return '<option value="'+escAttr(o.v)+'"'+(r[fld]===o.v?' selected':'')+'>'+esc(o.l)+'</option>'}).join('')+'</select></div>'};
    b+='<div class="mb-4"><label class="form-label" for="jbSel_when">When</label>'+fhelp('Enter the date of the cuts.')+'<input type="date" id="jbSel_when" class="field-input" style="width:200px" value="'+escAttr(r.when||'')+'" onchange="culCutSet(\'when\',this.value,this.id)" data-lock="jobCuts::'+escAttr(r.id||'jbcuts')+'"></div>'
      +selc('How people were told','told',CUL_CUT_TOLD,'')+(r.told==='other'&&r.id?'<div class="cul-other">'+inp('Please specify','jb_toldOther_'+r.id,r.toldOther,'','text')+'</div>':'')+selc('Did the organization explain the reasons to the people affected?','reasonsExplained',CUL_CUT_REASONS,'Choose \u201CYes, in full\u201D only if the organization told the people affected why it made the cuts. Answer from the record of what the organization actually said.')+selc('Did the organization give AI or automation as a reason?','aiGiven',CUL_CUT_AI,'Choose \u201CYes\u201D if the organization said that AI or automation was part of the reason for the cuts.')} /* Paul (19 Oct 2026, visual pass): Please specify sits under How people were told */
  return b}
function culS13cSignals(){var sg=culSg(),r=culCutRec()||{},h='',oc=culOutCountsHtml(),ps=culPolicyList(),ex=data.experimenters||[],cn=data.concerns||[],b,none='<p class="t-lead" style="margin:0 0 10px">No cases added yet.</p>';
  b=culRecList({coll:'experimenters',recs:ex,addLabel:'+ Add a case',addFn:'culExpAdd',empty:'No cases added yet.',
    card:function(x){var o=x.happened,tone=o==='rewarded'?'ok':(o==='informal'||o==='formal')?'bad':'';return culRecCard('experimenters',x,culMapShort((String(x.who||'').trim()?String(x.who).trim()+': ':'')+String(x.tried||'').trim(),110)||'A case not yet described',[culWord(CUL_WORKED,x.worked)?'Did it work? '+culWord(CUL_WORKED,x.worked):''],o?culTag(culWord(CUL_EXP_OUT,o),tone):culTag('Outcome not recorded','warn'))},
    title:function(x){return culMapShort((String(x.who||'').trim()?String(x.who).trim()+': ':'')+String(x.tried||''),90)||'A case'},form:culExpRow}); /* Paul (19 Oct 2026): cases as cards that open below, read-only, with Edit */ /* design rules 3 and 8 (14 Oct 2026): the count on the section heading, and no Outcomes so far tally */
  if(!culNamed('experimenters','tried').length)b+='<div style="margin-top:12px">'+tick('We looked and found no recent cases of someone trying something new.','sg_experimentersNone',!!sg.experimentersNone,'Tick this only if you checked and found none. Adding a case clears the tick.')+'</div>';
  h+=culSection('People who tried something new','Record recent cases of someone trying something new with AI or in their work, and what happened to them afterward. Add each case you can find, one at a time.',b,{count:culNamedCount(ex,'tried')});
  b=culRecList({coll:'concerns',recs:cn,addLabel:'+ Add a case',addFn:'culConAdd',empty:'No cases added yet.',
    card:function(x){var o=x.happened,tone=o==='acted'?'ok':(o==='ignored'||o==='sidelined')?'bad':'';return culRecCard('concerns',x,culMapShort((String(x.who||'').trim()?String(x.who).trim()+': ':'')+String(x.concern||'').trim(),110)||'A concern not yet described',[],o?culTag(culWord(CUL_CON_OUT,o),tone):culTag('Outcome not recorded','warn'))},
    title:function(x){return culMapShort((String(x.who||'').trim()?String(x.who).trim()+': ':'')+String(x.concern||''),90)||'A case'},form:culConRow});
  if(!culNamed('concerns','concern').length)b+='<div style="margin-top:12px">'+tick('We looked and found no recent cases of someone raising a concern.','sg_concernsNone',!!sg.concernsNone,'Tick this only if you checked and found none. Adding a case clears the tick.')+'</div>';
  h+=culSection('People who raised concerns','Record recent cases of someone raising a concern about AI or about how work is done, and what happened to them afterward. Add each case you can find, one at a time.',b,{count:culNamedCount(cn,'concern')});
  b=culCutsBody();
  h+=culSection('The most recent round of job cuts','Answer four questions about the most recent round of job cuts in the last two years, from the record of what the organization said at the time. If there were none, tick \u201CNone in the last two years.\u201D How the organization handled the last cuts can shape how people expect it to handle change brought by AI.',b);
  return h}
function culS13cPolicies(sp){var SP=CUL_SP_COPY.sp;var h='',b,ps=culPolicyList();
  b='';
  if(!ps.length)b+='<p class="t-lead" style="margin:0">'+esc(sp?SP.polEmpty:'No policies recorded yet. Record the organization\'s policies in step 1.1 and they will appear here for you to assess.')+'</p>';
  else b+=culRecList({coll:'policyPractice',recs:ps,empty:'',
    card:function(p){var a=p.practiceAnswer,tone=a==='yes'?'ok':a==='no'?'bad':a==='partly'?'warn':'';return culRecCard('policyPractice',p,String(p.name||'').trim()||'Unnamed policy',[String(p.practiceEvidence||'').trim()?'Evidence: '+culMapShort(String(p.practiceEvidence).trim(),130):''],a?culTag('Practice matches: '+String(culWord(CUL_PRACTICE,a)).toLowerCase(),tone):culTag('Not answered','warn'))},
    title:function(p){return String(p.name||'').trim()||'Unnamed policy'},
    form:function(p){return sel('Does practice match this policy?','po_practiceAnswer_'+p.id,p.practiceAnswer||'',[{v:'',l:'Choose an answer'}].concat(CUL_PRACTICE),CUL_PRACTICE_DEF,true)+ta('Evidence','po_practiceEvidence_'+p.id,p.practiceEvidence,'For example, the last two appraisal cycles used the criteria in the policy in two teams but not in the others.',2,'Describe what you have seen that supports your answer.')}}); /* Paul (19 Oct 2026): each policy is a card with its practice answer, opening below, read-only, with Edit */
  h+=culSection('Policy against practice',(sp?SP.polIntro+' '+SP.polBox:'For each policy recorded in step 1.1, judge whether what happens in practice matches it. You add and remove policies in step 1.1, not here.'),b,ps.length?{count:culNamedCount(ps,'name')}:{}); /* design rules 3 and 11 (14 Oct 2026): the count on the heading, and the step 1.1 note in the purpose line */
  return h}
function culS13c(){return culS13cSignals()+culS13cPolicies()}
/* ── Section 4: conversations and observations ── */
/* the conversation and observation forms offer all eleven dimensions, so culRowChoices (the eight culture dimensions) is gone (Paul, 26 Oct 2026) */ function culConvRow(c){var tms=culNamed('teams','name').map(function(t){return {v:t.id,l:t.name}});
  return culFold(c.id,culFoldTitle60(c.learned),'Date: '+(c.date?esc(fmtDate(c.date)):'not set'),inp('Date','cv_date_'+c.id,c.date,'','date')+inp('Senior leader','cv_leader_'+c.id,c.leader,'For example, Margaret Ellison','text','Name a member of the leadership group that took the leadership questionnaire in step 1.2.')+sel('Employee\'s team','cv_team_'+c.id,c.team||'',[{v:'',l:'Choose a team'}].concat(tms),tms.length?'Choose the team from the list.':'No teams are listed yet. Add the organization\'s teams in step 1.2, then choose one here.') /* 25 Oct 2026 (bug hunt B11): with no teams yet, the help points to step 1.2 */
    +ta('What was learned','cv_learned_'+c.id,c.learned,'For example, an adjuster said people stop sharing mistakes once a manager has reacted sharply to one.',3)+multi('Dimensions it bears on','cv_rows_'+c.id,culAllRowChoices(),c.rows,'Tick each dimension the conversation bears on.')+'<div>'+btn('Remove conversation','culConvDel(\''+escAttr(c.id)+'\')','bg2')+'</div>',{noun:'conversation'})}
function culObsRow(o){var w=culObsSettingLabel(o);return culFold(o.id,culFoldTitle60(o.observed),'Setting: '+(w?esc(w):'not set'),inp('Date','ob_date_'+o.id,o.date,'','date')+culSelOther('Setting','ob_setting_'+o.id,o.setting||'',[{v:'',l:'Choose a setting'}].concat(CUL_OBS_SETTING),o.settingOther,'ob_settingOther_'+o.id)+culObsMeetingField(o)+ta('What was observed','ob_observed_'+o.id,o.observed,'For example, in a pricing review the most senior person spoke first and no one challenged the model\'s output.',3)+multi('Dimensions it bears on','ob_rows_'+o.id,culAllRowChoices(),o.rows,'Tick each dimension the observation bears on.')+'<div>'+btn('Remove observation','culObsDel(\''+escAttr(o.id)+'\')','bg2')+'</div>',{noun:'observation'})}
/* ruling 155: "Which meeting was this?", optional. A meeting from step 2.4 is chosen from the list, and one not listed is named. With no meetings yet, the name is typed. */
function culObsMeetingVal(o){var m=String(o&&o.meeting||'');if(m&&m!=='other'&&!culNamed('meetings','name').some(function(r){return r.id===m}))m='';return m||(String(o&&o.meetingOther||'').trim()?'other':'')}
function culObsMeetingName(o){var v=culObsMeetingVal(o);if(v&&v!=='other'){var r=culNamed('meetings','name').filter(function(x){return x.id===v})[0];return r?String(r.name).trim():''}return v==='other'?String(o.meetingOther||'').trim():''}
function culObsMeetingField(o){var L=culNamed('meetings','name'),v=culObsMeetingVal(o);
  if(!L.length)return inp('Which meeting was this?','ob_meetingOther_'+o.id,o.meetingOther,'For example, the weekly pricing review','text','If you watched a regular meeting, name it.');
  return sel('Which meeting was this?','ob_meeting_'+o.id,v,[{v:'',l:'Choose a meeting'}].concat(L.map(function(r){return {v:r.id,l:String(r.name).trim()}}),[{v:'other',l:'A meeting not listed'}]),'If you watched a regular meeting, choose it or name it.')
    +(v==='other'?'<div class="cul-other">'+inp('Name of the meeting','ob_meetingOther_'+o.id,o.meetingOther,'','text')+'</div>':'')}
function culMissing13d(){return (culNamed('conversations','learned').length>=5&&culNamed('observations','observed').length>=3)?[]:['Conversations and Observations: add at least five conversations and three observations.']}
function culConvBrief(){return culInfoBox('<p style="margin:0 0 8px"><strong>What a conversation is.</strong> It is a talk of about half an hour between a senior leader and one employee about what working in this organization is really like. It is not an interview or an appraisal, and nothing the employee says counts against them. Ideally the employee is not one of the leader\'s direct reports.</p>'
      +'<p style="margin:0 0 8px"><strong>How to run it.</strong> Start by discussing the individual\'s work and the organization\'s culture in general, then bring in AI. Ask for examples, listen more than you talk, and do not defend the organization. Questions like these help:</p>'
      +'<ul style="margin:0 0 8px;padding-left:20px"><li>When something goes wrong on your team, what happens next?</li><li>When did you last raise a problem with someone senior, and how did it go?</li><li>What gets rewarded here in practice?</li><li>Where do you see AI, or tools like it, changing your work or your team\'s?</li><li>If you tried a new AI tool and it went wrong, what would happen to you?</li><li>What have you heard about what AI means for jobs here, and from whom?</li><li>What would make you more comfortable using AI at work?</li></ul>'
      +'<p style="margin:0"><strong>What to record.</strong> Record what you learned in a few sentences, with the employee\u2019s team and the dimensions it bears on. Never record the employee\u2019s name. Note anything that touches AI, even in passing.</p>')}
function culObsBrief(){return culInfoBox('Watch a regular meeting or a decision being made, ideally one where AI or a change to how work is done comes up. Record who spoke, whose view prevailed, how disagreement was handled, and whether anyone questioned an AI tool\'s output or a decision about AI.')}
function culS13d(){var cv=data.conversations||[],ob=data.observations||[],h='';
  h+=culSection('Conversations','Add each conversation once it has taken place. Aim for at least five conversations.',
    culConvBrief() /* Paul (12 Oct 2026): a fuller brief for the people holding the conversations */
    +culRecList({coll:'conversations',recs:culByDate(cv),addLabel:'+ Add a conversation',addFn:'culConvAdd',empty:'No conversations added yet. Aim for at least five.',
      card:function(c){var tm=(data.teams||[]).filter(function(x){return x&&x.id===c.team})[0];return culRecCard('conversations',c,culMapShort(String(c.learned||'').trim(),120)||'A conversation not yet written up',[[c.date?fmtDate(c.date):'Date not set',tm?String(tm.name||'').trim():'',String(c.leader||'').trim()?'with '+String(c.leader).trim():''].filter(Boolean).join(' \u00B7 ')])+''},
      title:function(c){return culFoldTitle60(c.learned)||'A conversation'},form:culConvRow}) /* Paul (19 Oct 2026): conversations as cards in date order, opening below, read-only, with Edit */,{count:culNamed('conversations','learned').length+', 5 needed',gate:'prog13c'}); /* design rule 3 (14 Oct 2026) */
  h+=culSection('Observations','A senior leader, or someone running this program, watches a meeting or a decision being made and records what happened. Add each observation, one at a time. Aim for at least three observations.',
    culObsBrief()
    +culRecList({coll:'observations',recs:culByDate(ob),addLabel:'+ Add an observation',addFn:'culObsAdd',empty:'No observations added yet. Aim for at least three.',
      card:function(o){var w=culObsSettingLabel(o),mn=culObsMeetingName(o);return culRecCard('observations',o,culMapShort(String(o.observed||'').trim(),120)||'An observation not yet written up',[[o.date?fmtDate(o.date):'Date not set',w,mn].filter(Boolean).join(' \u00B7 ')])},
      title:function(o){return culFoldTitle60(o.observed)||'An observation'},form:culObsRow}),{count:culNamed('observations','observed').length+', 3 needed',gate:'prog13o'});
  return h}
/* ── Section 5: practice baselines (blank stays blank, never zero; a record is created on first entry) ── */
var CUL_BASELINE_MEASURES=['experiments','concernsFormal','overrides','aiReviews','xfHeld','leaderSharing']; /* Paul (20 Oct 2026): no count of changes per team; change load is measured by the questionnaire and judged in step 4.2 */
function culMeasure(k){return CUL_MEASURES.filter(function(m){return m.k===k})[0]}
function culCountRec(k){return (data.practiceCounts||[]).filter(function(r){return r&&r.measure===k&&r.period==='baseline'})[0]||null}
function culCountLockId(k){var r=culCountRec(k);return r?r.id:'pkbase'+k} /* 8 Oct 2026 (R8): the id the baseline count will get, so its cells are locked before the record exists */
function culCountEnsure(k){var r=culCountRec(k);if(r)return r;if(Collab.lockedByOther('practiceCounts::pkbase'+k))return null;r={id:'pkbase'+k,measure:k,period:'baseline',noRecord:false};culEnsure('practiceCounts',[]).push(r);Store.commit('practiceCounts',r.id);return r}
function culPkGuard(r,elId,stored){if(Date.now()<_discardChangeUntil||Collab.lockedByOther('practiceCounts::'+r.id)){culPulseReset(elId,stored);return true}return false}
function culPkDone(r){culTouch();Store.commit('practiceCounts',r.id);culPulseMsg('');try{refreshGateInPlace()}catch(e){}}
function culPkEl(id){try{return document.getElementById(id)}catch(e){return null}}
var CUL_MAX_COUNT=100000; /* 8 Oct 2026 (R6a): the largest whole number a target per quarter or a practice count accepts */
function culPkNum(value,elId,stored){var blank=String(value==null?'':value).trim()==='';if(blank)return {blank:true};var n=Number(value);if(!isFinite(n)||n<0||n>CUL_MAX_COUNT||Math.floor(n)!==n){culPulseReset(elId,stored);culPulseMsg('Enter a whole number from 0 to 100,000, or tick “No record kept.”');return {bad:true}}return {n:n}}
function culCountSet(k,value,elId){var r=culCountRec(k),stored=(r&&r.count!=null)?String(r.count):'',v=culPkNum(value,elId,stored);if(v.bad)return false;if(v.blank&&!r)return true;
  r=r||culCountEnsure(k);if(!r){culPulseReset(elId,stored);return false}if(culPkGuard(r,elId,stored))return false;
  if(v.blank)delete r.count;else{r.count=v.n;r.noRecord=false;var cb=culPkEl('pkn_'+k);if(cb)cb.checked=false}
  culPkDone(r);if(v.blank!==(stored===''))render();return true} /* Paul (12 Oct 2026): the No record kept tick goes once a number is entered, and returns when it is cleared */
function culCountNone(k,checked,elId){var r=checked?culCountEnsure(k):culCountRec(k);if(!r){if(checked){var cb1=culPkEl(elId);if(cb1)cb1.checked=false;return false}return true}if(culPkGuard(r,elId,'')){var cb=culPkEl(elId);if(cb)cb.checked=!!r.noRecord;return false}
  r.noRecord=!!checked;if(checked){delete r.count;var inEl=culPkEl('pkc_'+k);if(inEl)inEl.value=''}culPkDone(r);return true}
function culTeamCountSet(teamId,value,elId){var r=culCountRec('changesPerTeam'),stored=(r&&r.perTeam&&r.perTeam[teamId]!=null)?String(r.perTeam[teamId]):'',v=culPkNum(value,elId,stored);if(v.bad)return false;if(v.blank&&!r)return true;
  if(!(data.teams||[]).some(function(t){return t&&t.id===teamId}))return false;
  r=r||culCountEnsure('changesPerTeam');if(!r){culPulseReset(elId,stored);return false}if(culPkGuard(r,elId,stored))return false;
  if(!r.perTeam||typeof r.perTeam!=='object')r.perTeam={};if(!r.perTeamNoRecord||typeof r.perTeamNoRecord!=='object')r.perTeamNoRecord={};
  if(v.blank)delete r.perTeam[teamId];else{r.perTeam[teamId]=v.n;delete r.perTeamNoRecord[teamId];var cb=culPkEl('pkn_changesPerTeam_'+teamId);if(cb)cb.checked=false}
  culPkDone(r);render();return true} /* the tick shows or hides with the count */
function culTeamCountNone(teamId,checked,elId){var r=checked?culCountEnsure('changesPerTeam'):culCountRec('changesPerTeam');if(!r){if(checked){var cb1=culPkEl(elId);if(cb1)cb1.checked=false;return false}return true}
  if(culPkGuard(r,elId,'')){var cb0=culPkEl(elId);if(cb0)cb0.checked=!!(r.perTeamNoRecord&&r.perTeamNoRecord[teamId]);return false}
  if(!r.perTeamNoRecord||typeof r.perTeamNoRecord!=='object')r.perTeamNoRecord={};if(!r.perTeam||typeof r.perTeam!=='object')r.perTeam={};
  if(checked){r.perTeamNoRecord[teamId]=true;delete r.perTeam[teamId];var inEl=culPkEl('pkc_changesPerTeam_'+teamId);if(inEl)inEl.value=''}else delete r.perTeamNoRecord[teamId];
  culPkDone(r);return true}
function culCountDone(k){var r=culCountRec(k);if(!r)return false;if(k==='changesPerTeam'){var ts=culRoundTeams();return ts.length>0&&ts.every(function(t){return (r.perTeamNoRecord&&r.perTeamNoRecord[t.id]===true)||(r.perTeam&&culNum(r.perTeam[t.id])!=null)})}return r.noRecord===true||culNum(r.count)!=null}
function culMissing13e(){return CUL_BASELINE_MEASURES.every(culCountDone)?[]:['What Records Show: every count needs a number or “No record kept.”']}
function culCountCell(id,lockId,handler,value,label){return '<input type="number" id="'+escAttr(id)+'" class="field-input" style="width:130px" min="0" step="1"'+' data-lock="practiceCounts::'+escAttr(lockId)+'"'+' value="'+escAttr(value)+'" placeholder="A number" aria-label="'+escAttr(label)+'" onchange="'+handler+'">'}
function culPkNoneTick(id,lockId,handler,checked){ /* renamed 12 Oct 2026: it shared its name with culNoneTick, so the None written ticks were calling this instead of saving */return '<label style="display:flex;align-items:center;gap:8px;font-size:14px;color:var(--text-body);cursor:pointer"><input type="checkbox" id="'+escAttr(id)+'"'+' data-lock="practiceCounts::'+escAttr(lockId)+'"'+(checked?' checked':'')+' onchange="'+handler+'"> No record kept</label>'}
function culS13e(){var h='<div data-pmsg="pk" role="status" style="font-size:14px;color:var(--gold-text);margin:0 0 8px"></div>',c1='',c2=''; /* design rule 11 (14 Oct 2026): the No record kept note joins the first purpose line */
  CUL_BASELINE_MEASURES.forEach(function(k){var m=culMeasure(k),r=culCountRec(k);
    if(k==='changesPerTeam'){ /* design rule 3 (14 Oct 2026): no second heading under the section heading; the definition is its purpose line */
      var ts=culRoundTeams();c2+=ts.length?ts.map(function(t){var n=r&&r.perTeam?r.perTeam[t.id]:null,nr=!!(r&&r.perTeamNoRecord&&r.perTeamNoRecord[t.id]);return '<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:0 0 8px"><div style="min-width:200px;font-size:14px">'+esc(t.name)+'</div>'+culCountCell('pkc_changesPerTeam_'+t.id,culCountLockId('changesPerTeam'),'culTeamCountSet(\''+escAttr(t.id)+'\',this.value,this.id)',n!=null?String(n):'',t.name+' changes')+(n!=null?'':culPkNoneTick('pkn_changesPerTeam_'+t.id,culCountLockId('changesPerTeam'),'culTeamCountNone(\''+escAttr(t.id)+'\',this.checked,this.id)',nr))+'</div>'}).join(''):'<p class="t-lead" style="margin:0">No teams yet. Add teams in step 1.2.</p>'}
    else c1+='<div class="cul-meas"><div style="font-weight:700;font-size:15px;margin:0 0 4px">'+esc(m.label)+'</div>'+fhelp(m.def)+'<div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap">'+culCountCell('pkc_'+k,culCountLockId(k),'culCountSet(\''+k+'\',this.value,this.id)',r&&r.count!=null?String(r.count):'',m.label)+((r&&r.count!=null)?'':culPkNoneTick('pkn_'+k,culCountLockId(k),'culCountNone(\''+k+'\',this.checked,this.id)',!!(r&&r.noRecord)))+'</div></div>'});
  return h+culSection('Counts from the last 90 days','Enter one count for each practice. Tick “No record kept” when the organization keeps no record you could count from. The missing record is itself a finding. It does not count against anyone.',c1)} /* Paul (20 Oct 2026): no count of changes per team */
CUL_BATTERIES['1.3']={page:true,intro:'Record what actually happens in your organization: what happens to people who try something new or raise a concern, what conversations and observations show, and what figures you can draw from your existing records.',sections:[ /* Paul (12 Oct 2026): step 1.3 holds the evidence; the employee questionnaire moved to step 1.2 */
  {key:'1.3c',label:'Signals in Practice',kind:null,intro:'Record what happens to people in practice, and set it beside the formal policies recorded in step 1.1. Work from records and conversations rather than impressions.',render:culS13c,missing:culMissing13c},
  {key:'1.3d',label:'Conversations and Observations',kind:null,intro:'Senior leaders talk one-to-one with employees and watch how meetings and decisions work. Record each conversation and each observation here, tagged with the dimensions it bears on.',render:culS13d,missing:culMissing13d},
  {key:'1.3e',label:'What Records Show',kind:null,intro:'Count, from your organization\u2019s records, how often each of these practices took place in the last 90 days. The counts show where the practices already happen and where nothing is recorded at all. \u201CNo record kept\u201D is itself a finding. The counts appear in the Baseline Report.',render:culS13e,missing:culMissing13e}]};

/* ── The step's part of the Baseline Report ── */
function culRowsText(ids){return (Array.isArray(ids)?ids:[]).map(function(i){var r=culRowById(i);return r?r.name:''}).filter(Boolean).join(', ')}
function culLivedPart(){var er=culBaselineFind('employees'),lr=culBaselineFind('leaders'),items=culS13Items(),teams=culRoundTeams(),sg=culSg(),
    ex=culNamed('experimenters','tried'),cs=culNamed('concerns','concern'),cut=culCutRec(),ps=culPolicyList().filter(function(p){return p.practiceAnswer}),
    cv=culNamed('conversations','learned'),ob=culNamed('observations','observed'),bases=CUL_BASELINE_MEASURES.filter(function(k){var r=culCountRec(k);return r&&(r.noRecord||culNum(r.count)!=null||(r.perTeam&&Object.keys(r.perTeam).length)||(r.perTeamNoRecord&&Object.keys(r.perTeamNoRecord).length))});
  var scored=er?items.filter(function(it){return culItemOrg(er,it.id).used!=null}):[],hasCut=sg.cutsNone===true||(cut&&(cut.when||cut.told||cut.reasonsExplained||cut.aiGiven));
  if(!scored.length&&!ex.length&&!cs.length&&!sg.experimentersNone&&!sg.concernsNone&&!hasCut&&!ps.length&&!cv.length&&!ob.length&&!bases.length)return '';
  var h=docHead('Lived Culture','What actually happens in the organization, as employees experience it and as the evidence shows.');
  if(scored.length){var r1='',orgN=culUnitResp(er,'org');if(orgN)r1+=lyRow('Respondents, whole organization',String(orgN));
    teams.forEach(function(t){var n=culUnitResp(er,t.id);if(n)r1+=lyRow('Respondents, '+t.name,String(n),true)});
    h+=docSection('How Employees Experience the Culture',culDocRow('Pulse round dates',culDatesText(er))+r1+culDocBars(er,{group:'employees',ai:false}));
    var r2='';culCultureRows().forEach(function(row){var e=culRowScore(er,row.id),l=lr?culRowScore(lr,row.id):null;if(e==null)return;r2+=lyRow(row.name,'Employees '+culFmt1(e)+(l!=null?'. Leaders '+culFmt1(l)+'. Gap '+culGapText(culGap(l,e)):''))});
    if(r2)h+=docSection('Employees Beside Leaders',r2);
    var r3='';teams.forEach(function(t){var parts=culCultureRows().map(function(row){var s=culRowScore(er,row.id,t.id);return s==null?'':row.name+' '+culFmt1(s)}).filter(Boolean);if(parts.length)r3+=lyRow(t.name+(t.manager?' (manager: '+t.manager+')':''),parts.join(' · '))});
    if(r3)h+=docSection('Scores by Team',r3);
    var r4='';scored.forEach(function(it){var o=culItemOrg(er,it.id),parts=['Whole organization '+culFmt1(o.used)];teams.forEach(function(t){var v=culUnitVal(er,t.id,it.id);if(v!=null)parts.push(t.name+' '+culFmt1(v))});r4+=lyRow(it.text,parts.join(' · '))});
    h+=docSection('Item Scores',r4);
    var fl=culFlaggedTeams();h+=docSection('Teams With Low Psychological Safety',fl.length?fl.map(function(t){var n=culSafetyNoteOf(er.id,t.id);return lyRow(t.name,'Psychological safety score '+culFmt1(culRowScore(er,1,t.id))+(n&&String(n.note||'').trim()?'. '+n.note.trim():''))}).join(''):lyRow('','No team had a psychological safety score below 3.0.'))}
  if(ex.length||sg.experimentersNone){var r5='';ex.forEach(function(x){r5+=lyRow('Case',x.tried)+culDocRow('Did it work?',culWord(CUL_WORKED,x.worked),true)+culDocRow('What happened to them',culWord(CUL_EXP_OUT,x.happened),true)});
    if(ex.length)r5+=lyRow('Outcomes',culOutCounts(CUL_EXP_OUT,'happened',ex));else r5+=lyRow('','No recent cases of someone trying something new were found.');h+=docSection('People Who Tried Something New',r5)}
  if(cs.length||sg.concernsNone){var r6='';cs.forEach(function(x){r6+=lyRow('Case',x.concern)+culDocRow('What happened to them',culWord(CUL_CON_OUT,x.happened),true)});
    if(cs.length)r6+=lyRow('Outcomes',culOutCounts(CUL_CON_OUT,'happened',cs));else r6+=lyRow('','No recent cases of someone raising a concern were found.');h+=docSection('People Who Raised Concerns',r6)}
  if(hasCut){h+=docSection('The Last Job Cuts',sg.cutsNone===true?lyRow('','No job cuts in the last two years.'):culDocRow('When',culMonthWords(cut.when))+culDocRow('How people were told',culToldLabel(cut))+culDocRow('Were the reasons explained?',culWord(CUL_CUT_REASONS,cut.reasonsExplained))+culDocRow('Was AI or automation given as a reason?',culWord(CUL_CUT_AI,cut.aiGiven)))}
  if(ps.length){var r7='';ps.forEach(function(p){r7+=lyRow('Policy',p.name)+culDocRow('Does practice match this policy?',culWord(CUL_PRACTICE,p.practiceAnswer),true)+culDocRow('Evidence',p.practiceEvidence,true)});h+=docSection('Policy Against Practice',r7)}
  if(cv.length||ob.length){var r8='';culCultureRows().forEach(function(row){var cc=cv.filter(function(c){return (c.rows||[]).map(String).indexOf(String(row.id))>=0}),oo=ob.filter(function(o){return (o.rows||[]).map(String).indexOf(String(row.id))>=0});if(!cc.length&&!oo.length)return;
      cc.forEach(function(c){r8+=lyRow(row.name,'Conversation'+(c.date?', '+lyDate(c.date):'')+(c.leader?', '+c.leader:'')+(c.team?', team: '+(culNamesOf('teams',[c.team])[0]||''):'')+'. '+c.learned)});
      oo.forEach(function(o){r8+=lyRow(row.name,'Observation'+(o.date?', '+lyDate(o.date):'')+(o.setting?', '+culObsSettingLabel(o):'')+'. '+o.observed)})});
    h+=docSection('Conversations and Observations by Dimension',r8)}
  if(bases.length){var r9='';bases.forEach(function(k){var m=culMeasure(k),r=culCountRec(k);if(k==='changesPerTeam'){r9+=lyRow(m.label,'Per team');teams.forEach(function(t){var n=r.perTeam?culNum(r.perTeam[t.id]):null,nr=r.perTeamNoRecord&&r.perTeamNoRecord[t.id];if(n!=null||nr)r9+=lyRow(t.name,n!=null?String(n):'No record kept',true)})}else r9+=lyRow(m.label,r.noRecord?'No record kept':String(r.count))});h+=docSection('What Records Show',r9)}
  return h}
CUL_BASELINE_PARTS.push({key:'livedCulture',html:culLivedPart});

/* ═══════════════════════════════════════════════════════════════════════
   STEP 1.4 AI FEARS (7 Oct 2026, Batch 2 step 6): the employee AI questions on the same employees round as step 1.3, what employees think
   AI is for, how they use it, listening sessions and themes, and the step's part of the Baseline Report.
   ═══════════════════════════════════════════════════════════════════════ */
var CUL_WIDE=[{v:'few',l:'Raised by a few',def:'Mentioned by a small number of people or in one session.',dm:'a small number of people mentioned it, or it came up in only one session.',rank:1},{v:'often',l:'Raised often',def:'Mentioned in several sessions or in a noticeable share of questionnaire answers.',dm:'it came up in several sessions or in a noticeable share of questionnaire answers.',rank:2},{v:'most',l:'Raised by most',def:'Mentioned in most sessions or by most of the people who answered the questionnaire.',dm:'it came up in most sessions or from most of the people who answered the questionnaire.',rank:3}];
function culThemeQ(k){return CUL_OPEN_Q.filter(function(q){return q.k===k})[0]||null}
function culLsAdd(){var r=culListAdd('listeningSessions',{date:'',team:'',people:'',runBy:'',notes:'',link:''});culFoldOpenNew(r.id);render()} /* renamed from culSessAdd, which a later helper of the same name (step 2.4) was overriding */
function culSessDel(id){culListDel('listeningSessions',id,'Remove this session? This cannot be undone.')}
function culThemeAdd(k){var q=k?(data.themeQuestions||[]).filter(function(x){return x&&x.id===k})[0]:null;if(q){if(UI.inlineAdd&&UI.inlineAdd.id===q.id)UI.inlineAdd=null;if(q._inlineDraft){delete q._inlineDraft;Store.commit('themeQuestions',q.id)}} /* 25 Oct 2026 (bug hunt B9): a theme added under a question uses it, so the question is no longer an abandoned blank draft: it is released from the blank-draft sweep (culListAdd sweeps the last added record first) and loses its draft flag. It stays blank and shows as Untitled question, with its field to fill */ var r=culListAdd('themes',{theme:'',question:k||'',widespread:'',teams:[],examples:[],uses:[]});culFoldOpenNew(r.id);render()}
function culThemeQAdd(){var r=culListAdd('themeQuestions',{q:''});culFoldOpenNew(r.id);UI.scrollTo='tq_q_'+r.id;render()} /* kept open so the blank draft is not swept before it is named */
function culThemeQSave(id){var el=document.getElementById('tq_new_'+id),v=el?String(el.value||'').trim():'';if(!v){if(el)el.focus();return false}fldSave('tq_q_'+id,v);render();return true} /* the saved question becomes the card's title (Paul, final pass) */ function culThemeQDel(id){var th=(data.themes||[]).filter(function(t){return t&&t.question===id});if(culDelBlocked('themeQuestions',id,[]))return;for(var _i=0;_i<th.length;_i++){var _refs=culLinksTo('themes',th[_i].id).concat(culListDelRefs('themes',th[_i].id).map(function(x){return {coll:x.coll,id:x.rec.id}}));if(culDelBlocked('themes',th[_i].id,_refs))return} /* C1-04 (audit, 31 Oct 2026: every record is checked before anything changes); audit C1-R01 (1 Nov 2026): the check includes every record a theme's removal also writes (culListDelRefs: the communications whose plans name it), so a held communication refuses the whole removal before anything is deleted */if(!confirm(th.length?'Remove this question and its '+th.length+(th.length===1?' theme':' themes')+'?':'Remove this question? This cannot be undone.'))return;for(var _j=0;_j<th.length;_j++){culListDel('themes',th[_j].id,'',true);if((data.themes||[]).some(function(x){return x&&x.id===th[_j].id})){render();return}} /* a theme still there was refused: stop, so the question is never removed with a theme left behind (audit C1-R01) */culListDel('themeQuestions',id,'',true);render()} function culThemeQCancel(id){culListDel('themeQuestions',id,'',true);render();return true} /* one question in words; Cancel on an unsaved question asks nothing (Paul, final pass: the x showed an empty confirmation) */
function culThemeDel(id){culListDel('themes',id,'Remove this theme? This cannot be undone.')}
function culEmpAiHaveScores(){var er=culBaselineFind('employees');return !!er&&culAiItems('employees').some(function(it){return culItemOrg(er,it.id).used!=null})}
function culLeadAiHaveScores(){var lr=culBaselineFind('leaders');return !!lr&&culAiItems('leaders').some(function(it){return culUnitVal(lr,'org',it.id)!=null})}
function culMissing14a(){var er=culBaselineFind('employees'),n=culAiItems('employees').filter(function(it){return culItemOrg(er,it.id).used==null}).length;return n?['Employee AI Questions: every AI item needs an organization-wide average, entered or calculated from teams.']:[]}
