function culThemesByQuestion(){var th=culNamed('themes','theme').map(function(t,i){return {t:t,i:i}});return CUL_OPEN_Q.map(function(q){var L=th.filter(function(p){return p.t.question===q.k}).sort(function(a,b){var ra=(CUL_WIDE.filter(function(o){return o.v===a.t.widespread})[0]||{rank:0}).rank,rb=(CUL_WIDE.filter(function(o){return o.v===b.t.widespread})[0]||{rank:0}).rank;return rb-ra||a.i-b.i}).map(function(p){return p.t});return {q:q,themes:L}})}
