  if(!rec){rec={id:'rsrow'+rid,row:rid};culEnsure('rowSettings',[]).push(rec);try{Array.prototype.forEach.call(document.querySelectorAll('[data-rs="'+rid+'"]'),function(e){e.setAttribute('data-lock','rowSettings::'+rec.id)})}catch(e){}}
  var was=field==='priority'?(rec.priority===true):(rec[field]==null?'':rec[field]);
  culHistPush(rec,field,was,v); /* 8 Oct 2026 (Batch 5, decision 11; Batch 6 C1: one entry per field per day): an edit after Day 90 keeps a dated entry of what it changed from and to */
  rec[field]=v;culRsMsg(rid,'');if(field==='targetScore'&&v!=='')culPulseReset(elId,culFmt1(v));
