  var h='<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr><th style="'+th+'">Dimension</th><th style="'+th+'">Current employee score</th><th style="'+th+'">Target employee score</th><th style="'+th+'">Priority</th></tr></thead><tbody>';
