  L('Conversations and observations',(!cv.length&&!ob.length)?culRsWait('Not recorded yet in step 1.3.'):((nc||no)?esc(nc+' conversation'+(nc===1?'':'s')+' and '+no+' observation'+(no===1?'':'s')+' tagged to this dimension'):'None tagged to this dimension.'));
  var types=Object.keys(CUL_POLICY_ROWS).filter(function(k){return CUL_POLICY_ROWS[k].indexOf(id)>=0});
  if(types.length){var pols=culPolicyList().filter(function(p){return types.indexOf(p.type)>=0&&p.practiceAnswer});L('Policy against practice',pols.length?pols.map(function(p){return esc(p.name+': practice matches it '+String(culWord(CUL_PRACTICE,p.practiceAnswer)||'').toLowerCase())}).join('<br>'):culRsWait('Not assessed yet in step 1.3.'))}
