function culThResp(t){return t&&t.notThisCycle===true?'notAddressed':(t&&String(t.plan||'').trim()?'answered':'')} /* 12 Oct 2026: a theme has a plan, is set aside for this cycle, or is waiting */
function culThLine(t){var q=CUL_OPEN_Q.filter(function(x){return x.k===t.question})[0],w=CUL_WIDE.filter(function(o){return o.v===t.widespread})[0];return (q?q.theme+'. ':'')+'How widespread: '+(w?w.l:'Not set')}
