    if(!CUL_RI_STATUS.some(function(o){return o.v===r.decisionStatus}))w.push('a decision status');if(!String(r.commitment||'').trim())w.push('a commitment');if(!String(r.tellWho||'').trim())w.push('who will tell them');if(!String(r.tellHow||'').trim())w.push('how they will be told');if(!culPmDateOk(r.tellDate))w.push('a delivery date');if(culRiCheckOpen(r))w.push('every checklist item ticked');
