function culCpTicked(r,k){return !!(r&&r.checklist&&typeof r.checklist==='object'&&r.checklist[k]===true)}
function culCpOpen(r){return CUL_CP_CHECK.filter(function(o){return !culCpTicked(r,o.k)}).length}
