function culHubPin(cx,cy,col){return '<g><circle cx="'+(cx+0.6)+'" cy="'+(cy+1.4)+'" r="6.2" fill="#000" opacity="0.18"/><circle cx="'+cx+'" cy="'+cy+'" r="6.2" style="fill:'+col+'"/><circle cx="'+(cx-1.8)+'" cy="'+(cy-1.8)+'" r="1.7" fill="#FFFFFF" opacity="0.55"/><circle cx="'+cx+'" cy="'+cy+'" r="6.2" fill="none" style="stroke:var(--hub-warm)" stroke-width="0.8" opacity="0.55"/></g>'} /* the Decision Lab's pin */
