function culBcStageStamp(rec,v){if(!v||rec.stage===v)return;if(!Array.isArray(rec.stageHistory))rec.stageHistory=[];rec.stageHistory.push({date:todayIso(),stage:v})} /* append-only: one entry per real change, the local day (§26.5) */
