function culBcNoCase(){return culBcCases().filter(function(c){return c.noCase===true})}
function culBcRank(c){var f=CUL_BC_VIS.filter(function(o){return o.v===c.visibility})[0];return f?f.rank:0}
function culBcSorted(){var L=culBcActive().map(function(c,i){return {c:c,i:i}});L.sort(function(a,b){return (culBcRank(b.c)-culBcRank(a.c))||(a.i-b.i)});return L.map(function(x){return x.c})} /* visibility rank descending, then the order added */
