function culRoundAnyScore(r){var R0=r&&r.results;if(!R0||typeof R0!=='object')return false;return Object.keys(R0).some(function(u){var a=R0[u]&&R0[u].avg;return !!a&&Object.keys(a).some(function(k){return a[k]!=null})})} function culFirstRows(){var r=culFirstFind(),p=(r&&Array.isArray(r.scopeRows)&&culRoundAnyScore(r))?r.scopeRows.filter(function(id){return culRowById(id)}):culPriorityRows(),x=r&&Array.isArray(r.extraRows)?r.extraRows:[];return p.concat(x.filter(function(id){return p.indexOf(id)<0&&culRowById(id)}))} /* once the first pulse has an answer it keeps the dimensions it was administered on; before that, today's priorities are its default (Paul's ruling of 31 Oct 2026; audit C3-R04) */ /* Paul (20 Oct 2026): the priority dimensions by default, and any others added to this round */
