var CUL_TK_RADAR_COPY={'radar.priority':'Priority dimension','radar.empty':'No dimension has a reading yet. The radar appears after your first pulse round.'}; /* ruling 4: the radar's own strings */
/* Copied from Architecture's assessedSeriesSVG (series drawing) */
function culTkRadarSeries(vec,point,color,fill,dash){var h='',known=vec.map(function(v){return v!==null&&v!==undefined&&isFinite(+v)&&+v>0}),attrs=' stroke="'+color+'" stroke-width="2"'+(dash?' stroke-dasharray="'+(typeof dash==='string'?dash:'5,4')+'"':'');if(known.every(Boolean))h='<polygon points="'+vec.map(function(v,i){return point(i,v)}).join(' ')+'" fill="'+(fill||'none')+'"'+attrs+'/>';else{vec.forEach(function(v,i){var j=(i+1)%vec.length;if(known[i]&&known[j]){var a=point(i,v).split(','),b=point(j,vec[j]).split(',');h+='<line x1="'+a[0]+'" y1="'+a[1]+'" x2="'+b[0]+'" y2="'+b[1]+'"'+attrs+'/>'}})}vec.forEach(function(v,i){if(!known[i])return;var p=point(i,v).split(',');h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3" fill="'+color+'"/>'});return h}
/* Copied from Architecture's layerRadar; variances (ruling 4): parameters and priority markers, and label fit for long row names */
/* UAT, 31 Oct 2026: the radar keeps its size where there is room and shrinks to its card where there is not (it ran past Analytics' card, cutting off its right-hand labels) */ function culTkRadar(series,size,opts){
  opts=opts||{};var labels=opts.labels||[],n=labels.length;if(n<3)return '';
  var S=size||220,longest=0;labels.forEach(function(l){longest=Math.max(longest,String(l).length)});
  var PAD=Math.max(44,Math.min(96,4.4*longest)),W=S+PAD*2,cx=W/2,cy=S/2,R=S*0.36,max=opts.max||5,pri=opts.priority||[],ticks=opts.ticks;
  if(!ticks){ticks=[];for(var t=1;t<=max;t++)ticks.push(t)}
  var idx=[];for(var q=0;q<n;q++)idx.push(q);
  var pt=function(i,v){var a=-Math.PI/2+i*2*Math.PI/n;return (cx+R*(v/max)*Math.cos(a)).toFixed(1)+','+(cy+R*(v/max)*Math.sin(a)).toFixed(1)};
  var h='<svg viewBox="0 0 '+W+' '+S+'" style="width:'+W+'px;max-width:100%;height:auto;display:block;margin:0 auto" role="img" aria-label="'+escAttr(opts.aria||'')+'">';
  ticks.forEach(function(r){h+='<polygon points="'+idx.map(function(i){return pt(i,r)}).join(' ')+'" fill="none" stroke="rgba(var(--fg-rgb),.08)" stroke-width="1"/>'});
  idx.forEach(function(i){h+='<line x1="'+cx+'" y1="'+cy+'" x2="'+pt(i,max).split(',')[0]+'" y2="'+pt(i,max).split(',')[1]+'" stroke="rgba(var(--fg-rgb),.08)"/>'});
  (series||[]).forEach(function(sr){if(sr&&sr.vec)h+=culTkRadarSeries(sr.vec,pt,sr.color,sr.fill,sr.dash)});
  idx.forEach(function(i){if(pri.indexOf(i)<0)return;var p=pt(i,max).split(',');h+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="4" fill="none" stroke="var(--gold-text)" stroke-width="2"><title>'+esc(CUL_TK_RADAR_COPY['radar.priority'])+'</title></circle>'});
  labels.forEach(function(l,i){var a=-Math.PI/2+i*2*Math.PI/n,c=Math.cos(a),lx=cx+(R+16)*c,ly=cy+(R+16)*Math.sin(a),anc=c>0.3?'start':c<-0.3?'end':'middle',isP=pri.indexOf(i)>=0,txt=String(l),body;
    if(txt.length>16){var mid=txt.length/2,best=-1;for(var k=0;k<txt.length;k++)if(txt.charAt(k)===' '&&(best<0||Math.abs(k-mid)<Math.abs(best-mid)))best=k;
      body=best>0?'<tspan x="'+lx.toFixed(1)+'" dy="-5">'+esc(txt.slice(0,best))+'</tspan><tspan x="'+lx.toFixed(1)+'" dy="11">'+esc(txt.slice(best+1))+'</tspan>':esc(txt)}else body=esc(txt);
    h+='<text x="'+lx.toFixed(1)+'" y="'+(ly+3).toFixed(1)+'" text-anchor="'+anc+'" font-family="DM Mono,monospace" font-size="9" fill="'+(isP?'var(--gold-text)':'var(--stone)')+'"'+(isP?' font-weight="700"':'')+'>'+body+'</text>'});
  return h+'</svg>';
}
