var CUL_UR_VERDICT=[{v:'building',l:'Good fit',def:'',dm:'the deployment supports the culture you want.'},{v:'neutral',l:'Acceptable',def:'',dm:'the deployment neither supports nor works against the culture you want.'},{v:'eroding',l:'Poor fit',def:'',dm:'the deployment works against the culture you want.'}]; /* Paul (20 Oct 2026): fit with the culture you want; the stored values are kept */
var CUL_UR_TRANSP=[{v:'engaged',l:'Engaged with',def:''},{v:'mixed',l:'Mixed',def:''},{v:'machine',l:'Managed by a machine',def:'People would feel that a system made the decision and a person only delivered it.'}];
var CUL_UR_YPN=[{v:'yes',l:'Yes',def:''},{v:'partly',l:'Partly',def:''},{v:'no',l:'No',def:''}];
var CUL_UR_DECISION=[{v:'proceed',l:'Proceed',def:'The deployment goes ahead as planned.'},{v:'proceedChanges',l:'Proceed with changes',def:'The deployment goes ahead once the organization makes the listed changes.'},{v:'pause',l:'Pause',def:'The deployment stops until the organization answers a set question.'},{v:'stop',l:'Stop',def:'The deployment does not go ahead.'}];
var CUL_UR_Q1=[{k:'q1',q:"What is this doing to our culture?",gloss:CUL_UR_COPY.b.gloss[0]},{k:'q2',q:"Is this deployment building organizational capability and trust, or is it eroding them?",gloss:CUL_UR_COPY.b.gloss[1]},{k:'q3',q:"Is the way we are implementing this consistent with the culture we say we want, or are we sacrificing the culture to hit the timeline?",gloss:CUL_UR_COPY.b.gloss[2]}];
var CUL_UR_PARTS={decide:['load','contact','prove'],culture:['q1','q2','q3'],room:['map','better','needs','transparency','transparencyNote'],identity:['says','ready','readyNote'],assumptions:['text','fit','fitNote']};
var CUL_UR_Q_FIELDS=['answer','verdict'];
var CUL_UR_BAD_TYPES=['takesOver','decides','replaces'];
function culUrRec(rid){return (data.useReviews||[]).filter(function(x){return x&&x.id===rid})[0]||null}
function culUrUse(r){return r?(data.aiUses||[]).filter(function(x){return x&&x.id===r.useId})[0]||null:null}
function culUrFor(useId){var best=null;(data.useReviews||[]).forEach(function(r){if(r&&r.useId===useId&&(!best||String(r.date||'')>=String(best.date||'')))best=r});return best} /* the latest by date; a tie goes to the later record */
function culUrMut(rid,fn){if(Date.now()<_discardChangeUntil)return false;if(lockBlocked('useReviews::'+rid)){culRefuse();return false}var r=culUrRec(rid);if(!r)return false;fn(r);culTouch();Store.commit('useReviews',rid);try{refreshGateInPlace()}catch(e){}try{culP5Refresh()}catch(e){}return true}
function culUrHas(list,v){return !v||list.some(function(o){return o.v===v})}
function culUrSet(rid,partKey,field,value){var P=CUL_UR_PARTS[partKey];if(!P||partKey==='culture'||P.indexOf(field)<0)return false;var v=String(value==null?'':value);
  if(field==='transparency'&&!culUrHas(CUL_UR_TRANSP,v))return false;if((field==='ready'||field==='fit')&&!culUrHas(CUL_UR_YPN,v))return false;
  return culUrMut(rid,function(r){var p=culMtObj(culMtObj(r,'parts'),partKey);if(v)p[field]=v;else delete p[field]})}
function culUrQ1(rid,qKey,field,value){if(CUL_UR_PARTS.culture.indexOf(qKey)<0||CUL_UR_Q_FIELDS.indexOf(field)<0)return false;var v=String(value==null?'':value);if(field==='verdict'&&!culUrHas(CUL_UR_VERDICT,v))return false;
  return culUrMut(rid,function(r){var q=culMtObj(culMtObj(culMtObj(r,'parts'),'culture'),qKey);if(v)q[field]=v;else delete q[field]})}
 function culUrStart(useId){var u=(data.aiUses||[]).filter(function(x){return x&&x.id===useId})[0];if(!u||!String(u.name||'').trim())return null;if(UI.rgGateRef&&UI.rgGateRef.id===useId)UI.rgGateRef=null;var r=culUrFor(useId);
  if(r){culFoldOpenNew('ur34_'+r.id);render();return r}
  if(Collab.lockedByOther('useReviews::ur'+useId)){try{alert(CUL_RV_COPY['miss.startBusy'])}catch(e){}return null}
  try{sweepBlankInline(true)}catch(e){}
  r={id:'ur'+useId,useId:useId,date:'',parts:{},decision:'',changesRequired:'',decidedBy:'',humanInRoom:''};culEnsure('useReviews',[]).push(r);culInlineAdded('useReviews');culTouch();Store.commit('useReviews',r.id);culFoldOpenNew('ur34_'+r.id);render();return r} /* culListAdd renders; a second start for the same use returns the first review and opens it */
CUL_HANDLER_LOCKS.push({fn:'culUrSet',coll:'useReviews'},{fn:'culUrQ1',coll:'useReviews'}); /* 8 Oct 2026 (Batch 4, step 3.4): the review's keyed savers; the review id is the first quoted argument. culUrStart is not listed: its first argument is a use id, and it only creates. */
function culUrNeedsRoom(u){return !!u&&CUL_UR_BAD_TYPES.indexOf(u.changeKind)>=0}
function culUrMust(u){return !!u&&!!String(u.name||'').trim()&&(u.status==='inUse'||u.status==='pilot')&&culAdGateKinds().indexOf(u.changeKind)>=0}
function culUrDone(r){var u=culUrUse(r);return !!u&&culUrMissing(u,r).length===0}
function culReviewsDoneIn(startIso,endIso){var seen={};(data.useReviews||[]).forEach(function(r){if(r&&r.useId&&culPmDateOk(r.date)&&r.date>=startIso&&r.date<=endIso&&culUrDone(r))seen[r.useId]=true});return Object.keys(seen).length} /* the reviewsDone calculator: distinct uses with a completed review dated in the period; not displayed yet */

/* ═══ Step 3.4, job 2: the tabs Deployments to Review and Charter Entry (3.4b is filled by a later job) ═══ */
function culUrState(u){var r=culUrFor(u.id);return !r?'none':(culUrDone(r)?'done':'part')}
function culUrDecide(rid,v){if(!CUL_UR_DECISION.some(function(o){return o.v===v}))return false;var _k=null;try{_k=idToRecordKey('ur_decision_'+rid)}catch(e){}if(_k&&Collab.lockedByOther(_k)){culRvBusy();return false} /* Sweep 3 item 6, 1 Nov 2026: a refusal under a held record says why */if(fldSave('ur_decision_'+rid,v)){render();return true}return false} /* the decision buttons save through the same field as the decision box did */
function culUrOpen(useId){var nu=(data.aiUses||[]).filter(function(x){return x&&x.id===useId})[0];if(!nu||!String(nu.name||'').trim())return null;UI.s34Tab='3.4b';var r=culUrFor(useId);if(r){culFoldOpenNew('ur34_'+r.id);render();return r}return culUrStart(useId)} /* "Open review": goes to The Culture Review and opens (or starts) that use's review */
function culS34a(){var A=CUL_UR_COPY.a,us=(data.aiUses||[]).filter(function(u){return u&&u.id}),gold='<span style="color:var(--gold-text);font-weight:700">';
  var folds=us.map(function(u){var id=escAttr(u.id),so=CUL_USE_STATUS.filter(function(o){return o.v===u.status})[0],st=culUrState(u),r=culUrFor(u.id),must=culUrMust(u),chips=[];
    chips.push('Status: '+esc(so?so.l:'not set'));
    chips.push('Review: '+esc((st==='done'?'complete':st==='part'?'in progress':'not started')));
    if(r&&r.decision)chips.push('Decision: '+esc(culWord(CUL_UR_DECISION,r.decision)));
    if(must)chips.push(gold+esc(A.chipMust)+'</span>'); /* design rule 9 (14 Oct 2026): label and value, the same order on every use; the kind of change is in the fold */
    return culFold('ur34a_'+u.id,u.name,chips,'<div class="mb-4">'+(!String(u.name||'').trim()?'':btn(esc(A.btnReview),'culUrOpen(\''+id+'\')','bp'))+'</div>'+culUseFields(u)+'<div>'+btn('Remove','culUseDel(\''+id+'\')','bg2')+'</div>',{noun:'AI use'})}).join('');
  var form=function(u){var id=escAttr(u.id);return (String(u.name||'').trim()?'<div class="mb-4"><button type="button" class="btn bp" onclick="'+escAttr("culUrOpenRec('"+culFoldJs(u.id)+"')")+'">'+esc(culUrFor(u.id)?A.btnReview:CUL_UR_COPY.b.startBtn)+'</button></div>':'')+culUseFields(u)+'<div>'+btn('Remove','culUseDel(\''+id+'\')','bg2')+'</div>'};
  return culSection('AI uses',A.note,'<div style="margin:0 0 14px">'+fhelp(A.addPurpose)+btnAdd('+ '+esc(A.btnAdd),"culRecAdd('aiUses','culUseAdd','3.4')")+'</div>'+(culNamed('aiUses','name').length?culUrTilesRec('aiUses'):'<p class="t-lead" style="margin:0 0 10px">'+esc(A.empty)+'</p>')+culRecBox('aiUses',us,function(u){return String(u.name||'').trim()||'Unnamed AI use'},form),{count:culNamedCount(us,'name')})} /* Paul (19 Oct 2026): a tile for each AI use with its review status; a use opens below the tiles, read-only, with Edit, and its review is one button away */ /* design rules (14 Oct 2026): one section card holds the list, its count on the heading and the review rule in its purpose line */
function culMissing34a(){var A=CUL_UR_COPY.a,named=culNamed('aiUses','name');if(!named.length)return (data.aiGoals||{}).usesNone?[]:[A.missNone];
  return named.filter(function(u){return culUrMust(u)&&!culUrDone(culUrFor(u.id))}).map(function(u){return A.missUse.replace('{use}',u.name)})}
/* ═══ Step 3.4b The Culture Review (Batch 4, 8 Oct 2026). Look modeled on Architecture's Alignment Gate card: a colored left border per verdict and a gloss under each question. Nested answers save through culUrSet/culUrQ1 (data-lock on every control); Part 5's top-level fields save through fldSave ('ur_<field>_<id>'). ═══ */
function culUrCtl(h,call,rid,rerender){return h.split('fldSave(this.id,this.value,true)').join(call).split('fldSave(this.id,this.value)').join(rerender?'if('+call+')render()':call).replace(/<(textarea|input|select) /,'<$1 data-lock="useReviews::'+escAttr(rid)+'" ')}
function culUrQuote(s){return "'"+escAttr(s)+"'"}
function culUrDefs(list){return list.filter(function(o){return o.def}).map(function(o){return '\u201C'+o.l+'\u201D: '+o.def}).join(' ')}
function culUrOpts(list,ph){return [{v:'',l:ph}].concat(list.map(function(o){return {v:o.v,l:o.l}}))}
function culUrPartBox(n,inner){var B=CUL_UR_COPY.b;return '<div class="cul-ur-part" style="'+(n>1?'border-top:1px solid rgba(var(--fg-rgb),.08);padding-top:16px;':'')+'margin:0 0 18px"><h4 class="h-sub" style="margin:0 0 4px">'+esc(B.heads[n-1])+'</h4><p class="cul-sec-purpose" style="margin:0 0 12px">'+esc(B.purpose[n-1])+'</p>'+inner+'</div>'}
function culUrNoteField(rid,partKey,field,label,val,req){return culUrCtl(ta(label+(req?'':''),'urn_'+partKey+'_'+field+'_'+rid,val,'',2),'culUrSet('+culUrQuote(rid)+','+culUrQuote(partKey)+','+culUrQuote(field)+',this.value)',rid,false)}
function culUrTextField(rid,partKey,field,label,val,help){return culUrCtl(ta(label+'','urt_'+partKey+'_'+field+'_'+rid,val,'',3,help),'culUrSet('+culUrQuote(rid)+','+culUrQuote(partKey)+','+culUrQuote(field)+',this.value)',rid,false)}
function culUrSelField(rid,partKey,field,label,val,list,ph,help){return culUrCtl(sel(label /* no asterisk: readiness is not required (Paul, 30 Oct 2026) */,'urs_'+partKey+'_'+field+'_'+rid,val||'',culUrOpts(list,ph),help),'culUrSet('+culUrQuote(rid)+','+culUrQuote(partKey)+','+culUrQuote(field)+',this.value)',rid,true)}
function culUrQ1Block(r,q,i){var rid=r.id,P=r.parts||{},c=(P.culture||{})[q.k]||{},call=function(f){return 'culUrQ1('+culUrQuote(rid)+','+culUrQuote(q.k)+','+culUrQuote(f)+',this.value)'};  return '<div class="cul-urq"><div class="cul-urq-h">'+esc(q.q)+'</div>'+fhelp(q.gloss)+culUrCtl(ta('Your answer','urq_'+q.k+'_answer_'+rid,c.answer||'','',3),call('answer'),rid,false)+'<div class="mb-4" data-lock="useReviews::'+escAttr(rid)+'"><div class="form-label">Fit with the culture you want</div><div class="cmap-tri" role="group" aria-label="Fit with the culture you want" style="--c:var(--p3)">'+CUL_UR_VERDICT.map(function(o){return '<button type="button" id="urq_'+q.k+'_verdict_'+escAttr(rid)+'_'+o.v+'" data-lock="useReviews::'+escAttr(rid)+'" aria-pressed="'+(c.verdict===o.v)+'" onclick="'+escAttr("culUrFitSet('"+culFoldJs(rid)+"','"+q.k+"','"+o.v+"')")+'">'+esc(o.l)+'</button>'}).join('')+'</div></div></div>'} /* each culture question is a card; its fit is chosen with three buttons (Paul, 27 Oct 2026: the deployment review as a summary and three tabs) */
/* culUrOverrideBox deleted: nothing drew it (Paul, 26 Oct 2026) */ /* design rule 6 (14 Oct 2026): step 2.3's override rule is reference, folded away */
function culUrTeamHint(u){var ids=u&&Array.isArray(u.teams)?u.teams:[],n=culNamed('teams','name').filter(function(t){return ids.indexOf(t.id)>=0}).map(function(t){return t.name});return n.length?'This AI use involves these teams: '+n.join(', ')+'.':''}
 /* Paul (19 Oct 2026): the dimensions read down the left column, then down the right */
/* ═══ Paul (20 Oct 2026): step 3.4 puts the culture question into AI decisions. One list of AI uses; each review is a short decision record whose answers lead to the decision ═══ */
function culUrBox(title,purpose,inner,first){return '<div class="cul-ur-part" style="'+(first?'':'border-top:1px solid rgba(var(--fg-rgb),.08);padding-top:16px;')+'margin:0 0 18px"><h4 class="h-sub" style="margin:0 0 4px">'+esc(title)+'</h4>'+(purpose?'<p class="cul-sec-purpose" style="margin:0 0 12px">'+esc(purpose)+'</p>':'')+inner+'</div>'}
function culUrRisky(r){var c=((r&&r.parts)||{}).culture||{},id=((r&&r.parts)||{}).identity||{};return ['q1','q2','q3'].some(function(k){return (c[k]||{}).verdict==='eroding'})||id.ready==='no'||id.ready==='partly'}
