function culAdLocSections(){var C=CUL_AD_COPY,K=C.card,h=''; /* where the stated culture is published, and the retired wording removed from it: drawn on the tab and in step 4.1's panel */
  var locs=(data.publishLocations||[]).filter(function(r){return r&&r.id}),lrow=function(r){var id=escAttr(r.id);
    return culFold('pl41_'+r.id,r.location,[culAdStChip(CUL_AD_LOCSTATUS,r.status)],inp('Location','pl_location_'+r.id,r.location,'For example, the website or the employee handbook','text')+sel('Status','pl_status_'+r.id,r.status||'',[{v:'',l:'Choose a status'}].concat(CUL_AD_LOCSTATUS))+'<div>'+btn('Remove','culAdLocDel(\''+id+'\')','bg2')+'</div>',{noun:'location'})};
  h+=culSection(K.locations.h,K.locations.p,culFoldCards({coll:'ad41loc',recs:locs,row:lrow,addLabel:'+ '+C.btnAddLocation,addFn:'culAdLocAdd',empty:C.empty.locations,unnamed:'Unnamed location'}),{count:culNamedCount(locs,'location')});
  var ret=culAdRetired(),named=culAdLocations(),rrow=function(x){var r=x.rec,id=String(r.id);
    var ticks=named.map(function(l){var on=!!(l.retiredRemoved&&typeof l.retiredRemoved==='object'&&l.retiredRemoved[id]===true);
      if(CUL_RO)return '<div style="font-size:14px;line-height:1.6;color:var(--text-body)">'+(on?'\u2713 Removed from ':'\u25CB Not yet removed from ')+esc(culAdT(l.location))+'</div>';
      return '<label style="display:flex;align-items:flex-start;gap:10px;font-size:14px;color:var(--text-body);line-height:1.5;cursor:pointer;margin:0 0 6px"><input type="checkbox" style="margin-top:3px" data-lock="publishLocations::'+escAttr(l.id)+'"'+(on?' checked':'')+' onchange="culAdRetTick('+culUrQuote(l.id)+','+culUrQuote(id)+',this.checked)"><span>'+esc(culAdT(l.location))+'</span></label>'}).join('');
    var done=named.filter(function(l){return !!(l.retiredRemoved&&typeof l.retiredRemoved==='object'&&l.retiredRemoved[id]===true)}).length;
    return culFold('rt41_'+id,culVcName(x.coll,r),[esc('Removed from: '+done+' of '+named.length)],(ticks||'<p class="t-lead" style="margin:0">'+esc(C.empty.locations)+'</p>'),{noun:x.coll==='values'?'value':'commitment'})},rf=ret.length?culFoldCards({coll:'ad41ret',recs:ret,idOf:function(x){return x.coll+':'+x.rec.id},row:rrow}):'';
  h+=culSection(K.retired.h,K.retired.p,rf||'<p class="t-lead" style="margin:0">'+esc(C.empty.retired)+'</p>',rf?{count:ret.length}:{});
  return h}
function culFoldCap(fn){var K=culFold,cap={title:'',chips:[]};culFold=function(key,title,chipHtml,bodyHtml,opts){cap={title:String(title==null?'':title),chips:Array.isArray(chipHtml)?chipHtml.filter(Boolean):(chipHtml?[chipHtml]:[])};return ''};try{fn()}finally{culFold=K}return cap}
function culPlainOf(h){return String(h==null?'':h).replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim()}
function culChipTone(s){return /with changes|\bChanges\b/.test(s)?'info':/\b(Adopted|In effect|Continues|Removed from every|Live|Published|Updated)\b/.test(s)?'ok':/\b(Overdue|not set|Not started|Ends)\b/i.test(s)?'warn':/\b(Pending|Approved|Drafted|Changes|In progress|Planned)\b/.test(s)?'info':''}
function culFoldCards(a){var recs=a.recs.map(function(r){return {id:String(a.idOf?a.idOf(r):r.id),src:r}});
  return culRecList({coll:a.coll,recs:recs,addLabel:a.addLabel,addFn:a.addFn,empty:a.empty||'',
    card:function(w){var cap=culFoldCap(function(){return a.row(w.src)}),c0=culPlainOf(cap.chips[0]||'');return culRecCard(a.coll,w,cap.title||a.unnamed||'Unnamed',cap.chips.slice(1).map(culPlainOf),c0?culTag(c0.replace(/^Status: /,''),culChipTone(c0)):'',a.color||'var(--p4)')},
    title:function(w){return culFoldCap(function(){return a.row(w.src)}).title||a.unnamed||'Unnamed'},form:function(w){return a.row(w.src)}})} /* Paul (19 Oct 2026): a list of folds drawn as cards, each opening below, read-only, with Edit; the fold's own body is the form */
function culS41a(){var C=CUL_AD_COPY,K=C.card,h='',s=culAdStatementItem(),kept=culAdKept();
  var vrow=function(r){var c=(data.values||[]).indexOf(r)>=0?'values':'commitments',px=c==='values'?'vl':'co',how=r.origin==='new'?'New in step 2.1':culVcDec(r)==='revise'?'Revised in step 2.1':'Kept in step 2.1',rw=(r.origin!=='new'&&culVcDec(r)==='revise'&&String(r.revisedWording||'').trim())?': '+String(r.revisedWording).trim():'';
    return culAdFromBox('ad41vc_'+r.id,'Decision in step 2.1',how+rw)+culAdAdoptFields(function(f){return px+'_'+f+'_'+r.id},r)};
  if(!s)h+=culSection(K.statement.h,K.statement.p,'<p class="t-lead" style="margin:0 0 10px">'+esc(C.empty.statement)+'</p>');
  else h+=culSection(K.statement.h,K.statement.p,culRecList({coll:'ad41st',recs:[{id:'statement',rec:s.rec,name:s.name}],empty:'',
      card:function(x){return culRecCard('ad41st',x,'The culture statement',[culMapShort(x.name,220)],culAdOverdueChip(x.rec)?culTag(culPlainOf(culAdOverdueChip(x.rec)),'warn'):'','var(--p4)','<div class="cmap-wcard-b">'+culAdMark('statement','statement',x.rec)+'</div>')},
      title:function(){return 'The culture statement'},form:function(x){return culAdFromBox('ad41st','Wording from step 2.1',x.name)+culAdAdoptFields(function(f){return 'sm_'+f},x.rec)}}));
  h+=culSection(K.values.h,K.values.p,kept.length?culRecList({coll:'ad41vc',recs:kept,empty:'',
      card:function(r){var c=(data.values||[]).indexOf(r)>=0?'values':'commitments',how=r.origin==='new'?'new in step 2.1':culVcDec(r)==='revise'?'revised in step 2.1':'kept in step 2.1',od=culAdOverdueChip(r);
        return culRecCard('ad41vc',r,culMapShort(culVcOptLabel(c,r),110),[(c==='values'?'Value':'Commitment')+', '+how],od?culTag(culPlainOf(od),'warn'):'','var(--p4)',culChips(culItemDims(c,r))+'<div class="cmap-wcard-b">'+culAdMark(c,r.id,r)+'</div>')},
      title:function(r){var c=(data.values||[]).indexOf(r)>=0?'values':'commitments';return culMapShort(culVcOptLabel(c,r),110)},form:vrow}):'<p class="t-lead" style="margin:0 0 10px">There are no values or commitments to adopt yet. Add them in step 2.1 Target Culture.</p>',{count:kept.length});
  h+=culAdLocSections();
  return h}
function culAdPolFold(p){var C=CUL_AD_COPY,id=p.id,ac=culWord(CUL_POLICY_ACTION,p.action),chips=[culAdStChip(CUL_AD_POLSTATUS,p.adoptionStatus),'Action: '+esc(ac||'not set')],od=culAdOverdueChip(p),inEff=p.adoptionStatus==='inEffect';if(od)chips.push(od);
  return culFold('po41_'+id,culAdT(p.name),chips,culAdFromBox('ad41po_'+id,'Action from step 2.3',ac+(String(p.changes||'').trim()?': '+String(p.changes).trim():''))
    +sel('Status','po_adoptionStatus_'+id,p.adoptionStatus||'',[{v:'',l:'Choose a status'}].concat(CUL_AD_POLSTATUS),C.help.inEffect)
    +inp('Approved by'+(inEff?'':''),'po_approvedBy_'+id,p.approvedBy,'','text','The body or role that approves it.')
    +inp('Takes effect'+(inEff?'':''),'po_takesEffect_'+id,p.takesEffect,'','date','The date it takes effect.')
    +inp('Where to find it','po_adoptionLives_'+id,p.adoptionLives,'For example, the intranet policy library','text',String(p.lives||'').trim()?C.keptAt+': '+String(p.lives).trim():'')
    ,{noun:'policy'})}
function culAdCritFold(r,px){var C=CUL_AD_COPY,id=r.id,dt=culPmDateOk(r.reviewCycleDate)?r.reviewCycleDate:'',chips=[esc('Review cycle: '+(dt?fmtDate(dt):'not set'))],od=culAdOverdueChip(r);if(od)chips.push(od);
  var tk='<label class="cul-pri" onclick="event.stopPropagation()" title="'+escAttr(C.help.templates)+'"><input type="checkbox" id="'+escAttr(px+'_templatesUpdated_'+id)+'"'+(r.templatesUpdated===true?' checked':'')+' onchange="fldSave(this.id,this.checked)"><span>Templates updated</span></label>'; /* design rule 9 (14 Oct 2026): a yes-or-no attribute is a tick on the header */
  return culFold('cr41_'+px+'_'+id,culAdT(r.text),chips,inp('Review cycle it enters',px+'_reviewCycleDate_'+id,r.reviewCycleDate,'','date',C.help.reviewPoint),{noun:px==='cr'?'criterion':'manager duty',headExtra:tk})}
