  var dd=c.driftReviewDate,end=at(12);if(dd>=d0&&dd<=end){var mi=12;for(var n=1;n<=12;n++){if(dd<=at(n)){mi=n;break}}out.push({date:dd,monthIndex:mi,kind:'drift'})}
