function culClLimits(){var s=culClStored(),mx=s.maxChanges,ru=s.ruleAtLimit,mxHas=mx!=null&&mx!=='',ruHas=ru!=null&&ru!=='',mxOk=!mxHas||culClMaxOk(mx),ruOk=!ruHas||CUL_CL_RULE.some(function(o){return o.v===ru}),ex=String(s.exceptionsBy==null?'':s.exceptionsBy).trim();
  return {max:(mxHas&&mxOk)?mx:CUL_CL_MAX_DEF,rule:(ruHas&&ruOk)?ru:'wait',exceptions:ex||CUL_CL_COPY.b.exceptPlaceholder,edited:mxHas||ruHas||!!ex,maxBad:!mxOk,ruleBad:!ruOk}} /* defaults are read, never stored; a stored value that is invalid falls back to the default here and is reported by culMissing43b */
function culClTeam(id){return (data.teams||[]).filter(function(t){return t&&t.id===id})[0]||null}
function culClBase(teamId){var r=culCountRec('changesPerTeam');if(!r||!r.perTeam||typeof r.perTeam!=='object')return null;if(r.perTeamNoRecord&&r.perTeamNoRecord[teamId])return null;var v=r.perTeam[teamId];return (typeof v==='number'&&isFinite(v))?v:null} /* the 1.3 count: No record kept, or no entry, is no count */
