var CUL_RV_CONSIST=[{v:'yes',l:'Keeps'},{v:'partly',l:'Strains'},{v:'no',l:'Breaks'}];
var CUL_RV_LISTS=[{v:'doubleDown',l:CUL_RV_COPY.labels.ncDoubleDown,h:CUL_RV_COPY['nc.dd.h'],p:CUL_RV_COPY['nc.dd.p'],add:CUL_RV_COPY['nc.add.dd']},{v:'redesign',l:CUL_RV_COPY.labels.ncRedesign,h:CUL_RV_COPY['nc.rd.h'],p:CUL_RV_COPY['nc.rd.p'],add:CUL_RV_COPY['nc.add.rd']},{v:'confront',l:CUL_RV_COPY.labels.ncConfront,h:CUL_RV_COPY['nc.cf.h'],p:CUL_RV_COPY['nc.cf.p'],add:CUL_RV_COPY['nc.add.cf']}];
