function culRvAgendaOf(rv){if(rv&&rv.loggedAt&&Array.isArray(rv.agendaAtLog))return rv.agendaAtLog.map(function(a){return {k:a.k,name:a.name}});return rv?culRvAgenda(rv.type):[]} /* a logged review keeps the agenda it was held with */
