/* audit C4-R01 (1 Nov 2026): once a review is logged, the Next Cycle and counts rules are not rerun, because they read today's priorities and today's Charter measures, which belong to the next review; the review's own record (coverage, date, the other items) is still checked */ function culRvMissing(rv){var m=[];if(!rv)return m;culRvAgendaOf(rv).forEach(function(a){if(!culRvCovered(rv,a.k))m.push(culRvT('miss.uncovered',{name:a.name}));else if(!(rv.loggedAt&&(a.k==='nextCycle'||a.k==='counts')))culRvItemMissing(rv,a.k).forEach(function(x){if(m.indexOf(x)<0)m.push(x)})}); /* close-out fix 2: a covered item is checked again at log time */
  if(!culPmDateOk(rv.date))m.push(CUL_RV_COPY['miss.date']);else if(rv.date>todayIso())m.push(CUL_RV_COPY['miss.dateFuture']);
  return m} /* who attended is not required (Paul, 29 Oct 2026: only what the module cannot run without is required) */
