function culGaList(type){var k=culRvListKey(type);if(k!=='quarterly'&&k!=='annual')return null;if(!data.agendaItems||typeof data.agendaItems!=='object'||Array.isArray(data.agendaItems))data.agendaItems={};if(!data.agendaItems[k]||typeof data.agendaItems[k]!=='object'||Array.isArray(data.agendaItems[k]))data.agendaItems[k]={};return data.agendaItems[k]}
