var CUL_TK_COL={target:'var(--gold-text)',baseline:'var(--stone)',latest:'var(--head-blue)'}; /* radar and spark colors, existing theme variables */
function culTkRadarData(shown){var names=shown.map(function(r){return r.x.row.name}),pri=[];shown.forEach(function(r,i){if(r.x.priority)pri.push(i)});
  var sr=[{vec:shown.map(function(r){return r.x.targetScore}),color:CUL_TK_COL.target,dash:true},{vec:shown.map(function(r){return r.x.baseline}),color:CUL_TK_COL.baseline},{vec:shown.map(function(r){return r.latest}),color:CUL_TK_COL.latest}];
  return {sr:sr,names:names,pri:pri,aria:culTkT('tk.radar.aria',{rows:names.join(', ')})}} /* 8 Oct 2026 (Batch 6, 5.1): the one series builder the 5.2 radar and the dashboard hero share */
function culTkRadarCard(shown){var h='<div class="card" data-tkradar="1" style="padding:20px 24px;margin-bottom:20px"><h4 class="h-sub" style="margin:0 0 4px">'+esc(CUL_TK_COPY['tk.radar.h'])+'</h4><p class="t-stone-13" style="margin:0 0 10px">'+esc(CUL_TK_COPY['tk.radar.sub'])+'</p>'
  +'<label style="display:flex;align-items:center;gap:8px;font-size:14px;margin:0 0 12px;cursor:pointer"><input type="checkbox" id="tk_pri_only"'+(UI.tkPriOnly===true?' checked':'')+' onchange="culTkPri(this.checked)"><span>'+esc(CUL_TK_COPY['tk.radar.filter'])+'</span></label>';
  if(shown.length<3)return h+'<p data-tkradar-empty="1" class="t-stone-13" style="margin:0">'+esc(CUL_TK_COPY['tk.radar.empty'])+'</p></div>';
  var rs=culTkRadarData(shown);
  h+=culTkRadar(rs.sr,330*1.5,{labels:rs.names,max:5,priority:rs.pri,aria:rs.aria});
  var lg=function(k,c){return '<span style="display:inline-flex;align-items:center;gap:6px"><span aria-hidden="true" style="width:14px;height:3px;border-radius:2px;background:'+c+'"></span>'+esc(CUL_TK_COPY[k])+'</span>'};
  return h+'<div data-tkradar-legend="1" style="display:flex;justify-content:center;gap:18px;flex-wrap:wrap;font-size:13px;margin-top:8px">'+lg('tk.radar.legend.target',CUL_TK_COL.target)+lg('tk.radar.legend.baseline',CUL_TK_COL.baseline)+lg('tk.radar.legend.latest',CUL_TK_COL.latest)+'</div></div>'}
function culTkChip(t,gold,attr){return '<span '+attr+' class="cul-fold-chip" style="'+(gold?'color:var(--gold-text);':'')+'margin:0 6px 4px 0;display:inline-block;white-space:normal;line-height:1.3;max-width:100%">'+esc(t)+'</span>'}
function culTkWordClip(t,n){t=String(t==null?'':t).replace(/\s+/g,' ').trim();if(t.length<=n)return t;return t.slice(0,n).replace(/\s+\S*$/,'').replace(/[,;:.\s]+$/,'')+'…'} /* Full pass round 21 (B1): clip at a word boundary */
function culTkRowBlock(r,opt){opt=opt||{};var x=r.x,row=x.row,key=(opt.key||'tk')+row.id,f=r.flags,th=r.th,open=r.open,dim='color:var(--text-faint)',P='font-size:13px;line-height:1.5;margin:0 0 4px',
  col=function(label,body){return '<div style="min-width:0"><div class="t-stone-13" style="font-weight:600;margin:0 0 4px">'+esc(label)+'</div>'+body+'</div>'};
  if(!UI.expanded)UI.expanded={};var isOpen=!!UI.expanded[key],c0=r.commitments[0];
  var c1='<p data-tkname="1" style="'+P+';font-weight:600;font-size:14px;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap"><span>'+esc(row.name)+'</span>'+(x.targetScore!=null?'<span data-tkscore="1" style="font-size:13px;font-weight:400;color:var(--text-muted)">'+esc(culFmt1(x.targetScore))+'</span>':'')+'</p><p title="'+escAttr(x.target||'')+'" style="'+P+(x.target?'':';'+dim)+'">'+esc(x.target?culTkWordClip(x.target,150):CUL_TK_COPY['tk.noTarget'])+'</p>'
    +'<p style="'+P+(c0?'':';'+dim)+'">'+esc(c0?String(c0.commitment||c0.text||c0.name||c0.statement||c0.measure||''):CUL_TK_COPY['tk.noCommit'])+'</p>';
  var c2;if(r.latest==null)c2='<p style="'+P+(x&&x.baseline!=null?'':';'+dim)+'">'+esc(x&&x.baseline!=null?culTkT('tk.baseOnly',{n:culFmt1(x.baseline)}):CUL_TK_COPY['tk.noReading'])+'</p>'; /* a baseline reading shows as such (Paul, 27 Oct 2026: Phase 5 review fixes) */
  else c2='<p style="'+P+'">'+esc(culTkT('tk.latest',{n:culFmt1(r.latest)}))+(x.delta!=null?' · '+esc(culTkT('tk.change',{n:culChangeText(x.delta)})):'')+'</p><div style="width:120px;margin:0 0 4px" aria-hidden="true">'+culSpark(r.spark,CUL_TK_COL.latest)+'</div>'
    +(r.leaderLatest!=null?'<p style="'+P+'">'+esc(culTkT('tk.leaders',{n:culFmt1(r.leaderLatest)}))+(r.gaps&&r.gaps.now!=null?' · '+esc(culTkT('tk.leaders.gap',{n:culGapText(r.gaps.now)})):'')+'</p>':'');
  var c3=r.commitments.length?r.practice.map(function(p){var t=p.noRecord?CUL_TK_COPY['tk.practice.norec']:(p.count==null?CUL_TK_COPY['tk.practice.none']:culTkT(p.fewer?'tk.practice.lineMax':'tk.practice.line',{count:String(p.count),target:p.target==null?'–':String(p.target)}));return '<p style="'+P+'">'+esc(p.label)+': '+esc(t)+'</p>'}).join(''):'';
  if(!c3)c3='<p style="'+P+';'+dim+'">'+esc(CUL_TK_COPY['tk.practice.noMeasure'])+'</p>';
  var c4='';
  if(x.priority&&!opt.statusOnly)c4+=culTkChip(CUL_TK_COPY['tk.pri'],true,'data-tkpri="1"');
  if(f.any){if(f.drop)c4+=culTkChip(culTkT('tk.flag.drop',{n:culFmt1(Math.round((f.details.previous-f.details.latest)*10)/10)}),true,'data-tkflag="drop"');if(f.below)c4+=culTkChip(CUL_TK_COPY['tk.flag.base'],true,'data-tkflag="base"');if(f.practice)c4+=culTkChip(culTkT('tk.flag.practice',{p:String(th.practicePercent)}),true,'data-tkflag="practice"')}
  else c4+=culTkChip(r.latest==null?((r.x&&r.x.baseline!=null)?'Not measured since the baseline':'No reading yet'):CUL_TK_COPY['tk.ok'],false,'data-tkok="1"'); /* no reading is not Holding (Paul's ruling 50, 2 Nov 2026) */
  if(open){c4+='<p data-tkrecheck="1" style="'+P+';color:var(--gold-text)">'+esc(culTkT('tk.recheck.open',{role:culRcLead(open.ledBy),date:fmtDate(open.due)}))+' <button type="button" class="cul-rcx" aria-label="Cancel this re-check" title="Cancel this re-check" onclick="event.stopPropagation();culRcCancel(\''+escAttr(open.id)+'\')">\u00D7</button></p>'; /* the small x on the Tracker's row (Paul, 1 Nov 2026) */if(open.due&&todayIso()>open.due)c4+='<p data-tkoverdue="1" style="'+P+';color:var(--gold-text);font-weight:600">'+esc(CUL_TK_COPY['tk.recheck.overdue'])+'</p>'}
  if(opt.status)c4+=opt.status(row.id); if(opt.statusOnly)return c4+(f.any&&!open?'<div style="margin-top:6px" onclick="event.stopPropagation()">'+btn(esc(CUL_TK_COPY['tk.recheck.start']),'culTkStartRecheck('+Number(row.id)+')','bg2','font-size:12px;padding:4px 10px')+'</div>':''); return '<details class="cul-fold" data-fold="'+escAttr(key)+'" data-tkrow="'+row.id+'"'+(isOpen?' open':'')+' ontoggle="culFoldSet(\''+culFoldJs(key)+'\',this.open)"><summary class="cul-fold-sum" style="align-items:flex-start"><span class="cul-fold-mk" aria-hidden="true"></span><div style="flex:1;min-width:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;font-weight:400">'
    +col(CUL_TK_COPY['tk.col.target'],c1)+col(CUL_TK_COPY['tk.col.report'],c2)+col(CUL_TK_COPY['tk.col.does'],c3)+col(CUL_TK_COPY['tk.col.status'],c4)+'</div></summary><div class="cul-fold-body"><div data-tkbody="'+row.id+'">'+(opt.body?opt.body(row.id,r):culTkBody(row.id,r))+'</div></div></details>'}
/* 8 Oct 2026 (Batch 6, 5.2 B3): the body of an opened Tracker row, and the re-check actions. The body reads culTkRow only. The one thing it starts or closes is a re-check, through culRcStart and culRcClose. */
function culTkReadings(x){var C=CUL_RV_COPY,R=x.readings,th0='padding:6px 8px;border-bottom:1px solid var(--border-faint);text-align:left;font-weight:600',td='padding:7px 8px;border-bottom:1px solid var(--border-softer);vertical-align:top',dash='<span style="color:var(--text-faint)">–</span>';
  if(!R.length)return '<p style="font-size:14px;line-height:1.6;margin:0 0 6px">'+esc(C['rd.noReadings'])+'</p>';
  return '<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr>'+['rd.col.round','rd.col.kind','rd.col.date','rd.col.score','rd.col.diff'].map(function(k){return '<th style="'+th0+'">'+esc(C[k])+'</th>'}).join('')+'</tr></thead><tbody>'+R.map(function(r){return '<tr><td style="'+td+'">'+(r.name?esc(r.name):dash)+'</td><td style="'+td+'">'+esc(r.kind)+'</td><td style="'+td+'">'+(r.date?esc(fmtDate(r.date)):dash)+'</td><td style="'+td+'">'+esc(culFmt1(r.score))+'</td><td style="'+td+'">'+(r.diff==null?dash:esc(culGapText(r.diff)))+'</td></tr>'}).join('')+'</tbody></table></div>'}
function culTkStartRecheck(rowId){if(!culFlags(rowId).any)return null; /* a re-check starts only on a slipping row (bug hunt B18, Paul 25 Oct 2026: re-checks are for slipping rows only); the Tracker button, which calls this, shows on slipping rows only */ var r=culRcStart(rowId);if(r){render();return r}try{var m=document.querySelector('[data-pmsg="tkrc'+Number(rowId)+'"]');if(m)m.textContent=CUL_TK_COPY['tk.recheck.refused']}catch(e){}return null}
function culTkCloseRecheck(rowId){var o=culRcOpen(rowId);if(!o)return false;var f=document.getElementById('tkrc_f_'+o.id),a=document.getElementById('tkrc_a_'+o.id); var miss=[];if(!String(f?f.value:'').trim())miss.push(CUL_TK_COPY['tk.recheck.findings']);if(!String(a?a.value:'').trim())miss.push(CUL_TK_COPY['tk.recheck.action']);if(miss.length){culRvAlert(miss);return false} /* 25 Oct 2026 (bug hunt B19): the family Still needed message names the empty fields */ if(!culRcClose(o.id,f?f.value:'',a?a.value:'')){culRefuse();return false}render();return true}
/* a small x cancels a re-check started by accident (Paul, 1 Nov 2026); the note once sat inside the HTML string and printed (Sweep 5 item 30) */ function culTkBody(rowId,r){r=r||culTkRow(rowId);if(!r||!r.x)return '';var x=r.x,f=r.flags,th=r.th,open=r.open,T=CUL_TK_COPY,OW=CUL_OW_COPY,
  P='font-size:14px;line-height:1.6;color:var(--text-body);margin:0 0 6px',H='font-size:13px;font-weight:600;color:var(--paper);margin:14px 0 6px',
  th0='padding:6px 8px;border-bottom:1px solid var(--border-faint);text-align:left;font-weight:600',td='padding:7px 8px;border-bottom:1px solid var(--border-softer);vertical-align:top',dash='<span style="color:var(--text-faint)">–</span>',
  nsec=0,sec=function(k){return (nsec++?'</div>':'')+'<div class="cd cul-sec" style="margin:0 0 12px"><h4 class="h-sub cul-sec-h" data-tksec="'+k+'">'+esc(T[k])+'</h4>'},
  tbl=function(heads,rows){return '<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%;font-size:14px"><thead><tr>'+heads.map(function(k){return '<th style="'+th0+'">'+esc(T[k])+'</th>'}).join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>'},
  sc=function(n){return n==null?dash:esc(culFmt1(n))},h='';
  h+=sec('tk.sec.readings')+culTkReadings(r);
  h+=sec('tk.sec.items');
  if(!r.items.length)h+='<p style="'+P+'">'+esc(T['tk.items.none'])+'</p>';
  else h+=tbl(['tk.col.item','tk.col.base','tk.col.latest'],r.items.map(function(i){return '<tr><td style="'+td+'">'+(i.text?esc(i.text):dash)+'</td><td style="'+td+'">'+sc(i.base)+'</td><td style="'+td+'">'+sc(i.latest)+'</td></tr>'}));
  h+=sec('tk.sec.teams');
  if(!r.teams.length)h+='<p style="'+P+'">'+esc(T['tk.teams.none'])+'</p>';
  else h+=tbl(['tk.col.team','tk.col.change','tk.col.resp'],r.teams.map(function(t){return '<tr><td style="'+td+'">'+esc(t.team.name)+'</td><td style="'+td+'">'+((t.base==null&&t.latest==null)?dash:esc((t.base==null?'–':culFmt1(t.base))+' to '+(t.latest==null?'–':culFmt1(t.latest))))+'</td><td style="'+td+'">'+(t.respondents==null?dash:esc(String(t.respondents)))+'</td></tr>'}));
  h+=sec('tk.sec.gap');var G=r.gaps||{base:null,now:null};
  if(G.base==null&&G.now==null)h+='<p style="'+P+'">'+esc(CUL_RV_COPY['rd.gap.none'])+'</p>';
  else{if(G.base!=null)h+='<p style="'+P+'">'+esc(culRvT('rd.gap.base',{n:culGapText(G.base)}))+'</p>';if(G.now!=null)h+='<p style="'+P+'">'+esc(culRvT('rd.gap.now',{n:culGapText(G.now)}))+'</p>'}
  h+=sec('tk.sec.charter');
  if(!r.commitments.length)h+='<p style="'+P+';color:var(--text-faint)">'+esc(T['tk.noCommit'])+'</p>';
  else{r.commitments.forEach(function(c){h+='<p style="'+P+'">'+esc(String(c.commitment||c.text||c.name||c.statement||c.measure||''))+'</p>'});
    r.practice.forEach(function(p){var t=p.noRecord?T['tk.practice.norec']:(p.count==null?T['tk.practice.none']:culTkT(p.fewer?'tk.practice.lineMax':'tk.practice.line',{count:String(p.count),target:p.target==null?'–':String(p.target)}));h+='<p style="'+P+'">'+esc(p.label)+': '+esc(t)+'</p>'})}
  /* copy pass, Phase 5 Pass 2 (20 Oct 2026): no per-dimension threshold block; decision 318 made the rule fixed, and the introduction states it */ h+=sec('tk.sec.recheck')+'<p style="'+P+'">'+esc(T['tk.recheck.explain'])+'</p><div data-pmsg="tkrc'+Number(rowId)+'" role="status" style="font-size:14px;color:var(--gold-text);margin:0 0 8px"></div>';
  if(!open){if(f.any){h+='<p data-tkflagged="1" style="'+P+'">'+esc(T['tk.recheck.flagged'])+'</p>';h+=btn(esc(T['tk.recheck.start']),'culTkStartRecheck('+Number(rowId)+')','bp')}} /* the re-check button shows on slipping rows only (bug hunt B18, Paul 25 Oct 2026: re-checks are for slipping rows only) */
  else{var lk=escAttr('rechecks::'+open.id),lab='font-size:13px;font-weight:600;margin:10px 0 2px;display:block',ts='width:100%;box-sizing:border-box;min-height:84px';
    h+='<p style="'+P+';display:flex;align-items:flex-start;gap:8px"><span style="flex:1">'+esc(culTkT('tk.recheck.open',{role:culRcLead(open.ledBy),date:fmtDate(open.due)}))+'</span><button type="button" class="cul-rcx" aria-label="Cancel this re-check" title="Cancel this re-check" onclick="culRcCancel(\''+escAttr(open.id)+'\')">\u00D7</button></p><p style="'+P+'">'+esc(culTkT('tk.recheck.started',{date:fmtDate(open.started)}))+'</p>';
    if(open.due&&todayIso()>open.due)h+='<p style="'+P+';color:var(--gold-text);font-weight:600">'+esc(T['tk.recheck.overdue'])+'</p>';
    h+='<label for="tkrc_f_'+escAttr(open.id)+'" style="'+lab+'">'+esc(T['tk.recheck.findings'])+'</label><div class="t-stone-13" style="margin:0 0 4px">'+esc(T['tk.recheck.findings.help'])+'</div><textarea id="tkrc_f_'+escAttr(open.id)+'" data-lock="'+lk+'" style="'+ts+'" onchange="culRcText(\''+escAttr(open.id)+'\',\'findings\',this.value,this.id)">'+esc(open.findings||'')+'</textarea>'
      +'<label for="tkrc_a_'+escAttr(open.id)+'" style="'+lab+'">'+esc(T['tk.recheck.action'])+'</label><div class="t-stone-13" style="margin:0 0 4px">'+esc(T['tk.recheck.action.help'])+'</div><textarea id="tkrc_a_'+escAttr(open.id)+'" data-lock="'+lk+'" style="'+ts+'" onchange="culRcText(\''+escAttr(open.id)+'\',\'action\',this.value,this.id)">'+esc(open.action||'')+'</textarea>'
      +'<p class="t-stone-13" style="margin:8px 0">'+esc(T['tk.recheck.closedNote'])+'</p>'+btn(esc(T['tk.recheck.close']),'culTkCloseRecheck('+Number(rowId)+')','bp')}
  var done=culRcList().map(function(k,i){return {k:k,i:i}}).filter(function(p){return Number(p.k.row)===Number(rowId)&&p.k.status==='done'}).sort(function(a,b){var x1=String(a.k.closedOn||''),y1=String(b.k.closedOn||'');return x1!==y1?(x1<y1?1:-1):b.i-a.i});
  if(done.length)h+='<div data-tkclosed="1" style="margin-top:14px">'+done.map(function(p){var k=p.k;return '<div style="border-top:1px solid var(--border-softer);padding:8px 0"><p style="'+P+'">'+esc(culTkT('tk.recheck.started',{date:fmtDate(k.started)}))+(k.closedOn?' · '+esc(fmtDate(k.closedOn)):'')+' · '+esc(k.ledBy)+'</p><p style="'+P+';white-space:pre-wrap">'+esc(k.findings)+'</p><p style="'+P+';white-space:pre-wrap">'+esc(k.action)+'</p></div>'}).join('')+'</div>';
  return h+'</div>'}
