function culReviewTitle(rv){return !rv?'Culture Review':rv.type==='day90'?'First Culture Review':rv.type==='annual'?'Annual Culture Review':'Quarterly Culture Review'} function culReviewDoc(rv){if(!rv||!rv.loggedAt)return printDocCover('Culture Review',CUL_RV_COPY['out.d90.notHeld'],'')+CUL_DOC_NONE;var held=culPmDateOk(rv.date)?culCoDate(rv.date):'',lead=rv.type==='day90'?CUL_RV_COPY['out.d90.lead']:('The '+(rv.type==='annual'?'annual':'quarterly')+' culture review'+(held?' held on '+held:'')+': where the culture stands, the decision on each dimension, and the plan for the next cycle.');return printDocCover(culReviewTitle(rv),lead,'')+culCoRender(culRrModel(rv,'print-review'),'paper')} /* a logged review prints from its own page (family spec 22.6.2; Paul, 30 Oct 2026: Phase 5 has no outputs) */ function culD90Doc(){var rv=culRvDay90(),M=culRrModel(rv,'out-day90');return printDocCover(CUL_RV_COPY['out.d90.title'],M.empty?CUL_RV_COPY['out.d90.notHeld']:CUL_RV_COPY['out.d90.lead'],'') /* the ruled title and lead */+(M.empty?CUL_DOC_NONE:culCoRender(M,'paper'))} /* on the family pattern (Paul, 30 Oct 2026) */
