function culRvsAttSet(type,i,value){if(lockBlocked('reviewSettings')){culRefuse();return false} /* R-16 (Paul, 30 Oct 2026; Rollout 53): a refused save returns the field to its stored value */var L=culRvsAtt(type),v=String(value==null?'':value).trim();if(i<0||i>=L.length)return false;if(v)L[i]=v;else L.splice(i,1);culTouch();Store.commit('reviewSettings');render();return true}
