function docFieldsToValues(h){ /* \u00a722.6.3: a form field prints as its value \u2014 an input as its text, a select as its chosen label, a textarea as its content */
  var nr='<span style="color:#999">Not recorded</span>';
  h=h.replace(/<select\b[^>]*>([\s\S]*?)<\/select>/g,function(m,opts){var s=opts.match(/<option\b[^>]*\bselected\b[^>]*>([\s\S]*?)<\/option>/);return '<span class="gd-val">'+(s?s[1]:nr)+'</span>'});
  h=h.replace(/<textarea\b[^>]*>([\s\S]*?)<\/textarea>/g,function(m,t){return '<span class="gd-val">'+(t.trim()?t:nr)+'</span>'});
  h=h.replace(/<input\b[^>]*>/g,function(m){if(/type="(checkbox|radio|hidden)"/.test(m))return '';var v=m.match(/\svalue="([^"]*)"/);return '<span class="gd-val">'+(v&&v[1]?v[1]:nr)+'</span>'});
  return h}
