 h+='<section class="mp-land"><div class="mp-h">The Culture Map</div><p class="mp-lead">Every initiative the organization is running, set against the dimensions it is meant to move. An initiative aimed at two dimensions appears in both.</p>'+key+'<div class="mp-cols-h"><div>Dimension</div><div>Score <span class="s">\u00B7 baseline, latest reading and target (ring), out of 5</span></div><div>Initiatives, by type</div><div>Count</div></div>'+dims.map(function(d){var L=its(d.id);return '<div class="mp-row"><div class="mp-name">'+esc(d.name)+culMapPrintTags(d)+'</div><div class="mp-score">'+culMapTrack(d)+'</div><div class="mp-sqs">'+(L.length?culMapPrintSqs(L):'<span style="font-size:10.5px;color:#6b7280">Nothing aimed at this yet</span>')+'</div><div class="mp-n">'+L.length+'</div></div>'}).join('')+'</section>';
 h+='<section class="mp-names"><div class="mp-h">The initiatives on the map</div><p class="mp-lead">What each square on the map stands for, dimension by dimension, grouped by type.</p><div class="mp-cols">'+dims.map(function(d){var L=its(d.id);return '<div class="mp-dim"><h3>'+esc(d.name)+' <span class="mp-st">('+L.length+')</span></h3>'+(L.length?CUL_MAP_KINDS.map(function(k){var g=L.filter(function(it){return it.kind===k.k});if(!g.length)return '';return '<div class="mp-k"><span class="mp-sq" style="background:rgb('+culMapCv(k.k)+')"></span> '+esc(k.l)+' ('+g.length+')</div><ul>'+g.map(function(it){return '<li>'+esc(String(it.name||'').trim())+(it.status&&it.status!=='inPlace'?' <span class="mp-st">\u00B7 '+esc(culLifeLabel(it.status))+'</span>':'')+'</li>'}).join('')+'</ul>'}).join(''):'<p class="mp-st" style="font-size:10.5px;margin:0">Nothing aimed at this dimension yet.</p>')+'</div>'}).join('')+'</div></section>';
 if(full)h+=dims.map(function(d){return culMapDimDoc(d,its(d.id))}).join('');
