function culCoT(L,v){return (typeof culWord==='function'&&L?culWord(L,v):'')||String(v==null?'':v)}
function culCoTeam(id){var t=(data.teams||[]).filter(function(x){return x&&x.id===id})[0];return t?String(t.name||'').trim():''}
function culCoRole(id){var t=(data.roles||[]).filter(function(x){return x&&x.id===id})[0];return t?String(t.name||'').trim():''}
function culCoRound(g,c){return (data.pulseRounds||[]).filter(function(r){return r&&r.group===g&&r.context===c})[0]||null}
function culCoEmp(r,row){var v=r?culRowScore(r,row):null;return v==null?null:Math.round(v*10)/10} /* step 1.2's own organization score (Paul, 29 Oct 2026: the radar and each question's answers, as in 1.2) */
function culCoLead(r,row){var v=r?culRowScore(r,row,'org'):null;return v==null?null:Math.round(v*10)/10}
function culCoPct(r,key,opt){var s=0,n=0;Object.keys((r&&r.choiceTeams)||{}).forEach(function(u){var m=r.choiceTeams[u]&&r.choiceTeams[u][key],w=Number(((r.results||{})[u]||{}).respondents)||0;if(m&&w>0&&m[opt]!=null){s+=(Number(m[opt])||0)*w;n+=w}});return n?Math.round(s/n):null}
function culCoJoin(L){return typeof culJoinAnd==='function'?culJoinAnd(L):L.join(', ')}
function culCoHeat(v){return v==null?'':v<2.5?'co-h1':v<3?'co-h2':v<3.5?'co-h3':v<4?'co-h4':'co-h5'}
function culCoTable(cols,rows,title){if(!rows.length)return '';return (title?'<h3>'+esc(title)+'</h3>':'')+'<table class="co-table"><thead><tr>'+cols.map(function(c){return '<th>'+esc(c)+'</th>'}).join('')+'</tr></thead><tbody>'+rows.map(function(r){return '<tr>'+r.map(function(c){return '<td>'+(c&&typeof c==='object'&&c.h!=null?c.h:esc(c==null||c===''?'Not recorded':String(c)))+'</td>'}).join('')+'</tr>' /* a cell given as {h:...} is prepared HTML (Paul, 30 Oct 2026: Priority beneath the dimension's name) */}).join('')+'</tbody></table>'}
function culCoDumbbell(dims){var L=dims.filter(function(d){return d.emp!=null||d.lead!=null});if(!L.length)return '';var W=680,lx=210,rx=620,rh=28,H=34+L.length*rh,X=function(v){return lx+(v-1)/4*(rx-lx)};var s='<svg class="co-svg" viewBox="0 0 '+W+' '+H+'" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Leaders and employees by dimension">';[1,2,3,4,5].forEach(function(t){s+='<line class="co-grid" x1="'+X(t)+'" y1="18" x2="'+X(t)+'" y2="'+(H-6)+'"/><text class="co-ax" x="'+X(t)+'" y="12" font-size="10" text-anchor="middle">'+t+'</text>'});L.forEach(function(d,i){var y=34+i*rh;s+='<text class="co-lbl" x="0" y="'+(y+4)+'" font-size="12">'+esc(d.name)+'</text>';if(d.emp!=null&&d.lead!=null)s+='<line class="co-link" x1="'+X(d.empR!=null?d.empR:d.emp)+'" y1="'+y+'" x2="'+X(d.leadR!=null?d.leadR:d.lead)+'" y2="'+y+'" stroke-width="3"/>';if(d.emp!=null)s+='<circle class="co-de" cx="'+X(d.empR!=null?d.empR:d.emp)+'" cy="'+y+'" r="6"/>';if(d.lead!=null)s+='<circle class="co-dl" cx="'+X(d.leadR!=null?d.leadR:d.lead)+'" cy="'+y+'" r="6"/>';if(d.emp!=null&&d.lead!=null){var g=Math.round((d.lead-d.emp)*10)/10;s+='<text class="co-gap'+(Math.abs(g)>=0.5?' hi':'')+'" x="'+(W-4)+'" y="'+(y+4)+'" font-size="11" text-anchor="end">'+(g>0?'+':'')+culFmt1(g)+'</text>'}});return '<div class="co-key" style="margin-top:18px"><span><i class="co-dl"></i>Leaders</span><span><i class="co-de"></i>Employees</span><span>The figure at the right is the leaders\u2019 score minus the employees\u2019.</span></div>'+s+'</svg>'}
function culCoStack(parts){var t=parts.reduce(function(a,p){return a+(p.v||0)},0);if(!t)return '';return '<div class="co-stack">'+parts.filter(function(p){return p.v>0}).map(function(p){return '<span style="width:'+(p.v/t*100)+'%;background:'+p.c+'" title="'+escAttr(p.l+': '+p.v+'%')+'">'+(p.v>=8?esc(p.v+'%'):'')+'</span>'}).join('')+'</div><div class="co-key">'+parts.map(function(p){return '<span><i style="background:'+p.c+';border-radius:2px"></i>'+esc(p.l+' '+(p.v==null?'':p.v+'%'))+'</span>'}).join('')+'</div>'}

  /* screen: the family's tiles, cards and tabs in theme colors; paper: the print styling, each section on a new page (Paul, 29 Oct 2026: outputs in the family style) */
var CUL_BR_LEAD='Where the organization starts: what it says about its culture and its AI, how leaders and employees read the culture, what actually happens, and what people fear.';

