function culTabStripInstr(h){return String(h).replace(/<h2\b[^>]*>[\s\S]*?<\/h2>/,'').replace(/<p class="t-lead"[^>]*>[\s\S]*?<\/p>/g,'').replace(/<p class="(?:cul-sec-purpose|cmap-lead)"[^>]*>[\s\S]*?<\/p>/g,'').replace(/<h4 class="h-sub"[^>]*>[\s\S]*?<\/h4>\s*(?:<p\b[^>]*>[\s\S]*?<\/p>)?/g,'')} /* a tab print carries no on-screen instructions: the page heading the cover gives, the lead, the section explanations and an editor's own heading with its instruction (Paul, 31 Oct 2026; family spec 22.4.2) */ function culStandingTabDoc(r){return p5Read(function(){var body=r.draw();return printDocCover(r.title,r.tab,'')+p5AnalyticsStyles()+culAnPrintStyles()+'<div class="an-doc">'+culTabStripInstr(_pdFormsToText(p5Clean(_pbStrip(body))))+'</div>'})}
function culStandingPrint(){var f=CUL_SP_PRINT[currentPage];if(!f)return false;var r=f();
 if(r.out&&PRINT_DOCS[r.out]){var _o=[];PH.forEach(function(ph){(ph.outcomes||[]).forEach(function(x){if(x.id===r.out)_o.push(x.name)})});printDocument(_o[0]||'Report',PRINT_DOCS[r.out](),'');return true} /* the output's own name, as the window title */
 if(r.pack){printDocument(r.pack.name,p5Read(function(){var id='sp_pack_'+currentPage;rcDefs().push({id:id,name:r.pack.name,subtitle:r.pack.subtitle,units:r.pack.units.map(function(x){var c=rcCatalogue().filter(function(u){return u.kind==='output'&&u.id===x})[0];return c?JSON.parse(JSON.stringify(c)):{kind:'output',id:x}}) /* each unit from its catalogue entry, as a saved report's units are */});return rcCompile(id)}),'');return true} /* the Report Manager's own compiler, unchanged (byte-identical to the family's): the pack is a definition added to a copy of the data, never saved */
 if(r.tab){printDocument(r.title+': '+r.tab,culStandingTabDoc(r),'');return true}
 return false}
var OUTPUT_PAGES={'out-baseline':renderBaselineOutput,'out-aiuses':renderAiUseInventoryOutput,'out-target':renderTargetOutput,'out-powermap':renderPowerMapOutput,'out-rewiring':renderRewiringPlanOutput,'out-comms':renderCommsPlanOutput,'out-charter':renderCharterOutput,'out-culturereport':renderCultureReportOutput,'out-blockers':renderBlockersOutput,'out-aireview':renderAiReviewOutput,'out-sustainment':renderSustainmentOutput,'out-day90':renderDay90Output}; /* Batch 2: the Baseline Report's on-screen page */
function renderOutcomePage(){var id=currentStep;var h='<div class="content-area pt-110"><div class="content-inner">'+culBackBtn(); /* the family page frame (Paul, 29 Oct 2026: outputs in the family style) */ var _op=OUTPUT_PAGES[id]; h+=_op?_op():'<p style="color:var(--stone)">Output not found.</p>'; return h+'</div></div>'}

