function renderReviewPractices(){var rv=culRvView(),a=(culRvCore(rv?rv.type:'quarterly').filter(function(x){return x.k==='practices'})[0])||{steps:[]};var h='<div class="content-area"><div class="content-inner">';h+=culBackBtn();h+='<h2 style="font-size:22px;font-weight:700;margin:0 0 4px">Standing Practices</h2><p style="color:var(--text-faint);margin:8px 0 16px;line-height:1.6;font-size:14px">'+esc((a.steps||[]).join(' '))+'</p>';h+=culRvProgLine();h+='<div data-pmsg role="status" style="font-size:14px;color:var(--gold-text);margin:0 0 8px"></div>';h+=culRvPracticesBlock(rv);return h+'</div></div>'} /* the quarterly and annual reviews' Standing Practices, on a page of its own, so a long list does not swell the agenda (Paul, 1 Nov 2026) */
function renderReviewMap(){var rv=culRvView(),done=!!(rv&&rv.covered&&rv.covered.map),open=!!(rv&&!rv.loggedAt); var h='<div style="padding-top:calc(var(--nav-h,100px) + 16px)"><div class="content-inner cul-mapstep"><div class="cul-narrow">'+culBackBtn()+culRvProgLine()+'<h1 style="font-family:var(--serif);font-size:clamp(28px,3.5vw,42px);font-weight:300;margin:6px 0 12px">Review the Culture Map</h1><p class="t-lead" style="margin:0 0 14px">Review the initiatives aimed at each dimension. Keep what still works, change what needs changing, and fill any gaps you see.</p>'; h+='<div class="cul-rmbar">'+(done?'<span class="cul-rvdone">\u2713 Review complete</span>'+btn('Back to the review','culRvBackGo()','bg2','font-size:12px;padding:5px 12px'):(open?btn('Review complete','culRmDone()','bp'):''))+'</div></div>'; if(UI.mapBoard&&culRowById(UI.mapBoard))h+='<div data-db="board">'+culDbBoard(UI.mapBoard)+'</div>'+culPanelHtml()+culMapToastHtml(); else h+='<div data-db="hero">'+culDbAddCtl()+culDbMap()+'</div>'+culPanelHtml()+culMapToastHtml(); /* (Paul, 1 Nov 2026) */ return h+'</div></div>'} function culRmDone(){var rv=culRvView();if(!rv||rv.loggedAt)return false;if(!(rv.covered&&rv.covered.map))culRvCover(rv.id,'map');if(!(rv.covered&&rv.covered.map))return false;UI.mapBoard=null;culRvBackGo();return true} /* item 4 on a page of its own: the instruction, one Review complete button above the map, which marks the agenda item; Mark complete on the agenda sets the same mark (Paul, 28 Oct 2026: item 4 on its own page, one Review complete button) */
function renderPhase5(){
  var h='<div style="padding-top:calc(var(--nav-h,100px) + 16px)"><div class="content-inner cul-mapstep cul-dash">'; /* decision 203 (15 Oct 2026, Paul): the dashboard widens to 1,240 pixels like the step pages, with the same left edge (replaces decision 157). 10 Nov 2026: cul-dash — every section of the dashboard takes that width, so its cards line up with the culture map instead of sitting in the 804-pixel column inside it */
  h+=renderDashboardContent();
  h+='</div></div>';
  return h;
}


