// === VOICE ACTIVATION ===
/* Voice (Rollout item 40): the Architecture/ER cluster, Culture's page vocabulary. 25 Sep 2026 — replaces the superseded Pipeline-exemplar voice form. */
var _voiceActive=false,_recognition=null;
function _voiceToast(msg){var el=document.getElementById('voiceToast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(_voiceToast._t);_voiceToast._t=setTimeout(function(){el.classList.remove('show')},2600);}
function _voiceUI(on){var f=document.getElementById('voiceFab'),ic=document.getElementById('voiceIcon'),lb=document.getElementById('voiceLabel');if(f)f.classList.toggle('listening',!!on);if(ic)ic.innerHTML=on?'\u25C9':'\u25C9';if(lb)lb.textContent=on?'Listening\u2026':'Voice';}
function toggleVoice(){ if(!(typeof _voiceActive!=='undefined'&&_voiceActive)&&!voiceOn())return; /* 2 Oct 2026 (Spec §25.2): Voice never starts while its switch is off */
  if(typeof _voiceActive!=='undefined'&&_voiceActive){
    _voiceActive=false;
    if(_recognition)try{_recognition.stop();}catch(e){}
    _voiceUI(false);_voiceToast('Voice off');
    return;
  }
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){_voiceToast('Voice needs Chrome or Edge');return;}
  _recognition=new SR();
  _recognition.continuous=true;_recognition.interimResults=false;_recognition.lang='en-US';
  _recognition.onstart=function(){_voiceActive=true;_voiceUI(true);_voiceToast('Listening\u2026 try \u201Chome\u201D, \u201Cframework\u201D, \u201Cstop\u201D');};
  _recognition.onresult=function(e){
    var tx=e.results[e.results.length-1][0].transcript.trim().toLowerCase();
    _voiceToast('Heard: '+tx);
    if(tx.match(/\b(home)\b/)){go('home');}
    else if(tx.match(/\b(learn|library|research)\b/)){go('learn');}
    else if(tx.match(/\b(framework|pipeline|phase|journey)\b/)){go('pipeline');}
    else if(tx.match(/\b(insight|data)\b/)){go('insights');}
    else if(tx.match(/\b(dashboard)\b/)){go('phase5');}
    else if(tx.match(/\b(coach|guide)\b/)&&typeof coachOpen!=='undefined'&&!coachOpen){toggleCoach();}
    else if(tx.match(/\b(notes?)\b/)&&!notesOpen){toggleNotes();}
    else if(tx.match(/\b(help)\b/)){openHelp();}
    else if(tx.match(/\b(stop|quiet|cancel)\b/)){toggleVoice();}
  };
  _recognition.onerror=function(e){
    var msg=e.error==='not-allowed'?'Microphone access denied':e.error==='no-speech'?'No speech detected':'Voice error: '+e.error;
    _voiceUI(false);_voiceActive=false;_voiceToast(msg);
  };
  _recognition.onend=function(){if(_voiceActive){try{_recognition.start();}catch(e){_voiceActive=false;_voiceUI(false);}}};
  try{_recognition.start();}catch(e){_voiceToast('Could not start voice');}
}





// Init
/* 25 Oct 2026 (conformance audit F1, Spec §14): the boot runs behind the Store's readiness seam, the donor's form. Locally ready() fires in the same tick, so start-up is unchanged; on a server build the loading note holds the app node until the cache is warm. */
Store.ready(function(){ bootApp(); render(); });
if(!_bootDone){ try{ var _bootEl=document.getElementById('app'); if(_bootEl) _bootEl.innerHTML='<div style="padding:140px 24px;text-align:center;font-size:15px;opacity:.7">Loading your workspace\u2026</div>'; }catch(e){} }
// Auto-expand textareas
document.addEventListener('input',function(e){if(e.target.tagName==='TEXTAREA'){e.target.style.height='auto';e.target.style.height=e.target.scrollHeight+'px'}});
/* the sample is seeded with month-only dates; they become full dates for the date pickers (Paul, 31 Oct 2026) */
_culSeed0=seedSampleData; seedSampleData=function(){var _sr=0;try{_sr=Math.max(+(Store.raw.get('culture-org-rev::'+currentOrgId)||0),(data&&data.rev)||0)}catch(e){} var r=_culSeed0.apply(this,arguments);try{var _n=culDateFullFix();try{culRoundScopeFix();_n++}catch(e){}try{data.rev=Math.max((data&&data.rev)||0,_sr);data.resetAt=Date.now();try{_lastResetSeen=data.resetAt}catch(e2){}_n++}catch(e){} /* the seeding tab has nothing typed to discard; other tabs see the new stamp */ /* Sweep 3 item 1, 1 Nov 2026: a replacement saves above the stored revision, so every open tab adopts it, and is stamped like a reset, so their typed drafts are discarded */ if(_n){try{saveData()}catch(e){}}}catch(e){} /* the seed's priority rounds record their dimensions too (C5-05) */return r};
/* Sweep 5 item 8 (2 Nov 2026): a date box saves only a complete date with a four-digit year, 1900 or later, when the person leaves the box, and never redraws mid-entry. While a date box has focus its input and change events stop at the document, so no box's own writer sees a half-typed year (0002, 0020, 0202); on leaving, a changed, valid value (or a deliberate blank) is passed to the box's own onchange as one change event, so each box keeps its own rules; a half-typed or impossible date returns to what it was and says why. */
try{(function(){var isD=function(t){return !!t&&t.tagName==='INPUT'&&String(t.type).toLowerCase()==='date'};
document.addEventListener('focusin',function(e){var t=e.target;if(isD(t)&&!t.__culDateOn){t.__culDateOn=true;t.__culDateStart=t.value}},true); /* the value when editing began, kept through any refocus mid-entry */
['input','change'].forEach(function(ev){document.addEventListener(ev,function(e){var t=e.target;if(isD(t)&&!e.__culDateCommit&&t.__culDateOn)e.stopPropagation() /* held for the whole editing session, whatever the box held before (Sweep 6 item 2) */},true)});
document.addEventListener('focusout',function(e){var t=e.target;if(!isD(t))return;t.__culDateOn=false;var v=t.value,s=t.__culDateStart==null?'':t.__culDateStart;if(v===s)return;var bad=(t.validity&&t.validity.badInput)||(v&&!(/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number(v.slice(0,4))>=1900));if(bad){t.value=s;try{culMapToast('Enter a complete date with a four-digit year, 1900 or later.');render()}catch(x){}return}t.__culDateStart=v;var ev;try{ev=new Event('change',{bubbles:true})}catch(x){ev=document.createEvent('Event');ev.initEvent('change',true,true)}ev.__culDateCommit=true;t.dispatchEvent(ev)},true)})()}catch(e){}

/* ═══ GLOBAL INPUT LENGTH CAP (family drop-in — 10,000 characters; ruled 17 Aug 2026) ═══
   One rule for the whole app: no text field may hold more than 10,000 characters.
   This single document-level listener covers every existing field, every page and
   modal, and every field created later. Do not add per-field maxlength attributes;
   this block is the whole mechanism. */
(function(){
  var INPUT_CHAR_CAP=10000;
  var CAPPED_INPUT_TYPES=['text','search','email','url','tel','password'];
  document.addEventListener('input',function(e){
    var el=e.target;
    if(!el||!el.tagName)return;
    var isTextArea=(el.tagName==='TEXTAREA');
    var isTextInput=(el.tagName==='INPUT'&&CAPPED_INPUT_TYPES.indexOf(el.type)>=0);
    if(!isTextArea&&!isTextInput)return;
    if(typeof el.value==='string'&&el.value.length>INPUT_CHAR_CAP){
      el.value=el.value.slice(0,INPUT_CHAR_CAP); /* keep the first 10,000 characters; drop the rest */
    }
  },true); /* true = capture phase: the cap runs even if other code stops the event */
})();
/* ═══ END GLOBAL INPUT LENGTH CAP ═══ */
